SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

-- Table: public.subjects (1 INSERT statement(s))
ON CONFLICT DO NOTHING;

-- Table: public.exercises (1 INSERT statement(s))
ON CONFLICT DO NOTHING;

-- Table: public.tasks (1 INSERT statement(s))
ON CONFLICT DO NOTHING;

-- Table: public.math_solution_steps (1 INSERT statement(s))
ON CONFLICT DO NOTHING;

-- Table: public.learning_materials (1 INSERT statement(s))
ON CONFLICT DO NOTHING;

-- Table: public.trainer_exams (1 INSERT statement(s))
ON CONFLICT DO NOTHING;

-- Table: public.badges (1 INSERT statement(s))
ON CONFLICT DO NOTHING;

-- Sequenzen synchronisieren, damit lokale UI-Inserts keine PK-Konflikte erzeugen
SELECT pg_catalog.setval(pg_get_serial_sequence('public.subjects', 'id'), COALESCE((SELECT MAX(id) FROM public.subjects), 1), true);
SELECT pg_catalog.setval(pg_get_serial_sequence('public.exercises', 'id'), COALESCE((SELECT MAX(id) FROM public.exercises), 1), true);
SELECT pg_catalog.setval(pg_get_serial_sequence('public.tasks', 'id'), COALESCE((SELECT MAX(id) FROM public.tasks), 1), true);
SELECT pg_catalog.setval(pg_get_serial_sequence('public.learning_materials', 'id'), COALESCE((SELECT MAX(id) FROM public.learning_materials), 1), true);
SELECT pg_catalog.setval(pg_get_serial_sequence('public.badges', 'id'), COALESCE((SELECT MAX(id) FROM public.badges), 1), true);
