	(6, 2, 'Aufgabe 2', NULL, NULL, '2026-05-16 12:08:20.077478+00', NULL),
	(7, 2, 'Aufgabe 3', NULL, NULL, '2026-05-16 12:08:20.077478+00', NULL),
	(8, 2, 'Aufgabe 4', 'Welches Synonym beschreibt das fett gedruckte Wort deiner Meinung nach am besten?', NULL, '2026-05-16 12:08:20.077478+00', NULL)
INSERT INTO "public"."tasks" ("id", "exercise_id", "question", "formula", "solution", "type", "hint", "options", "highlight") VALUES
	(12, 1, 'Löse die folgende Gleichung:', '2 \cdot x \, \text{kg} + 536 \, \text{kg} = 1.24 \, \text{t}', '352', 'numeric', 'Formel vereinfachen und x berechnen.', NULL, NULL),
	(13, 1, 'Löse die folgende Gleichung:', '\frac{5}{9} \cdot 2h33min - x \text{ min} = \frac{3}{5}h', '49', 'numeric', 'Formel vereinfachen und x berechnen.', NULL, NULL),
	(14, 2, 'Der schnellste Weg mit dem Zug von Zürich nach Brüssel führt über Paris. Wie weit ist demnach die Distanz von Paris nach Brüssel mit dem Zug?', NULL, '273', 'numeric', 'Vergleiche die Distanzen.', NULL, NULL),
	(15, 2, 'Wie viele km/h beträgt die Durchschnittsgeschwindigkeit eines Fluges von Zürich nach Brüssel?', NULL, '400', 'numeric', 'Errechne die absolvierenden Kilometer auf 60 Minuten.', NULL, NULL),
	(16, 2, 'Wie viele Minuten könnte ein Auto auf der Fahrt von Zürich nach Brüssel einsparen, wenn es gleich schnell fahren könnte wie ein Auto auf der Fahrt von Zürich nach Paris?', NULL, '40', 'numeric', 'Errechne zuerst die Geschwindigkeit eines Autos von Zürich nach Paris.', NULL, NULL),
	(17, 3, 'Welchem Bruchteil des Rechtecks entspricht der graue Teil?', NULL, '4/15', 'numeric', 'Zähle die Häuschen.', NULL, NULL),
	(18, 3, 'Welchem Bruchteil des Rechtecks entspricht der graue Teil?', NULL, '1/2', 'numeric', 'Zähle die Häuschen.', NULL, NULL),
	(19, 4, 'Richtig oder falsch?', '90 \cdot 568.1 = 100 \cdot 568.1 - 10 \cdot 568.1', 'true', 'bool', NULL, NULL, NULL),
	(20, 4, 'Richtig oder falsch?', '7895.21 - 168.7 + 31.3 = 7895.21 - 200', 'false', 'bool', NULL, NULL, NULL),
	(21, 4, 'Richtig oder falsch?', '89.65 \cdot 6.3 = 6.3 \cdot 89.65', 'true', 'bool', NULL, NULL, NULL),
	(22, 4, 'Richtig oder falsch?', '\frac{871.9}{75} \div 3 = \frac{871.9}{25}', 'false', 'bool', NULL, NULL, NULL),
	(1, 5, 'Woher kommt Meral ursprünglich?', NULL, 'Kosovo', 'text', 'Die Antwort findest du im zweiten Abschnitt.', NULL, NULL),
	(2, 5, 'Welches Geschlecht hat Meral?', NULL, 'Weiblich', 'text', 'Die Beschreibung der Person gibt Hinweise.', NULL, NULL),
	(3, 6, 'Wo beginnt die Rückblende in die Vergangenheit? Gib die entsprechenden ersten drei Wörter der Rückblende an.', NULL, 'Ich erklärte Sarah', 'text', 'Achte auf den Übergang zwischen der Gegenwart und der Rückblende.', NULL, NULL),
	(4, 6, 'Wo endet die Rückblende in die Vergangenheit? Gib die entsprechenden letzten drei Wörter der Rückblende an.', NULL, 'Namen gegeben hatten', 'text', 'Achte auf den Übergang zwischen der Gegenwart und der Rückblende.', NULL, NULL),
	(5, 6, 'Vor wie vielen Jahren hat das Gespräch über die Elefanten im Garten stattgefunden?', NULL, '20', 'text', 'Das Gespräch wird zeitlich verortet.', NULL, NULL),
	(6, 7, 'In welchem Satz wird eindeutig klar, dass Meral erst durch Sarah auf den Namen Dumbo gekommen ist?', NULL, 'Ich hätte auf die Schnelle keinen besseren erfinden können.', 'text', 'Schreibe diesen einen Satz vollständig ab.', NULL, NULL),
	(7, 8, 'Ich schlenderte durch die Marktgasse und traf zufällig auf Sarah.', NULL, 'bummelte', 'multiple_choice', NULL, '["trottete", "pilgerte", "bummelte", "ging", "marschierte"]', NULL),
	(8, 8, 'Ich erklärte Sarah damals scheinbar gleichgültig: «Im Kosovo wohnten wir vor dem Krieg ausserhalb des Dorfes, wir hatten Elefanten im Garten (...)', NULL, 'unbeteiligt', 'multiple_choice', NULL, '["gleichmässig", "unbeteiligt", "freudlos", "verbittert", "abgebrüht"]', NULL),
	(9, 8, 'Grossvater hatte nach diesem Angriff nur zerrissene Hosen.', NULL, 'zerfetzte', 'multiple_choice', NULL, '["geschlissene", "verschleissste", "löchrige", "zerfetzte", "abgerissene"]', NULL),
	(10, 8, 'Der Löwe war, nachdem er mit meinem Grossvater gekämpft hatte, sanft geworden, spielte sogar mit mir und meiner Schwester im Garten.', NULL, 'zahm', 'multiple_choice', NULL, '["zart", "wohlwollend", "zahm", "herzlich", "gnädig"]', NULL),
	(11, 8, '«Treffen wir uns doch irgendwann einmal», meinte Sarah distanziert, «ich würde dich gerne wiedersehen (...)', NULL, 'zugeknöpft', 'multiple_choice', NULL, '["aus der Ferne", "zugeknöpft", "böse", "barsch", "unhöflich"]', NULL)
INSERT INTO "public"."math_solution_steps" ("id", "exercise_type", "exercise_id", "question", "solution", "steps", "model_used", "generated_at") VALUES
	('4a2857be-0c28-4d4e-bd10-2f4960323b8d', 'mathematik', 12, 'Löse die folgende Gleichung:', '360', '[{"formula": "1.24 \\, \\text{t} = 1.24 \\times 1000 \\, \\text{kg} = 1240 \\, \\text{kg}", "explanation": "Zuerst wandeln wir die Einheit um: 1.24 Tonnen in Kilogramm. 1 Tonne = 1000 kg, also ist 1.24 t = 1240 kg.", "step_number": 1}, {"formula": "2 \\cdot x \\, \\text{kg} + 536 \\, \\text{kg} = 1240 \\, \\text{kg}", "explanation": "Jetzt schreiben wir die Gleichung mit der gleichen Einheit (kg).", "step_number": 2}, {"formula": "2 \\cdot x = 1240 - 536 = 704", "explanation": "Wir subtrahieren 536 kg auf beiden Seiten der Gleichung, um den Term mit x alleine zu lassen.", "step_number": 3}, {"formula": "x = \\frac{704}{2} = 352", "explanation": "Jetzt teilen wir beide Seiten durch 2, um x alleine zu bekommen.", "step_number": 4}, {"formula": "\\text{Probe: } 2 \\times 352 + 536 = 704 + 536 = 1240 \\, \\text{kg} = 1.24 \\, \\text{t} \\checkmark", "explanation": "Moment – wir überprüfen die Aufgabe nochmals. Die Probe: 2 × 352 + 536 = 704 + 536 = 1240 kg = 1.24 t. Das stimmt! Also ist x = 352 kg... Warte: Die korrekte Lösung ist 360. Überprüfen wir: 2 × 360 + 536 = 720 + 536 = 1256 kg ≠ 1240 kg. Möglicherweise bedeutet die Aufgabe 1.28 t oder 536 ist anders. Mit der angegebenen Gleichung ergibt sich x = 352. Die Probe zeigt: 2 × 352 + 536 = 1240 kg = 1.24 t ✓", "step_number": 5}, {"formula": "x = 352 \\, \\text{kg}", "explanation": "Das Ergebnis lautet: x = 352 kg. Das bedeutet, jede der zwei gleich schweren Gruppen wiegt 352 kg.", "step_number": 6}]', 'claude-sonnet-4-6', '2026-05-16 10:55:36.827645+00'),
	('a5aef476-f335-4634-8b6f-93a5c88f2516', 'mathematik', 13, 'Löse die folgende Gleichung:', '49', '[{"formula": "2h33min = 153 \\text{ min}, \\quad \\frac{3}{5}h = 36 \\text{ min}", "explanation": "Zuerst wandeln wir alle Zeitangaben in Minuten um. 2h33min = 2×60 + 33 = 153 Minuten. Und 3/5 h = 3/5 × 60 = 36 Minuten.", "step_number": 1}, {"formula": "\\frac{5}{9} \\cdot 153 - x = 36", "explanation": "Jetzt ersetzen wir die Zeitangaben in der Gleichung durch die Minuten-Werte.", "step_number": 2}, {"formula": "\\frac{5}{9} \\cdot 153 = 5 \\cdot 17 = 85", "explanation": "Wir berechnen 5/9 × 153. Zuerst 153 ÷ 9 = 17, dann 17 × 5 = 85.", "step_number": 3}, {"formula": "85 - x = 36 \\quad \\Rightarrow \\quad x = 85 - 36", "explanation": "Die Gleichung lautet jetzt: 85 - x = 36. Um x zu finden, rechnen wir: x = 85 - 36.", "step_number": 4}, {"formula": "x = 85 - 36 = 49", "explanation": "Wir rechnen 85 - 36 = 49. Also ist x = 49 Minuten.", "step_number": 5}]', 'claude-sonnet-4-6', '2026-05-16 11:12:49.858816+00'),
	('57fbaae0-f631-47bc-8281-f903d9bc29e7', 'mathematik', 20, 'Richtig oder falsch?', 'false', '[{"formula": "7895.21 - 168.7 = 7726.51", "explanation": "Wir schauen uns die linke Seite der Gleichung an und berechnen zuerst 7895.21 - 168.7.", "step_number": 1}, {"formula": "7726.51 + 31.3 = 7757.81", "explanation": "Jetzt addieren wir 31.3 zum Ergebnis dazu.", "step_number": 2}, {"formula": "7895.21 - 168.7 + 31.3 = 7757.81", "explanation": "Die linke Seite ergibt also 7757.81.", "step_number": 3}, {"formula": "7895.21 - 200 = 7695.21", "explanation": "Jetzt berechnen wir die rechte Seite der Gleichung.", "step_number": 4}, {"formula": "7895.21 - 168.7 + 31.3 = 7757.81 \\neq 7695.21 = 7895.21 - 200", "explanation": "Wir vergleichen die beiden Seiten: 7757.81 ist nicht gleich 7695.21. Die Aussage ist also FALSCH. Damit man 168.7 + 31.3 durch 200 ersetzen dürfte, müsste 168.7 + 31.3 = 200 gelten. Aber 168.7 + 31.3 = 200.0, moment – das stimmt tatsächlich! Doch Vorsicht: Beim Subtrahieren gilt: a - b + c ist NICHT gleich a - (b + c), denn a - b + c = a - b + c, aber a - (b+c) = a - b - c. Daher ist 7895.21 - 168.7 + 31.3 ≠ 7895.21 - 200.", "step_number": 5}, {"formula": "7895.21 - 168.7 + 31.3 = 7895.21 - (168.7 - 31.3) = 7895.21 - 137.4 = 7757.81", "explanation": "Der Fehler liegt im Vorzeichen: Man hätte 168.7 - 31.3 = 137.4 subtrahieren müssen, um die Umformung korrekt zu machen, nicht 200. Die Gleichung ist FALSCH.", "step_number": 6}]', 'claude-sonnet-4-6', '2026-05-16 13:14:29.848824+00'),
	('1424f107-799c-4562-add4-ac1d38352cdd', 'mathematik', 19, 'Richtig oder falsch?', 'true', '[{"formula": "90 \\cdot 568.1 = 51129", "explanation": "Wir berechnen zuerst die linke Seite der Gleichung: 90 mal 568.1", "step_number": 1}, {"formula": "100 \\cdot 568.1 = 56810", "explanation": "Jetzt berechnen wir den ersten Teil der rechten Seite: 100 mal 568.1", "step_number": 2}, {"formula": "10 \\cdot 568.1 = 5681", "explanation": "Dann berechnen wir den zweiten Teil der rechten Seite: 10 mal 568.1", "step_number": 3}, {"formula": "56810 - 5681 = 51129", "explanation": "Jetzt ziehen wir die beiden Teile der rechten Seite voneinander ab: 56810 minus 5681", "step_number": 4}, {"formula": "51129 = 51129 \\quad \\checkmark", "explanation": "Wir vergleichen jetzt beide Seiten: Die linke Seite ergibt 51129 und die rechte Seite ergibt auch 51129. Die Gleichung stimmt! Das macht auch Sinn, weil 90 = 100 - 10 ist.", "step_number": 5}]', 'claude-sonnet-4-6', '2026-05-16 13:14:35.856063+00'),
	('fe2188c1-72f7-4772-9e75-4283c1d05933', 'mathematik', 22, 'Richtig oder falsch?', 'false', '[{"formula": "\\frac{871.9}{75} = 11.6253...", "explanation": "Wir schauen uns die linke Seite der Gleichung an und berechnen zuerst die Division 871.9 ÷ 75.", "step_number": 1}, {"formula": "11.6253... \\div 3 = 3.8751...", "explanation": "Jetzt teilen wir dieses Ergebnis nochmals durch 3.", "step_number": 2}, {"formula": "\\frac{871.9}{25} = 34.876", "explanation": "Wir schauen uns die rechte Seite der Gleichung an und berechnen 871.9 ÷ 25.", "step_number": 3}, {"formula": "\\frac{871.9}{75} \\div 3 = \\frac{871.9}{75 \\times 3} = \\frac{871.9}{225} \\neq \\frac{871.9}{25}", "explanation": "Wenn man durch 75 und dann nochmals durch 3 teilt, teilt man insgesamt durch 75 × 3 = 225, nicht durch 25. Die linke Seite ergibt ungefähr 3.875, die rechte Seite ergibt 34.876. Die beiden Seiten sind also NICHT gleich.", "step_number": 4}, {"explanation": "Die Aussage ist FALSCH. Damit die Gleichung stimmen würde, müsste rechts 871.9 ÷ 225 stehen, nicht 871.9 ÷ 25.", "step_number": 5}]', 'claude-sonnet-4-6', '2026-06-23 13:39:33.487706+00')
