INSERT INTO "public"."trainer_exams" ("id", "title", "subject", "year", "generated_by", "data", "text_lines", "created_at", "updated_at") VALUES
	('math-2023-claude', 'Mathematik 2023 (Langgymnasium)', 'Math', 2023, 'Claude Opus 4.5', '{"meta": {"time": "60 Minuten", "hints": ["Löse die Aufgaben direkt auf das Aufgabenblatt. Reicht der Platz bei einer Aufgabe nicht aus, fährst du auf der letzten Seite weiter.", "Du musst Ausrechnungen und Zwischenresultate aufschreiben, damit der Lösungsweg verständlich ist; sonst erhältst du keine Punkte.", "Antwortsätze sind nicht verlangt. Kennzeichne aber die Ergebnisse deutlich und notiere sie mit der passenden Masseinheit.", "Du darfst die Aufgaben in beliebiger Reihenfolge lösen.", "Bei Aufgabe 4 erhältst du für jedes richtig gesetzte Kreuz einen Punkt, für jedes falsch gesetzte Kreuz einen Punkt Abzug.", "Bei Aufgabe 6 darfst du das Netz weder ausschneiden noch nachbilden.", "Du darfst weder Taschenrechner noch andere elektronische Hilfsmittel verwenden."], "maxPoints": 36}, "questions": [{"id": "m23-1", "type": "input", "number": 1, "prompt": "Bestimme die fehlende Zahl im Kästchen.", "subTasks": [{"id": "m23-1-a", "label": "a)", "prompt": "$2 \\cdot \\square \\text{ kg} + 536\\text{ kg} = 1.24\\text{ t}$", "correctAnswer": 352}, {"id": "m23-1-b", "label": "b)", "prompt": "$\\left(\\frac{5}{9} \\text{ von } 2\\text{ h } 33\\text{ min}\\right) - \\square \\text{ min} = \\frac{3}{5}\\text{ h}$", "correctAnswer": 49}]}, {"id": "m23-2", "type": "input", "number": 2, "prompt": "Die folgende Tabelle zeigt die Distanzen und Zeiten für die jeweils schnellsten Verbindungen.", "context": "| | Zürich–Paris | | Zürich–Brüssel | |\\n|---|---|---|---|---|\\n| | Distanz | Reisezeit | Distanz | Reisezeit |\\n| Luftlinie | 488 km | – | 493 km | – |\\n| Flugzeug | 490 km | 1 h 15 min | 500 km | 1 h 15 min |\\n| Zug | 575 km | 4 h 10 min | 848 km | 6 h 50 min |\\n| Auto | 640 km | 6 h 40 min | 632 km | 7 h 15 min |", "subTasks": [{"id": "m23-2-a", "label": "a)", "prompt": "Der schnellste Weg mit dem Zug von Zürich nach Brüssel führt über Paris. Wie weit ist demnach die Distanz von Paris nach Brüssel mit dem Zug?", "suffix": "km", "correctAnswer": 273}, {"id": "m23-2-b", "label": "b)", "prompt": "Wie viele km/h beträgt die Durchschnittsgeschwindigkeit eines Fluges von Zürich nach Brüssel?", "suffix": "km/h", "correctAnswer": 400}, {"id": "m23-2-c", "label": "c)", "prompt": "Wie viele Minuten könnte ein Auto auf der Fahrt von Zürich nach Brüssel einsparen, wenn es gleich schnell fahren könnte wie ein Auto auf der Fahrt von Zürich nach Paris?", "suffix": "min", "correctAnswer": 40}]}]}', NULL, '2026-02-22 22:34:02.716537+00', '2026-02-22 22:34:02.716537+00'),
	('math-2024-claude', 'Mathematik 2024 (Langgymnasium)', 'Math', 2024, 'Claude Opus 4.5', '{"meta": {"time": "60 Minuten", "hints": ["Du darfst weder Taschenrechner noch andere elektronische Hilfsmittel verwenden."], "maxPoints": 36}, "questions": [{"id": "m24-1", "type": "input", "number": 1, "prompt": "Bestimme die fehlende Zahl.", "subTasks": [{"id": "m24-1-a", "label": "a)", "prompt": "$3 \\cdot \\square + 15 = 42$", "correctAnswer": 9}]}]}', NULL, '2026-02-22 22:36:13.175522+00', '2026-02-22 22:36:13.175522+00'),
	('math-2022-claude', 'Mathematik 2022 (Langgymnasium)', 'Math', 2022, 'Claude Opus 4.5', '{"meta": {"time": "60 Minuten", "hints": ["Du darfst weder Taschenrechner noch andere elektronische Hilfsmittel verwenden."], "maxPoints": 36}, "questions": [{"id": "m22-1", "type": "input", "number": 1, "prompt": "Berechne.", "subTasks": [{"id": "m22-1-a", "label": "a)", "prompt": "$25 + 17 = \\square$", "correctAnswer": 42}]}]}', NULL, '2026-02-22 22:36:13.175522+00', '2026-02-22 22:36:13.175522+00'),
	('german-2023-claude', 'Deutsch 2023 (Langgymnasium)', 'German', 2023, 'Claude Opus 4.5', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text sorgfältig durch."], "maxPoints": 51}, "questions": [{"id": "g23-1", "type": "input", "number": 1, "prompt": "Beantworte die Fragen zum Text.", "subTasks": [{"id": "g23-1a", "label": "a)", "prompt": "Woher kommt Meral ursprünglich?", "correctAnswer": "Kosovo"}]}]}', '{"Ich schlenderte durch die Marktgasse und traf zufällig auf Sarah.","Sie sah aus wie früher.","Wenn ich Sarah auch Ewigkeiten nicht mehr gesehen hatte, erkannte ich sie dennoch sofort wieder."}', '2026-02-22 22:36:13.175522+00', '2026-02-22 22:36:13.175522+00'),
	('german-2022-claude', 'Deutsch 2022 (Langgymnasium)', 'German', 2022, 'Claude Opus 4.5', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch. Du brauchst ihn zur Lösung der folgenden Aufgaben.", "Die Reihenfolge darfst du frei wählen.", "In den Aufgaben 3, 4, 8, 12, 13 und 14 führen Schreibfehler zu einem Punkteabzug.", "Du hast 45 Minuten Zeit."], "maxPoints": 47}, "questions": [{"id": "g22-1", "type": "input", "number": 1, "prompt": "Welche zwei unterschiedlichen gesundheitlichen Probleme des Kaufmanns werden in der Geschichte erwähnt? Nenne die beiden Begriffe, die im Text verwendet werden.", "subTasks": [{"id": "g22-1a", "label": "1.", "correctAnswer": "Gallenschmerzen"}, {"id": "g22-1b", "label": "2.", "correctAnswer": "Lungenentzündung"}]}, {"id": "g22-2", "type": "text-area", "number": 2, "prompt": "Auf Zeile 5 des Textes wird gesagt: «So kam also sozusagen der Geiz zum Geize.» Wer kommt hier eigentlich zu wem?", "subTasks": [{"id": "g22-2a", "label": "", "modelAnswer": "Der (geizige) Arzt/Doktor kommt zum (geizigen) Kaufmann."}]}, {"id": "g22-3", "type": "text-area", "number": 3, "prompt": "Der Kaufmann bereut es nachträglich, den Arzt um Hilfe gebeten zu haben. Nenne die zwei Überlegungen, die er sich im Text dazu macht. Formuliere in eigenen Worten und in je einem Satz.", "subTasks": [{"id": "g22-3a", "label": "1.", "modelAnswer": "Vielleicht wäre er auch ohne den Arzt gesund geworden."}, {"id": "g22-3b", "label": "2.", "modelAnswer": "Er hätte sich die Rechnung sparen können, wenn er nicht den Arzt gerufen hätte."}]}, {"id": "g22-4", "type": "text-area", "number": 4, "prompt": "Geiz und Sparsamkeit haben etwas gemeinsam. Aber Geiz wird anders wahrgenommen und bewertet als Sparsamkeit.", "subTasks": [{"id": "g22-4a", "label": "a)", "prompt": "Erkläre die Gemeinsamkeit zwischen Geiz und Sparsamkeit allgemein. Schreibe einen ganzen Satz. Arbeite nicht mit Beispielen.", "modelAnswer": "In beiden Fällen spart man / will man kein Geld ausgeben."}, {"id": "g22-4b", "label": "b)", "prompt": "Erkläre den inhaltlichen Unterschied in der Bewertung von Geiz und Sparsamkeit, indem du den Satz unten vervollständigst: Sparsamkeit wird __________ bewertet als Geiz.", "correctAnswer": "positiver"}]}, {"id": "g22-5", "rows": [{"id": "r1", "text": "Der Kaufmann verschliesst die gefüllten Dosen."}, {"id": "r2", "text": "Der Kaufmann beschriftet die Deckel."}, {"id": "r3", "text": "Der Kaufmann mischt Salz bei."}, {"id": "r4", "text": "Der Kaufmann holt die Bohnen aus dem Keller."}, {"id": "r5", "text": "Der Kaufmann hat eine zündende Idee."}, {"id": "r6", "text": "Der Kaufmann kocht die Fisch-Eier."}, {"id": "r7", "text": "Der Kaufmann importiert die Linsen aus Russland."}], "type": "table-select", "number": 5, "prompt": "Lies die Zeilen 8-16 nochmals. Stimmen die Aussagen in der Tabelle mit der Handlung in den Zeilen überein? Setze das Kreuz bei «ja» oder «nein». Falsch gesetzte Kreuze geben Abzug.", "columns": [{"id": "nein", "label": "nein"}, {"id": "ja", "label": "ja"}], "subTasks": [{"id": "g22-5a", "label": ""}], "correctTableAnswers": {"r1": "ja", "r2": "nein", "r3": "ja", "r4": "nein", "r5": "ja", "r6": "nein", "r7": "nein"}}, {"id": "g22-6", "rows": [{"id": "r1", "text": "Der Kaufmann ist älter als der Doktor."}, {"id": "r2", "text": "Es ist nicht bekannt, wann genau die Geschichte spielt."}, {"id": "r3", "text": "Kaviar besteht ausschliesslich aus roten Fischeiern."}, {"id": "r4", "text": "Der Kaufmann geht listig vor."}, {"id": "r5", "text": "Keine Person in der Geschichte weiss, dass anstelle von Kaviar Linsen in den Dosen sind."}, {"id": "r6", "text": "Die Verwandten sind traurig darüber, dass der Doktor gestorben ist."}, {"id": "r7", "text": "Der Kaufmann stirbt, weil er den Arzt nicht gerufen hat."}, {"id": "r8", "text": "Die Magd hält den Kaufmann für geizig."}], "type": "table-select", "number": 6, "prompt": "Kreuze bei den folgenden Sätzen an, ob sie mit den Aussagen des Textes übereinstimmen (!) oder nicht (–). Setze das Kreuz beim Fragezeichen (?), wenn das nicht entschieden werden kann. Es darf nur ein Kreuz pro Zeile gesetzt werden.", "columns": [{"id": "stimmt", "label": "!"}, {"id": "stimmt-nicht", "label": "–"}, {"id": "unklar", "label": "?"}], "subTasks": [{"id": "g22-6a", "label": ""}], "correctTableAnswers": {"r1": "unklar", "r2": "stimmt", "r3": "stimmt-nicht", "r4": "stimmt", "r5": "stimmt-nicht", "r6": "stimmt-nicht", "r7": "stimmt", "r8": "unklar"}}, {"id": "g22-7", "type": "input", "number": 7, "prompt": "Das Wort «Gold» wird im Text dreimal verwendet, und zwar auf den Zeilen 13, 24 und 34. Aber nur einmal ist mit «Gold» tatsächlich echtes Gold gemeint, während zweimal nur eine Eigenschaft von Gold als Vergleich eingesetzt wird. Schreibe «echt» auf die freie Linie beim Satz, wo echtes Gold gemeint ist, und nenne in den anderen beiden Fällen die Eigenschaft von Gold, welche für den Vergleich genutzt wird.", "subTasks": [{"id": "g22-7a", "label": "a)", "prompt": "«Bester russischer Kaviar – schwarzes Gold – Mindestgrösse 3 mm war auf den Dosen gut zu lesen.» (Z. 13)", "modelAnswer": "der hohe Wert / die Kostbarkeit"}, {"id": "g22-7b", "label": "b)", "prompt": "«Der Doktor bewunderte die Dosen, die glänzten wie Gold.» (Z. 23-24)", "modelAnswer": "der Glanz / die Farbe"}, {"id": "g22-7c", "label": "c)", "prompt": "«Sie holten den Kaviar zur Krönung des Festes aus dem Keller und füllten ihn in eine Schale aus Gold.» (Z. 33-34)", "correctAnswer": "echt"}]}, {"id": "g22-8", "type": "text-area", "number": 8, "prompt": "Lies die Zeilen 23 bis 30 noch einmal. In dieser Passage täuscht sich der Doktor gleich zweimal. Erkläre diese beiden Fehleinschätzungen in jeweils einem ganzen Satz.", "subTasks": [{"id": "g22-8a", "label": "1.", "modelAnswer": "Der Doktor nimmt an, in seinem Keller sei echter Kaviar / er sei reich beschenkt worden."}, {"id": "g22-8b", "label": "2.", "modelAnswer": "Der Doktor denkt, der Kaufmann sei nicht geizig / habe zu Unrecht einen schlechten Ruf."}]}, {"id": "g22-9", "rows": [{"id": "r1", "text": "Menschen lassen sich austricksen."}, {"id": "r2", "text": "Man soll Genuss nicht aufschieben."}, {"id": "r3", "text": "Der Ruf eines Menschen kann täuschen."}, {"id": "r4", "text": "Lügen haben kurze Beine."}, {"id": "r5", "text": "Wertloses kann wertvoll sein."}, {"id": "r6", "text": "Wertvolles kann wertlos sein."}, {"id": "r7", "text": "Geiz lohnt sich nicht."}], "type": "table-select", "number": 9, "prompt": "Die Personen machen im Verlauf der Geschichte verschiedene Erfahrungen. Kreuze an: Wer macht welche Erfahrung(en)? Setze das Kreuz bei «niemand», wenn keine Person in der Geschichte die entsprechende Erfahrung macht. Es darf nur ein Kreuz pro Zeile gesetzt werden.", "columns": [{"id": "kaufmann", "label": "Kaufmann"}, {"id": "doktor", "label": "Doktor"}, {"id": "erben", "label": "Erben"}, {"id": "niemand", "label": "niemand"}], "subTasks": [{"id": "g22-9a", "label": ""}], "correctTableAnswers": {"r1": "kaufmann", "r2": "erben", "r3": "doktor", "r4": "niemand", "r5": "doktor", "r6": "erben", "r7": "niemand"}}, {"id": "g22-10", "type": "multiple-choice", "number": 10, "prompt": "Kreuze jeweils nur die Lösung an, die der Bedeutung der fett gedruckten Wörter und Ausdrücke am besten entspricht. Deine Lösung muss inhaltlich zum Text passen.", "subTasks": [{"id": "g22-10a", "label": "a)", "prompt": "«Der war genauso **wohlhabend** wie geizig.» (Z. 1)", "options": ["wohlgenährt", "rechthaberisch", "wohlständig", "reich", "glücklich"], "correctAnswer": "reich"}, {"id": "g22-10b", "label": "b)", "prompt": "«Er überlegte sich, wie er es **einfädeln** könnte...» (Z. 9-10)", "options": ["einrichten", "anrichten", "kommunizieren", "vorstellen", "versichern"], "correctAnswer": "einrichten"}, {"id": "g22-10c", "label": "c)", "prompt": "«Nicht lange danach **segnete der Doktor selbst das Zeitliche**.» (Z. 31)", "options": ["machte das Kreuzzeichen", "gab jemandem den Segen", "schied aus dem Leben", "wurde heilig", "genoss die Zeit"], "correctAnswer": "schied aus dem Leben"}, {"id": "g22-10d", "label": "d)", "prompt": "«Alle bissen **herzhaft** hinein.» (Z. 35)", "options": ["herzlich", "halbherzig", "warmherzig", "mit Herzenslust", "grossherzig"], "correctAnswer": "mit Herzenslust"}, {"id": "g22-10e", "label": "e)", "prompt": "«Sein **Wappenschild** blieb fleckenlos oder wenigstens sah man die Flecken nicht!» (Z. 38-39)", "options": ["Firmenlogo", "Ruf", "Firmenschild", "Bekanntheit", "Verteidigung"], "correctAnswer": "Ruf"}]}, {"id": "g22-11", "type": "multiple-choice", "number": 11, "prompt": "Kreuze jeweils an, worauf sich das fett gedruckte Wort inhaltlich bezieht. Lies die Stellen im Text nochmals durch und kreuze nur eine Lösung an. Die Lösung muss inhaltlich zum Text passen.", "subTasks": [{"id": "g22-11a", "label": "a)", "prompt": "«Der Doktor wendete alle Geschicklichkeit auf, den Kranken zu heilen, und es gelang. Die Freude des Kaufmanns **darüber** war allerdings getrübt.» (Z. 5-6)", "options": ["die Heilung", "die hohe Rechnung", "die Gallensteine", "den Geiz des Doktors", "die Geschicklichkeit des Doktors"], "correctAnswer": "die Heilung"}, {"id": "g22-11b", "label": "b)", "prompt": "«Dann füllte er alles fein säuberlich in die Dosen und schraubte **deren** beschriftete Deckel gut zu, sodass sie wie ungeöffnet wirkten.» (Z. 15-16)", "options": ["Firmenwappen", "Deckel", "Dosen", "Kaufmann", "Kaviar"], "correctAnswer": "Dosen"}, {"id": "g22-11c", "label": "c)", "prompt": "«Den geizigen Doktor werde es reuen, den teuren Kaviar selbst zu verzehren oder **ihn** gar seinen sowieso seltenen Gästen vorzusetzen – für ihn und erst recht für Letztere reichte ein Käsebrötchen vollends.» (Z. 21-23)", "options": ["Doktor", "Reue", "Kaufmann", "Gäste", "Kaviar"], "correctAnswer": "Kaviar"}, {"id": "g22-11d", "label": "d)", "prompt": "«Den geizigen Doktor werde es reuen, den teuren Kaviar selbst zu verzehren oder ihn gar seinen sowieso seltenen Gästen vorzusetzen – für ihn und erst recht für **Letztere** reichte ein Käsebrötchen vollends.» (Z. 21-23)", "options": ["Doktor", "Kaviar", "Gäste", "Kaufmann", "Käsebrötchen"], "correctAnswer": "Gäste"}]}, {"id": "g22-12", "type": "text-area", "number": 12, "prompt": "Beantworte die folgenden Fragen zur Textstelle.", "context": "Auf Z. 29-30 heisst es: «Wie unrecht hatte man dem Kaufmann immer getan, ihn geizig zu nennen. Er, der Doktor, wusste es besser!»", "subTasks": [{"id": "g22-12a", "label": "a)", "prompt": "Erkläre in einem ganzen Satz, warum der zweite Satz der oben angegebenen Textstelle nicht einfach lauten kann: «Er wusste es besser!»", "modelAnswer": "Es wäre/ist nicht klar, ob sich «er» auf den Kaufmann oder den Doktor bezieht."}, {"id": "g22-12b", "label": "b)", "prompt": "«Sie holten den Kaviar zur Krönung des Festes ...» (Z. 33-34). Formuliere diesen Satz so um, dass er gleich aufgebaut ist wie: «Er, der Doktor, wusste es besser!»", "correctAnswer": "Sie, die Erben, holten den Kaviar zur Krönung des Festes."}]}, {"id": "g22-13", "type": "input", "number": 13, "prompt": "Bilde ausgehend vom Wortstamm (Stamm-Morphem) der fett gedruckten Wörter ein neues Wort aus derselben Wortfamilie, das in die Lücke passt. Es darf nur ein einziges Wort pro Lücke eingesetzt werden und die Bedeutung des rechten Satzes muss mit der des linken Satzes übereinstimmen.", "subTasks": [{"id": "g22-13a", "label": "a)", "prompt": "Der Kaufmann **litt** an Gallenschmerzen. → Sein schmerzhaftes __________ wurde von der Galle verursacht.", "correctAnswer": "Leiden"}, {"id": "g22-13b", "label": "b)", "prompt": "Der Doktor **wendete** alle Geschicklichkeit auf, den Kranken zu heilen. → Unter __________ aller Geschicklichkeit gelang es dem Doktor, den Kranken zu heilen.", "correctAnswer": "Anwendung"}, {"id": "g22-13c", "label": "c)", "prompt": "Seine Behandlung war am Schluss mit **Erfolg** gesegnet. → Die Behandlung war zu guter Letzt __________.", "correctAnswer": "erfolgreich"}, {"id": "g22-13d", "label": "d)", "prompt": "Er starb, weil ihm die Behandlung der Lungenentzündung überflüssig **erschien**. → Er starb, weil der __________ getrogen hatte.", "correctAnswer": "Schein"}, {"id": "g22-13e", "label": "e)", "prompt": "Sein Wappenschild blieb **fleckenlos**. → Sein Wappenschild blieb __________.", "correctAnswer": "unbefleckt"}]}, {"id": "g22-14", "type": "input", "number": 14, "prompt": "Bilde die verlangten Verbformen und schreibe sie fehlerfrei.", "context": "Fülle die Tabelle mit den korrekten Verbformen aus.", "subTasks": [{"id": "g22-14a1", "label": "laden – Präsens, 2. Person Plural", "correctAnswer": "ladet"}, {"id": "g22-14a2", "label": "laden – Präteritum, 3. Person Singular", "correctAnswer": "lud"}, {"id": "g22-14b1", "label": "sein – Präsens, 2. Person Plural", "correctAnswer": "seid"}, {"id": "g22-14b2", "label": "sein – Präteritum, 3. Person Singular", "correctAnswer": "war"}, {"id": "g22-14c1", "label": "lassen – Präsens, 2. Person Plural", "correctAnswer": "lasst"}, {"id": "g22-14c2", "label": "lassen – Präteritum, 3. Person Singular", "correctAnswer": "liess"}, {"id": "g22-14d1", "label": "schaffen – Präsens, 2. Person Plural", "correctAnswer": "schafft"}, {"id": "g22-14d2", "label": "schaffen – Präteritum, 3. Person Singular", "correctAnswer": "schaffte"}, {"id": "g22-14e1", "label": "setzen – Präsens, 2. Person Plural", "correctAnswer": "setzt"}, {"id": "g22-14e2", "label": "setzen – Präteritum, 3. Person Singular", "correctAnswer": "setzte"}]}, {"id": "g22-15", "type": "input", "number": 15, "prompt": "Ersetze bei den folgenden Begriffen jeweils den ersten Wortbaustein so, dass die gegenteilige Bedeutung entsteht. Jeder Wortbaustein darf nur einmal verwendet werden.", "context": "Wortbausteine: **aus-, zu-, miss-, ab-, ent-, a-, tief-, bös-, un-, de-, be-**", "subTasks": [{"id": "g22-15a", "label": "a)", "prompt": "bewaffnen →", "correctAnswer": "entwaffnen"}, {"id": "g22-15b", "label": "b)", "prompt": "gelingen →", "correctAnswer": "misslingen"}, {"id": "g22-15c", "label": "c)", "prompt": "verpacken →", "correctAnswer": "auspacken"}, {"id": "g22-15d", "label": "d)", "prompt": "hochmütig →", "correctAnswer": "demütig"}, {"id": "g22-15e", "label": "e)", "prompt": "absagen →", "correctAnswer": "zusagen"}]}]}', '{"In einer schwäbischen Stadt lebte ein Kaufmann. Der war genauso wohlhabend wie geizig, und beides fällt ja","gern zusammen. Dieser Kaufmann litt öfter an Gallenschmerzen und einmal waren diese besonders schlimm.","Trotzdem liess er erst nach langem Zögern einen Arzt rufen, weil er die Kosten fürchtete. Dieser Doktor aber","gehörte ebenfalls nicht zu den verschwenderisch Freigebigen und war für seine Knausrigkeit ebenso bekannt","wie der Kaufmann. So kam also sozusagen der Geiz zum Geize. Der Doktor wendete alle Geschicklichkeit auf,","den Kranken zu heilen, und es gelang. Die Freude des Kaufmanns darüber war allerdings getrübt durch den","Gedanken an die hohe Rechnung, die der Doktor nun bestimmt bald stellen würde.","«Hätte ich diesen nur nicht so voreilig gerufen», dachte sich der Kaufmann. «Vielleicht wäre ich ja ganz von","allein wieder gesund geworden und hätte das Geld für den Arzt sparen können.» Er zerbrach sich lange den","Kopf, wie er es einfädeln könnte, vom geldgierigen Doktor nicht allzu sehr zur Kasse gebeten zu werden. Da","kam ihm endlich ein rettender Einfall.","Er hatte nämlich, da er natürlich alles aufhob, ein Dutzend leerer Kaviardosen im Keller stehen. Bester russischer Kaviar – schwarzes Gold – Mindestgrösse 3 mm war auf den Dosen gut zu lesen. Schnell kochte er eine","Portion kleiner schwarzer Linsen, die aussahen wie diese köstlichen Fischeier, und fügte der Haltbarkeit wegen","eine grosszügige Portion Salz hinzu. Dann füllte er alles fein säuberlich in die Dosen und schraubte deren","beschriftete Deckel gut zu, sodass sie wie ungeöffnet wirkten.","Das Dutzend Dosen schickte er, noch bevor er eine Rechnung von ihm bekommen hatte, schön in ein Kistchen","verpackt, dem Doktor. Dazu legte er einen höflichen und schmeichlerischen Brief, in dem er schrieb, der Doktor","sei, wie er wisse, ein Kenner und werde den Kaviar zu schätzen wissen. Dieser sei eigentlich ein Luxus für","Herzöge und Erzbischöfe, aber seine Dankbarkeit für die gelungene Heilung sei gross und nichts sei ihm zu","teuer in solch einem Fall. Die Überlegung des Kaufmanns war nämlich diese: Den geizigen Doktor werde es","reuen, den teuren Kaviar selbst zu verzehren oder ihn gar seinen sowieso seltenen Gästen vorzusetzen – für ihn","und erst recht für Letztere reichte ein Käsebrötchen vollends. Und so geschah es auch: Der Doktor bewunderte","die Dosen, die glänzten wie Gold, bedankte sich umständlich bei dem Geber und liess das Geschenk durch","seine Magd in den Keller schaffen, um es für eine besondere Gelegenheit aufzusparen.","Die Jahre vergingen. Der Kaufmann starb, und zwar nicht an seinem Gallenleiden. Eine Lungenentzündung,","zu deren Behandlung er es nicht für nötig gehalten hatte, den Doktor herbeizurufen, raffte ihn hinweg. Der","Doktor ging trotzdem zu seiner Beerdigung und dachte, während der Sarg in die Tiefe sank, an die zwölf Dosen","mit bestem Kaviar in seinem Keller. Wie unrecht hatte man dem Kaufmann immer getan, ihn geizig zu nennen.","Er, der Doktor, wusste es besser!","Nicht lange danach segnete der Doktor selbst das Zeitliche, betrauert nur von seiner alten Magd. Die Erben,","entfernte Verwandte, organisierten einen grossen Leichenschmaus, bei dem sie so üppig assen und tranken,","dass der Doktor sich im Grab umgedreht hätte, wenn es ihm möglich gewesen wäre zuzuschauen. Sie holten","den Kaviar zur Krönung des Festes aus dem Keller und füllten ihn in eine Schale aus Gold. Als sie ihre Brötchen","mit dem immer noch schwarz glänzenden Kaviar bestrichen hatten, bissen alle herzhaft hinein. Doch ebenso","schnell husteten und verschluckten sie sich. Ja, einige spuckten den Kaviar sogar auf das weisse Tischtuch – so","faulig und verdorben schmeckte er. Trotzdem – für Linsen hielt den Kaviar keiner! Und obwohl sie von der","Magd dann erfuhren, dass der Kaviar ein Geschenk des schon lange toten Kaufmanns gewesen war – sein","Wappenschild blieb fleckenlos oder wenigstens sah man den Flecken nicht!","Die Erben beschlossen übrigens nach dieser Erfahrung, ihnen sollte so etwas nicht geschehen; sie wollten ihren","Kaviar nicht zu lange lagern, denn, scherzten sie, alt zu werden bekommt nur den Menschen gut, nicht aber",Delikatessen!}', '2026-02-22 22:49:47.360812+00', '2026-02-22 22:49:47.360812+00'),
	('german-2022-gemini', 'Sprachprüfung Deutsch 2022 (Langgymnasium)', 'German', 2022, 'Gemini 3 Pro', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch.", "Die Reihenfolge darfst du frei wählen.", "In den Aufgaben 3, 4, 8, 12, 13 und 14 führen Schreibfehler zu einem Punkteabzug."], "maxPoints": 47}, "questions": [{"id": "g22-1", "type": "text-area", "number": 1, "prompt": "Welche zwei unterschiedlichen gesundheitlichen Probleme des Kaufmanns werden in der Geschichte erwähnt? Nenne die beiden Begriffe, die im Text verwendet werden.", "subTasks": [{"id": "g22-1a", "label": "Antwort:", "prompt": "Begriffe aus dem Text.", "modelAnswer": "Gallenschmerzen (Gallenleiden) und Lungenentzündung."}]}, {"id": "g22-2", "type": "text-area", "number": 2, "prompt": "Auf Zeile 5 des Textes wird gesagt: «So kam also sozusagen der Geiz zum Geize.» Wer kommt hier eigentlich zu wem?", "subTasks": [{"id": "g22-2a", "label": "Antwort:", "prompt": "Erkläre die Situation.", "modelAnswer": "Der (geizige) Arzt/Doktor kommt zum/besucht den (geizigen) Kaufmann."}]}, {"id": "g22-3", "type": "text-area", "number": 3, "prompt": "Der Kaufmann bereut es nachträglich, den Arzt um Hilfe gebeten zu haben. Nenne die zwei Überlegungen, die er sich im Text dazu macht.", "context": "Formuliere in eigenen Worten und in je einem Satz.", "subTasks": [{"id": "g22-3a", "label": "1.", "prompt": "Erste Überlegung:", "modelAnswer": "Vielleicht wäre er auch ohne den Arzt gesund geworden."}, {"id": "g22-3b", "label": "2.", "prompt": "Zweite Überlegung:", "modelAnswer": "Er hätte sich die Rechnung sparen können, wenn er nicht den Arzt gerufen hätte."}]}, {"id": "g22-4", "type": "input", "number": 4, "prompt": "Geiz und Sparsamkeit haben etwas gemeinsam. Aber Geiz wird anders wahrgenommen und bewertet als Sparsamkeit.", "subTasks": [{"id": "g22-4a", "label": "a)", "prompt": "Erkläre die Gemeinsamkeit zwischen Geiz und Sparsamkeit allgemein. Schreibe einen ganzen Satz. Arbeite nicht mit Beispielen.", "modelAnswer": "In beiden Fällen spart man (oder: will man kein Geld ausgeben)."}, {"id": "g22-4b", "label": "b)", "prompt": "Erkläre den inhaltlichen Unterschied in der Bewertung von Geiz und Sparsamkeit, indem du den Satz unten vervollständigst: Sparsamkeit wird", "suffix": "bewertet als Geiz.", "modelAnswer": "positiver / besser / höher", "correctAnswer": "positiver"}]}, {"id": "g22-5", "rows": [{"id": "r1", "text": "Der Kaufmann verschliesst die gefüllten Dosen."}, {"id": "r2", "text": "Der Kaufmann beschriftet die Deckel."}, {"id": "r3", "text": "Der Kaufmann mischt Salz bei."}, {"id": "r4", "text": "Der Kaufmann holt die Bohnen aus dem Keller."}, {"id": "r5", "text": "Der Kaufmann hat eine zündende Idee."}, {"id": "r6", "text": "Der Kaufmann kocht die Fisch-Eier."}, {"id": "r7", "text": "Der Kaufmann importiert die Linsen aus Russland."}], "type": "table-select", "number": 5, "prompt": "Lies die Zeilen 8-16 nochmals. Stimmen die Aussagen in der Tabelle mit der Handlung in den Zeilen überein?", "columns": [{"id": "c_nein", "label": "nein"}, {"id": "c_ja", "label": "ja"}], "context": "Setze das Kreuz bei «ja» oder «nein».", "subTasks": [{"id": "g22-5-sub", "label": "Tabelle", "prompt": "Kreuze an."}], "correctTableAnswers": {"r1": "c_ja", "r2": "c_nein", "r3": "c_ja", "r4": "c_nein", "r5": "c_ja", "r6": "c_nein", "r7": "c_nein"}}, {"id": "g22-6", "rows": [{"id": "r1", "text": "Der Kaufmann ist älter als der Doktor."}, {"id": "r2", "text": "Es ist nicht bekannt, wann genau die Geschichte spielt."}, {"id": "r3", "text": "Kaviar besteht ausschliesslich aus roten Fischeiern."}, {"id": "r4", "text": "Der Kaufmann geht listig vor."}, {"id": "r5", "text": "Keine Person in der Geschichte weiss, dass anstelle von Kaviar Linsen in den Dosen sind."}, {"id": "r6", "text": "Die Verwandten sind traurig darüber, dass der Doktor gestorben ist."}, {"id": "r7", "text": "Der Kaufmann stirbt, weil er den Arzt nicht gerufen hat."}, {"id": "r8", "text": "Die Magd hält den Kaufmann für geizig."}], "type": "table-select", "number": 6, "prompt": "Kreuze bei den folgenden Sätzen an, ob sie mit den Aussagen des Textes übereinstimmen (✓), nicht (-) oder ob es nicht entschieden werden kann (?).", "columns": [{"id": "c_true", "label": "✓"}, {"id": "c_false", "label": "-"}, {"id": "c_unknown", "label": "?"}], "subTasks": [{"id": "g22-6-sub", "label": "Tabelle", "prompt": "Kreuze an."}], "correctTableAnswers": {"r1": "c_unknown", "r2": "c_true", "r3": "c_false", "r4": "c_true", "r5": "c_false", "r6": "c_false", "r7": "c_unknown", "r8": "c_unknown"}}, {"id": "g22-7", "type": "input", "number": 7, "prompt": "Das Wort «Gold» wird im Text dreimal verwendet. Bestimme die Bedeutung.", "context": "Schreibe «echt» auf die Linie, wo echtes Gold gemeint ist, und nenne in den anderen Fällen die Eigenschaft, die für den Vergleich genutzt wird.", "subTasks": [{"id": "g22-7a", "label": "a)", "prompt": "«...schwarzes Gold...» (Z. 13)", "modelAnswer": "Der hohe Wert / die Kostbarkeit / das Luxuriöse / das Wertvolle"}, {"id": "g22-7b", "label": "b)", "prompt": "«...die glänzten wie Gold...» (Z. 23-24)", "modelAnswer": "Optisches: die Farbe / der Glanz / die Helligkeit / etwas Schönes"}, {"id": "g22-7c", "label": "c)", "prompt": "«...Schale aus Gold.» (Z. 33-34)", "modelAnswer": "echt", "correctAnswer": "echt"}]}, {"id": "g22-8", "type": "text-area", "number": 8, "prompt": "Lies die Zeilen 23 bis 30 noch einmal. In dieser Passage täuscht sich der Doktor gleich zweimal. Erkläre diese beiden Fehleinschätzungen in jeweils einem ganzen Satz.", "subTasks": [{"id": "g22-8a", "label": "1.", "prompt": "Fehleinschätzung «Wert des Geschenks»", "modelAnswer": "Der Doktor nimmt an, in seinem Keller sei echter Kaviar (oder: er sei reich beschenkt worden)."}, {"id": "g22-8b", "label": "2.", "prompt": "Fehleinschätzung «Charakter des Kaufmanns»", "modelAnswer": "Der Doktor denkt, der Kaufmann sei nicht geizig (oder: der Kaufmann werde zu Unrecht für geizig gehalten)."}]}, {"id": "g22-9", "rows": [{"id": "r1", "text": "Menschen lassen sich austricksen."}, {"id": "r2", "text": "Man soll Genuss nicht aufschieben."}, {"id": "r3", "text": "Der Ruf eines Menschen kann täuschen."}, {"id": "r4", "text": "Lügen haben kurze Beine."}, {"id": "r5", "text": "Wertloses kann wertvoll sein."}, {"id": "r6", "text": "Wertvolles kann wertlos sein."}, {"id": "r7", "text": "Geiz lohnt sich nicht."}], "type": "table-select", "number": 9, "prompt": "Die Personen machen im Verlauf der Geschichte verschiedene Erfahrungen. Kreuze an: Wer macht welche Erfahrung(en)?", "columns": [{"id": "c_kaufmann", "label": "Kaufmann"}, {"id": "c_doktor", "label": "Doktor"}, {"id": "c_erben", "label": "Erben"}, {"id": "c_niemand", "label": "niemand"}], "subTasks": [{"id": "g22-9-sub", "label": "Tabelle", "prompt": "Kreuze an."}], "correctTableAnswers": {"r1": "c_kaufmann", "r2": "c_erben", "r3": "c_doktor", "r4": "c_niemand", "r5": "c_kaufmann", "r6": "c_erben", "r7": "c_erben"}}, {"id": "g22-10", "type": "multiple-choice", "number": 10, "prompt": "Kreuze jeweils nur die Lösung an, die der Bedeutung der fett gedruckten Wörter und Ausdrücke am besten entspricht.", "subTasks": [{"id": "g22-10a", "label": "a)", "prompt": "«Der war genauso **wohlhabend** wie geizig.» (Z. 1)", "options": ["wohlgenährt", "rechthaberisch", "wohlständig", "reich", "glücklich"], "correctAnswer": "reich"}, {"id": "g22-10b", "label": "b)", "prompt": "«...wie er es **einfädeln** könnte...» (Z. 9-10)", "options": ["einrichten", "anrichten", "kommunizieren", "vorstellen", "versichern"], "correctAnswer": "einrichten"}, {"id": "g22-10c", "label": "c)", "prompt": "«Nicht lange danach **segnete** der Doktor selbst **das Zeitliche**.» (Z. 31)", "options": ["machte das Kreuzzeichen", "gab jemandem den Segen", "schied aus dem Leben", "wurde heilig", "genoss die Zeit"], "correctAnswer": "schied aus dem Leben"}, {"id": "g22-10d", "label": "d)", "prompt": "«Alle bissen **herzhaft** hinein.» (Z. 35)", "options": ["herzlich", "halbherzig", "warmherzig", "mit Herzenslust", "grossherzig"], "correctAnswer": "mit Herzenslust"}, {"id": "g22-10e", "label": "e)", "prompt": "«Sein **Wappenschild** blieb fleckenlos...» (Z. 38-39)", "options": ["Firmenlogo", "Ruf", "Firmenschild", "Bekanntheit", "Verteidigung"], "correctAnswer": "Ruf"}]}, {"id": "g22-11", "type": "multiple-choice", "number": 11, "prompt": "Kreuze jeweils an, worauf sich das fett gedruckte Wort inhaltlich bezieht.", "subTasks": [{"id": "g22-11a", "label": "a)", "prompt": "«...Die Freude des Kaufmanns **darüber** war allerdings getrübt.» (Z. 5-6)", "options": ["die Heilung", "die hohe Rechnung", "die Gallensteine", "den Geiz des Doktors", "die Geschicklichkeit des Doktors"], "correctAnswer": "die Heilung"}, {"id": "g22-11b", "label": "b)", "prompt": "«...und schraubte **deren** beschriftete Deckel gut zu...» (Z. 15-16)", "options": ["Firmenwappen", "Deckel", "Dosen", "Kaufmann", "Kaviar"], "correctAnswer": "Dosen"}, {"id": "g22-11c", "label": "c)", "prompt": "«...den teuren Kaviar selbst zu verzehren oder **ihn** gar seinen sowieso seltenen Gästen vorzusetzen...» (Z. 21-23)", "options": ["Doktor", "Reue", "Kaufmann", "Gäste", "Kaviar"], "correctAnswer": "Kaviar"}, {"id": "g22-11d", "label": "d)", "prompt": "«...für ihn und erst recht für **Letztere** reichte ein Käsebrötchen vollends.» (Z. 21-23)", "options": ["Doktor", "Kaviar", "Gäste", "Kaufmann", "Käsebrötchen"], "correctAnswer": "Gäste"}]}, {"id": "g22-12", "type": "input", "number": 12, "prompt": "Sprachbetrachtung: Grammatik", "subTasks": [{"id": "g22-12a", "label": "a)", "prompt": "Erkläre in einem ganzen Satz, warum der Satz «Er, der Doktor, wusste es besser!» nicht einfach «Er wusste es besser!» lauten kann.", "modelAnswer": "Es wäre nicht klar, ob sich «er» auf den Kaufmann oder den Doktor bezieht."}, {"id": "g22-12b", "label": "b)", "prompt": "Formuliere den Satz «Sie holten den Kaviar zur Krönung des Festes...» so um, dass er gleich aufgebaut ist wie «Er, der Doktor, wusste es besser!»:", "modelAnswer": "Sie, die Erben, holten den Kaviar zur Krönung des Festes."}]}, {"id": "g22-13", "type": "input", "number": 13, "prompt": "Bilde ausgehend vom Wortstamm der fett gedruckten Wörter ein neues Wort aus derselben Wortfamilie, das in die Lücke passt.", "subTasks": [{"id": "g22-13a", "label": "a)", "prompt": "Der Kaufmann litt an Gallenschmerzen. -> Sein schmerzhaftes", "suffix": "wurde von der Galle verursacht.", "modelAnswer": "Leiden", "correctAnswer": "Leiden"}, {"id": "g22-13b", "label": "b)", "prompt": "Der Doktor wendete alle Geschicklichkeit auf. -> Unter Anwendung aller", "suffix": "gelang es dem Doktor, den Kranken zu heilen.", "modelAnswer": "Geschicklichkeit", "correctAnswer": "Geschicklichkeit"}, {"id": "g22-13c", "label": "c)", "prompt": "Seine Behandlung war mit Erfolg gesegnet. -> Die Behandlung war zu guter Letzt", "modelAnswer": "erfolgreich / erfolgsgekrönt", "correctAnswer": "erfolgreich"}, {"id": "g22-13d", "label": "d)", "prompt": "Behandlung der Lungenentzündung erschien überflüssig. -> Er starb, weil der", "suffix": "getrogen hatte.", "modelAnswer": "Schein", "correctAnswer": "Schein"}, {"id": "g22-13e", "label": "e)", "prompt": "Sein Wappenschild blieb fleckenlos. -> Sein Wappenschild blieb", "modelAnswer": "unbefleckt", "correctAnswer": "unbefleckt"}]}, {"id": "g22-14", "type": "input", "number": 14, "prompt": "Bilde die verlangten Verbformen und schreibe sie fehlerfrei.", "subTasks": [{"id": "g22-14a", "label": "laden", "prompt": "Präsens, 2. Pers. Plural: ihr", "correctAnswer": "ladet"}, {"id": "g22-14b", "label": "laden", "prompt": "Präteritum, 3. Pers. Singular: er", "correctAnswer": "lud"}, {"id": "g22-14c", "label": "sein", "prompt": "Präsens, 2. Pers. Plural: ihr", "correctAnswer": "seid"}, {"id": "g22-14d", "label": "sein", "prompt": "Präteritum, 3. Pers. Singular: es", "correctAnswer": "war"}, {"id": "g22-14e", "label": "lassen", "prompt": "Präsens, 2. Pers. Plural: ihr", "correctAnswer": "lasst"}, {"id": "g22-14f", "label": "lassen", "prompt": "Präteritum, 3. Pers. Singular: er", "correctAnswer": "liess"}, {"id": "g22-14g", "label": "schaffen", "prompt": "Präsens, 2. Pers. Plural: ihr", "correctAnswer": "schafft"}, {"id": "g22-14h", "label": "schaffen", "prompt": "Präteritum, 3. Pers. Singular: sie", "modelAnswer": "schaffte / schuf", "correctAnswer": "schaffte"}, {"id": "g22-14i", "label": "setzen", "prompt": "Präsens, 2. Pers. Plural: ihr", "correctAnswer": "setzt"}, {"id": "g22-14j", "label": "setzen", "prompt": "Präteritum, 3. Pers. Singular: er", "correctAnswer": "setzte"}]}, {"id": "g22-15", "type": "input", "number": 15, "prompt": "Ersetze bei den folgenden Begriffen jeweils den ersten Wortbaustein so, dass die gegenteilige Bedeutung entsteht. Jeder Wortbaustein aus der Liste darf nur einmal verwendet werden.", "context": "Verfügbare Bausteine: aus-, zu-, miss-, ab-, ent-, a-, tief-, bös-, un-, de-, be-", "subTasks": [{"id": "g22-15a", "label": "a)", "prompt": "bewaffnen ->", "correctAnswer": "entwaffnen"}, {"id": "g22-15b", "label": "b)", "prompt": "gelingen ->", "correctAnswer": "misslingen"}, {"id": "g22-15c", "label": "c)", "prompt": "verpacken ->", "correctAnswer": "auspacken"}, {"id": "g22-15d", "label": "d)", "prompt": "hochmütig ->", "correctAnswer": "demütig"}, {"id": "g22-15e", "label": "e)", "prompt": "absagen ->", "correctAnswer": "zusagen"}]}]}', '{"In einer schwäbischen Stadt lebte ein Kaufmann. Der war genauso wohlhabend wie geizig, und beides fällt ja","gern zusammen. Dieser Kaufmann litt öfter an Gallenschmerzen und einmal waren diese besonders schlimm.","Trotzdem liess er erst nach langem Zögern einen Arzt rufen, weil er die Kosten fürchtete. Dieser Doktor aber","gehörte ebenfalls nicht zu den verschwenderisch Freigebigen und war für seine Knausrigkeit ebenso bekannt","wie der Kaufmann. So kam also sozusagen der Geiz zum Geize. Der Doktor wendete alle Geschicklichkeit auf,","den Kranken zu heilen, und es gelang. Die Freude des Kaufmanns darüber war allerdings getrübt durch den","Gedanken an die hohe Rechnung, die der Doktor nun bestimmt bald stellen würde.","«Hätte ich diesen nur nicht so voreilig gerufen», dachte sich der Kaufmann. «Vielleicht wäre ich ja ganz von","allein wieder gesund geworden und hätte das Geld für den Arzt sparen können.» Er zerbrach sich lange den","Kopf, wie er es einfädeln könnte, vom geldgierigen Doktor nicht allzu sehr zur Kasse gebeten zu werden. Da","kam ihm endlich ein rettender Einfall.","Er hatte nämlich, da er natürlich alles aufhob, ein Dutzend leerer Kaviardosen im Keller stehen. Bester russi-","scher Kaviar – schwarzes Gold – Mindestgrösse 3 mm war auf den Dosen gut zu lesen. Schnell kochte er eine","Portion kleiner schwarzer Linsen, die aussahen wie diese köstlichen Fischeier, und fügte der Haltbarkeit wegen","eine grosszügige Portion Salz hinzu. Dann füllte er alles fein säuberlich in die Dosen und schraubte deren","beschriftete Deckel gut zu, sodass sie wie ungeöffnet wirkten.","Das Dutzend Dosen schickte er, noch bevor er eine Rechnung von ihm bekommen hatte, schön in ein Kistchen","verpackt, dem Doktor. Dazu legte er einen höflichen und schmeichlerischen Brief, in dem er schrieb, der Doktor","sei, wie er wisse, ein Kenner und werde den Kaviar zu schätzen wissen. Dieser sei eigentlich ein Luxus für","Herzöge und Erzbischöfe, aber seine Dankbarkeit für die gelungene Heilung sei gross und nichts sei ihm zu","teuer in solch einem Fall. Die Überlegung des Kaufmanns war nämlich diese: Den geizigen Doktor werde es","reuen, den teuren Kaviar selbst zu verzehren oder ihn gar seinen sowieso seltenen Gästen vorzusetzen – für ihn","und erst recht für Letztere reichte ein Käsebrötchen vollends. Und so geschah es auch: Der Doktor bewunderte","die Dosen, die glänzten wie Gold, bedankte sich umständlich bei dem Geber und liess das Geschenk durch","seine Magd in den Keller schaffen, um es für eine besondere Gelegenheit aufzusparen.","Die Jahre vergingen. Der Kaufmann starb, und zwar nicht an seinem Gallenleiden. Eine Lungenentzündung,","zu deren Behandlung er es nicht für nötig gehalten hatte, den Doktor herbeizurufen, raffte ihn hinweg. Der","Doktor ging trotzdem zu seiner Beerdigung und dachte, während der Sarg in die Tiefe sank, an die zwölf Dosen","mit bestem Kaviar in seinem Keller. Wie unrecht hatte man dem Kaufmann immer getan, ihn geizig zu nennen.","Er, der Doktor, wusste es besser!","Nicht lange danach segnete der Doktor selbst das Zeitliche, betrauert nur von seiner alten Magd. Die Erben,","entfernte Verwandte, organisierten einen grossen Leichenschmaus, bei dem sie so üppig assen und tranken,","dass der Doktor sich im Grab umgedreht hätte, wenn es ihm möglich gewesen wäre zuzuschauen. Sie holten","den Kaviar zur Krönung des Festes aus dem Keller und füllten ihn in eine Schale aus Gold. Als sie ihre Brötchen","mit dem immer noch schwarz glänzenden Kaviar bestrichen hatten, bissen alle herzhaft hinein. Doch ebenso","schnell husteten und verschluckten sie sich. Ja, einige spuckten den Kaviar sogar auf das weisse Tischtuch – so","faulig und verdorben schmeckte er. Trotzdem – für Linsen hielt den Kaviar keiner! Und obwohl sie von der","Magd dann erfuhren, dass der Kaviar ein Geschenk des schon lange toten Kaufmanns gewesen war – sein","Wappenschild blieb fleckenlos oder wenigstens sah man den Flecken nicht!","Die Erben beschlossen übrigens nach dieser Erfahrung, ihnen sollte so etwas nicht geschehen; sie wollten ihren","Kaviar nicht zu lange lagern, denn, scherzten sie, alt zu werden bekommt nur den Menschen gut, nicht aber",Delikatessen!}', '2026-02-22 22:49:47.450127+00', '2026-02-22 22:49:47.450127+00'),
	('german-2022-qwen', 'Deutsch 2022 (Langgymnasium)', 'German', 2022, 'Qwen 3 Max', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch.", "Du darfst wählen, in welcher Reihenfolge du die Aufgaben löst.", "In den Aufgaben 3, 4, 8, 12, 13 und 14 führen Rechtschreib- und Grammatikfehler zu einem Punkteabzug."], "maxPoints": 47}, "questions": [{"id": "german22-1", "type": "input", "number": 1, "prompt": "Welche zwei unterschiedlichen gesundheitlichen Probleme des Kaufmanns werden in der Geschichte erwähnt? Nenne die beiden Begriffe, die im Text verwendet werden.", "context": "", "subTasks": [{"id": "1a", "label": "-", "prompt": "", "correctAnswer": "Gallenschmerzen"}, {"id": "1b", "label": "-", "prompt": "", "correctAnswer": "Lungenentzündung"}]}, {"id": "german22-2", "type": "text-area", "number": 2, "prompt": "Auf Zeile 5 des Textes wird gesagt: «So kam also sozusagen der Geiz zum Geize.» Wer kommt hier eigentlich zu wem?", "context": "", "subTasks": [{"id": "2a", "label": "", "prompt": "", "modelAnswer": "Der geizige Arzt kommt zum geizigen Kaufmann."}]}, {"id": "german22-3", "type": "text-area", "number": 3, "prompt": "Der Kaufmann bereut es nachträglich, den Arzt um Hilfe gebeten zu haben. Nenne die zwei Überlegungen, die er sich im Text dazu macht. Formuliere in eigenen Worten und in je einem Satz.", "context": "", "subTasks": [{"id": "3a", "label": "Überlegung «Heilung»:", "prompt": "", "modelAnswer": "Vielleicht wäre er auch ohne Arzt gesund geworden."}, {"id": "3b", "label": "Überlegung «Ausgaben»:", "prompt": "", "modelAnswer": "Er hätte die Arztrechnung sparen können."}]}, {"id": "german22-4", "type": "text-area", "number": 4, "prompt": "Geiz und Sparsamkeit haben etwas gemeinsam. Aber Geiz wird anders wahrgenommen und bewertet als Sparsamkeit.\n\na) Erkläre die Gemeinsamkeit zwischen Geiz und Sparsamkeit allgemein. Schreibe einen ganzen Satz. Arbeite nicht mit Beispielen.\n\nb) Erkläre den inhaltlichen Unterschied in der Bewertung von Geiz und Sparsamkeit, indem du den Satz unten vervollständigst.", "context": "", "subTasks": [{"id": "4a", "label": "a.", "prompt": "", "modelAnswer": "Beide bedeuten, dass man kein Geld ausgibt."}, {"id": "4b", "label": "b. Sparsamkeit wird", "prompt": "bewertet als Geiz.", "correctAnswer": "positiver"}]}, {"id": "german22-5", "rows": [{"id": "5a", "text": "Der Kaufmann verschliesst die gefüllten Dosen."}, {"id": "5b", "text": "Der Kaufmann beschriftet die Deckel."}, {"id": "5c", "text": "Der Kaufmann mischt Salz bei."}, {"id": "5d", "text": "Der Kaufmann holt die Bohnen aus dem Keller."}, {"id": "5e", "text": "Der Kaufmann hat eine zündende Idee."}, {"id": "5f", "text": "Der Kaufmann kocht die Fisch-Eier."}, {"id": "5g", "text": "Der Kaufmann importiert die Linsen aus Russland."}], "type": "table-select", "number": 5, "prompt": "Lies die Zeilen 8–16 nochmals. Stimmen die Aussagen in der Tabelle mit der Handlung in den Zeilen überein? Setze das Kreuz bei «ja» oder «nein». Falsch gesetzte Kreuze geben Abzug.", "columns": [{"id": "no", "label": "nein"}, {"id": "yes", "label": "ja"}], "context": "", "subTasks": [], "correctTableAnswers": {"5a": "yes", "5b": "no", "5c": "yes", "5d": "no", "5e": "yes", "5f": "no", "5g": "no"}}, {"id": "german22-6", "rows": [{"id": "6a", "text": "Der Kaufmann ist älter als der Doktor."}, {"id": "6b", "text": "Es ist nicht bekannt, wann genau die Geschichte spielt."}, {"id": "6c", "text": "Kaviar besteht ausschliesslich aus roten Fischeiern."}, {"id": "6d", "text": "Der Kaufmann geht listig vor."}, {"id": "6e", "text": "Keine Person in der Geschichte weiss, dass anstelle von Kaviar Linsen in den Dosen sind."}, {"id": "6f", "text": "Die Verwandten sind traurig darüber, dass der Doktor gestorben ist."}, {"id": "6g", "text": "Der Kaufmann stirbt, weil er den Arzt nicht gerufen hat."}, {"id": "6h", "text": "Die Magd hält den Kaufmann für geizig."}], "type": "table-select", "number": 6, "prompt": "Kreuze bei den folgenden Sätzen an, ob sie mit den Aussagen des Textes übereinstimmen (✓) oder nicht (–). Setze das Kreuz beim Fragezeichen (?), wenn das nicht entschieden werden kann. Es darf nur ein Kreuz pro Zeile gesetzt werden.", "columns": [{"id": "correct", "label": "✓"}, {"id": "incorrect", "label": "–"}, {"id": "unknown", "label": "?"}], "context": "", "subTasks": [], "correctTableAnswers": {"6a": "unknown", "6b": "correct", "6c": "incorrect", "6d": "correct", "6e": "incorrect", "6f": "incorrect", "6g": "unknown", "6h": "unknown"}}, {"id": "german22-7", "type": "input", "number": 7, "prompt": "Das Wort «Gold» wird im Text dreimal verwendet, und zwar auf den Zeilen 13, 24 und 34. Aber nur einmal ist mit «Gold» tatsächlich echtes Gold gemeint, während zweimal nur eine Eigenschaft von Gold als Vergleich eingesetzt wird. Schreibe «echt» auf die freie Linie beim Satz, wo echtes Gold gemeint ist, und nenne in den anderen beiden Fällen die Eigenschaft von Gold, welche für den Vergleich genutzt wird.", "context": "", "subTasks": [{"id": "7a", "label": "a. „Bester russischer Kaviar – schwarzes Gold...“", "prompt": "", "correctAnswer": "hoher Wert"}, {"id": "7b", "label": "b. „Die Dosen, die glänzten wie Gold.“", "prompt": "", "correctAnswer": "Glanz"}, {"id": "7c", "label": "c. „...in eine Schale aus Gold.“", "prompt": "", "correctAnswer": "echt"}]}, {"id": "german22-8", "type": "text-area", "number": 8, "prompt": "Lies die Zeilen 23 bis 30 noch einmal. In dieser Passage täuscht sich der Doktor gleich zweimal. Erkläre diese beiden Fehleinschätzungen in jeweils einem ganzen Satz.", "context": "", "subTasks": [{"id": "8a", "label": "Fehleinschätzung «Wert des Geschenks»:", "prompt": "", "modelAnswer": "Der Doktor glaubt, echten Kaviar erhalten zu haben."}, {"id": "8b", "label": "Fehleinschätzung «Charakter des Kaufmanns»:", "prompt": "", "modelAnswer": "Der Doktor hält den Kaufmann für großzügig und nicht geizig."}]}, {"id": "german22-9", "rows": [{"id": "9a", "text": "Menschen lassen sich austricksen."}, {"id": "9b", "text": "Man soll Genuss nicht aufschieben."}, {"id": "9c", "text": "Der Ruf eines Menschen kann täuschen."}, {"id": "9d", "text": "Lügen haben kurze Beine."}, {"id": "9e", "text": "Wertloses kann wertvoll sein."}, {"id": "9f", "text": "Wertvolles kann wertlos sein."}, {"id": "9g", "text": "Geiz lohnt sich nicht."}], "type": "table-select", "number": 9, "prompt": "Die Personen machen im Verlauf der Geschichte verschiedene Erfahrungen. Kreuze an: Wer macht welche Erfahrung(en)? Setze das Kreuz bei «niemand», wenn keine Person in der Geschichte die entsprechende Erfahrung macht. Es darf nur ein Kreuz pro Zeile gesetzt werden.", "columns": [{"id": "kaufmann", "label": "Kaufmann"}, {"id": "doktor", "label": "Doktor"}, {"id": "erben", "label": "Erben"}, {"id": "niemand", "label": "niemand"}], "context": "", "subTasks": [], "correctTableAnswers": {"9a": "kaufmann", "9b": "erben", "9c": "doktor", "9d": "niemand", "9e": "kaufmann", "9f": "erben", "9g": "erben"}}, {"id": "german22-10", "type": "multiple-choice", "number": 10, "prompt": "Kreuze jeweils nur die Lösung an, die der Bedeutung der fett gedruckten Wörter und Ausdrücke am besten entspricht. Deine Lösung muss inhaltlich zum Text passen.", "context": "", "subTasks": [{"id": "10a", "label": "«Der war genauso wohlhabend wie geizig.» (Z. 1)", "options": ["wohlgenährt", "rechthaberisch", "wohlstündig", "reich", "glücklich"], "correctAnswer": "reich"}, {"id": "10b", "label": "«Er überlegte sich, wie er es einfädeln könnte...» (Z. 9–10)", "options": ["einrichten", "anrichten", "kommunizieren", "vorstellen", "versichern"], "correctAnswer": "einrichten"}, {"id": "10c", "label": "«Nicht lange danach segnete der Doktor selbst das Zeitliche.» (Z. 31)", "options": ["machte das Kreuzzeichen", "gab jemandem den Segen", "schied aus dem Leben", "wurde heilig", "genoss die Zeit"], "correctAnswer": "schied aus dem Leben"}, {"id": "10d", "label": "«Alle bissen herzhaft hinein.» (Z. 35)", "options": ["herzlich", "halbherzig", "warmherzig", "mit Herzenslust", "grossherzig"], "correctAnswer": "mit Herzenslust"}, {"id": "10e", "label": "«Sein Wappenschild blieb fleckenlos...» (Z. 38–39)", "options": ["Firmenlogo", "Ruf", "Firmenschild", "Bekanntheit", "Verteidigung"], "correctAnswer": "Ruf"}]}, {"id": "german22-11", "rows": [{"id": "11a", "text": "«Der Doktor wendete alle Geschicklichkeit auf... Die Freude des Kaufmanns darüber war allerdings getrübt.»"}, {"id": "11b", "text": "«... schraubte deren beschriftete Deckel gut zu...»"}, {"id": "11c", "text": "«Den geizigen Doktor werde es reuen, den teuren Kaviar selbst zu verzehren...» (erster Teil)"}, {"id": "11d", "text": "«... oder ihn gar seinen sowieso seltenen Gästen vorzusetzen...» (zweiter Teil)"}], "type": "table-select", "number": 11, "prompt": "Kreuze jeweils an, worauf sich das fett gedruckte Wort inhaltlich bezieht. Lies die Stellen im Text nochmals durch und kreuze nur eine Lösung an. Die Lösung muss inhaltlich zum Text passen.", "columns": [{"id": "option1", "label": "die Heilung"}, {"id": "option2", "label": "die hohe Rechnung"}, {"id": "option3", "label": "die Gallensteine"}, {"id": "option4", "label": "den Geiz des Doktors"}, {"id": "option5", "label": "die Geschicklichkeit des Doktors"}], "context": "", "subTasks": [], "correctTableAnswers": {"11a": "option2", "11b": "option3", "11c": "option5", "11d": "option3"}}, {"id": "german22-12", "type": "text-area", "number": 12, "prompt": "a) Erkläre in einem ganzen Satz, warum der zweite Satz der Textstelle nicht einfach lauten kann: «Er wusste es besser!»\n\nb) Formuliere den Satz «Sie holten den Kaviar zur Krönung des Festes...» so um, dass er gleich aufgebaut ist wie: „Er, der Doktor, wusste es besser!“", "context": "", "subTasks": [{"id": "12a", "label": "a.", "prompt": "", "modelAnswer": "Weil dann unklar wäre, ob „er“ der Kaufmann oder der Doktor ist."}, {"id": "12b", "label": "b.", "prompt": "", "modelAnswer": "Sie, die Erben, holten den Kaviar zur Krönung des Festes."}]}, {"id": "german22-13", "type": "input", "number": 13, "prompt": "Bilde ausgehend vom Wortstamm (Stamm-Morphem) der fett gedruckten Wörter ein neues Wort aus derselben Wortfamilie, das in die Lücke passt.", "context": "", "subTasks": [{"id": "13a", "label": "Sein schmerzhaftes", "prompt": "wurde von der Galle verursacht.", "correctAnswer": "Leiden"}, {"id": "13b", "label": "Unter", "prompt": "aller Geschicklichkeit gelang es dem Doktor...", "correctAnswer": "Anwendung"}, {"id": "13c", "label": "Die Behandlung war zu guter Letzt", "prompt": ".", "correctAnswer": "erfolgreich"}, {"id": "13d", "label": "Er starb, weil der", "prompt": "getrogen hatte.", "correctAnswer": "Schein"}, {"id": "13e", "label": "Sein Wappenschild blieb", "prompt": ".", "correctAnswer": "unbefleckt"}]}, {"id": "german22-14", "type": "input", "number": 14, "prompt": "Bilde die verlangten Verbformen und schreibe sie fehlerfrei.", "context": "", "subTasks": [{"id": "14a1", "label": "laden – 2. Pers. Pl. Präsens:", "prompt": "", "correctAnswer": "ihr ladet"}, {"id": "14a2", "label": "laden – 3. Pers. Sg. Präteritum:", "prompt": "", "correctAnswer": "er lud"}, {"id": "14b1", "label": "sein – 2. Pers. Pl. Präsens:", "prompt": "", "correctAnswer": "ihr seid"}, {"id": "14b2", "label": "sein – 3. Pers. Sg. Präteritum:", "prompt": "", "correctAnswer": "es war"}, {"id": "14c1", "label": "lassen – 2. Pers. Pl. Präsens:", "prompt": "", "correctAnswer": "ihr lasst"}, {"id": "14c2", "label": "lassen – 3. Pers. Sg. Präteritum:", "prompt": "", "correctAnswer": "er liess"}, {"id": "14d1", "label": "schaffen – 2. Pers. Pl. Präsens:", "prompt": "", "correctAnswer": "ihr schafft"}, {"id": "14d2", "label": "schaffen – 3. Pers. Sg. Präteritum:", "prompt": "", "correctAnswer": "sie schuf"}, {"id": "14e1", "label": "setzen – 2. Pers. Pl. Präsens:", "prompt": "", "correctAnswer": "ihr setzt"}, {"id": "14e2", "label": "setzen – 3. Pers. Sg. Präteritum:", "prompt": "", "correctAnswer": "er setzte"}]}, {"id": "german22-15", "type": "input", "number": 15, "prompt": "Ersetze bei den folgenden Begriffen jeweils den ersten Wortbaustein so, dass die gegenteilige Bedeutung entsteht. Jeder Wortbaustein darf nur einmal verwendet werden.", "context": "Wortbausteine: aus, zu, miss, ab, ent, a, tief, bös, un, de, be", "subTasks": [{"id": "15a", "label": "a) bewaffnen", "prompt": "", "correctAnswer": "entwaffnen"}, {"id": "15b", "label": "b) gelingen", "prompt": "", "correctAnswer": "misslingen"}, {"id": "15c", "label": "c) verpacken", "prompt": "", "correctAnswer": "auspacken"}, {"id": "15d", "label": "d) hochmütig", "prompt": "", "correctAnswer": "demütig"}, {"id": "15e", "label": "e) absagen", "prompt": "", "correctAnswer": "zusagen"}]}]}', '{"In einer schwäbischen Stadt lebte ein Kaufmann. Der war genauso wohlhabend wie geizig, und","beides fällt ja gern zusammen. Dieser Kaufmann litt öfter an Gallenschmerzen und einmal","waren diese besonders schlimm.","Trotzdem liess er erst nach langem Zögern einen Arzt rufen, weil er die Kosten fürchtete.","Dieser Doktor aber gehörte ebenfalls nicht zu den verschwenderisch Freigebigen und war für","seine Knausrigkeit ebenso bekannt wie der Kaufmann. So kam also sozusagen der Geiz zum","Geize. Der Doktor wendete alle Geschicklichkeit auf, den Kranken zu heilen, und es gelang.","Die Freude des Kaufmanns darüber war allerdings getrübt durch den Gedanken an die hohe","Rechnung, die der Doktor nun bestimmt bald stellen würde.","«Hätte ich diesen nur nicht so voreilig gerufen», dachte sich der Kaufmann. «Vielleicht wäre","ich ja ganz von allein wieder gesund geworden und hätte das Geld für den Arzt sparen können.»","Er zerbrach sich lange den Kopf, wie er es einfädeln könnte, vom geldgierigen Doktor nicht","allzu sehr zur Kasse gebeten zu werden. Da kam ihm endlich ein rettender Einfall.","Er hatte nämlich, da er natürlich alles aufhob, ein Dutzend leerer Kaviardosen im Keller stehen.","Bester russischer Kaviar – schwarzes Gold – Mindestgrösse 3 mm war auf den Dosen gut zu","lesen. Schnell kochte er eine Portion kleiner schwarzer Linsen, die aussahen wie diese köstlichen","Fischeier, und fügte der Haltbarkeit wegen eine grosszügige Portion Salz hinzu. Dann füllte er","alles fein säuberlich in die Dosen und schraubte deren beschriftete Deckel gut zu, sodass sie wie","ungeöffnet wirkten.","Das Dutzend Dosen schickte er, noch bevor er eine Rechnung von ihm bekommen hatte, schön","in ein Kistchen verpackt, dem Doktor. Dazu legte er einen höflichen und schmeichlerischen","Brief, in dem er schrieb, der Doktor sei, wie er wisse, ein Kenner und werde den Kaviar zu","schätzen wissen. Dieser sei eigentlich ein Luxus für Herzöge und Erzbischöfe, aber seine","Dankbarkeit für die gelungene Heilung sei gross und nichts sei ihm zu teuer in solch einem Fall.","Die Überlegung des Kaufmanns war nämlich diese: Den geizigen Doktor werde es reuen, den","teuren Kaviar selbst zu verzehren oder ihn gar seinen sowieso seltenen Gästen vorzusetzen – für","ihn und erst recht für Letztere reichte ein Käsebrötchen vollends. Und so geschah es auch: Der","Doktor bewunderte die Dosen, die glänzten wie Gold, bedankte sich umständlich bei dem Geber","und liess das Geschenk durch seine Magd in den Keller schaffen, um es für eine besondere","Gelegenheit aufzusparen.","Die Jahre vergingen. Der Kaufmann starb, und zwar nicht an seinem Gallenleiden. Eine","Lungenentzündung, zu deren Behandlung er es nicht für nötig gehalten hatte, den Doktor","herbeizurufen, raffte ihn hinweg. Der Doktor ging trotzdem zu seiner Beerdigung und dachte,","während der Sarg in die Tiefe sank, an die zwölf Dosen mit bestem Kaviar in seinem Keller. Wie","unrecht hatte man dem Kaufmann immer getan, ihn geizig zu nennen. Er, der Doktor, wusste es",besser!,"Nicht lange danach segnete der Doktor selbst das Zeitliche, betrauert nur von seiner alten Magd.","Die Erben, entfernte Verwandte, organisierten einen grossen Leichenschmaus, bei dem sie so","üppig assen und tranken, dass der Doktor sich im Grab umgedreht hätte, wenn es ihm möglich","gewesen wäre zuzuschauen. Sie holten den Kaviar zur Krönung des Festes aus dem Keller und","füllten ihn in eine Schale aus Gold. Als sie ihre Brötchen mit dem immer noch schwarz glänzenden","Kaviar bestrichen hatten, bissen alle herzhaft hinein. Doch ebenso schnell husteten und","verschluckten sie sich. Ja, einige spuckten den Kaviar sogar auf das weisse Tischtuch – so","faulig und verdorben schmeckte er. Trotzdem – für Linsen hielt den Kaviar keiner! Und obwohl","sie von der Magd dann erfuhren, dass der Kaviar ein Geschenk des schon lange toten Kaufmanns","gewesen war – sein Wappenschild blieb fleckenlos oder wenigstens sah man den Flecken nicht!","Die Erben beschlossen übrigens nach dieser Erfahrung, ihnen sollte so etwas nicht geschehen;","sie wollten ihren Kaviar nicht zu lange lagern, denn, scherzten sie, alt zu werden bekommt nur","den Menschen gut, nicht aber Delikatessen!"}', '2026-02-22 22:49:47.585089+00', '2026-02-22 22:49:47.585089+00'),
	('german-2023-gemini', 'Sprachprüfung Deutsch 2023 (Langgymnasium)', 'German', 2023, 'Gemini 3 Pro', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch.", "Die Reihenfolge darfst du frei wählen.", "In den Aufgaben 5, 6, 7, 9, 11, 12 und 13 führen Rechtschreibe- und Grammatikfehler zu einem Punkteabzug."], "maxPoints": 51}, "questions": [{"id": "g23-1", "type": "input", "number": 1, "prompt": "Fragen zur Person Meral", "subTasks": [{"id": "g23-1a", "label": "a)", "prompt": "Woher kommt Meral ursprünglich?", "modelAnswer": "Kosovo / Kosovo-Albanien / Republik Kosovo"}, {"id": "g23-1b", "label": "b)", "prompt": "Welches Geschlecht hat Meral?", "modelAnswer": "weiblich (Mädchen, Frau)"}]}, {"id": "g23-2", "type": "input", "number": 2, "prompt": "Es gibt in der Geschichte einen Zeitsprung (Rückblende).", "subTasks": [{"id": "g23-2a-start", "label": "a)", "prompt": "Die Rückblende in die Vergangenheit beginnt auf der Zeile", "correctAnswer": 10}, {"id": "g23-2a-end", "label": "und", "prompt": "endet auf der Zeile", "correctAnswer": 41}, {"id": "g23-2b", "label": "b)", "prompt": "Vor wie vielen Jahren hat das Gespräch über die Elefanten im Garten stattgefunden?", "suffix": "Jahren", "correctAnswer": 20}]}, {"id": "g23-3", "type": "text-area", "number": 3, "prompt": "Gleich im ersten Abschnitt wird deutlich, dass Meral das Verhalten von Sarah beim Wiedersehen als zurückhaltend empfindet. Halte stichwortartig vier Punkte fest, die dies verdeutlichen.", "subTasks": [{"id": "g23-3a", "label": "Punkte:", "prompt": "Nenne 4 Beobachtungen.", "modelAnswer": "1. schwächere Umarmung / drückt weniger\n2. (bloss) Ausrede / angeblich keine Zeit\n3. leise Stimme (als ob sie Ohren schonen wolle)\n4. lächelt verlegen\n5. wiederholt Ausrede"}]}, {"id": "g23-4", "type": "text-area", "number": 4, "prompt": "In welchem Satz wird eindeutig klar, dass Meral erst durch Sarah auf den Namen Dumbo gekommen ist? Schreibe diesen einen Satz vollständig ab.", "subTasks": [{"id": "g23-4a", "label": "Antwort:", "prompt": "Satz aus dem Text:", "correctAnswer": "«Ich hätte auf die Schnelle keinen besseren erfinden können.»"}]}, {"id": "g23-5", "type": "input", "number": 5, "prompt": "Betrachte die auf dem Bild sichtbaren Teile der fünf mit Ziffern markierten Gebäude. Lies noch einmal das Gespräch auf den Zeilen 10 bis 17.", "imageUrl": "/images/german-2023/gemini/task-5.png", "subTasks": [{"id": "g23-5a", "label": "a)", "prompt": "Welches Haus entspricht am ehesten jenem, in welchem Merals Familie gemäss diesem Gespräch gelebt haben soll?", "correctAnswer": "2"}, {"id": "g23-5b-1", "label": "b) 1.", "prompt": "Lage: Das von mir gewählte Gebäude liegt...", "modelAnswer": "ausserhalb des Dorfes / versteckt / zwischen Bäumen / so, dass es Sichtschutz bietet"}, {"id": "g23-5b-2", "label": "b) 2.", "prompt": "Gelände um das Gebäude: Das von mir gewählte Gebäude hat...", "modelAnswer": "Verstecke für Tiere / einen Garten / Bäume"}, {"id": "g23-5b-3", "label": "b) 3.", "prompt": "Merkmale am Gebäude: Das von mir gewählte Gebäude verfügt als einziges über...", "modelAnswer": "Fenster auf zwei Etagen / Fenster im Parterre und zweiten Stock"}]}, {"id": "g23-6", "type": "text-area", "number": 6, "prompt": "Der Alltag von Merals Eltern in der Schweiz war von Stress und Sorgen geprägt.", "subTasks": [{"id": "g23-6a", "label": "a)", "prompt": "Erkläre, weshalb die Familie in den Schulferien nicht ins Ausland reisen konnte und die Kinder keine tollen Geschenke erhielten.", "modelAnswer": "Juristisch: Reiseverbot für Asylbewerber. Finanziell: Arbeitsverbot / Armut / kein Geld."}, {"id": "g23-6b", "label": "b)", "prompt": "Mit welchem Verhalten reagierte Meral gegenüber Sarah auf diese schwierige Situation bei sich zuhause?", "modelAnswer": "Sie lügt / schwindelt / erfindet Geschichten / macht sich interessant."}]}, {"id": "g23-7", "type": "text-area", "number": 7, "prompt": "Laut Meral hat der Grossvater den Löwen besänftigt. Zähle vier weitere Aussagen über den Grossvater auf, die unglaubwürdig sind.", "subTasks": [{"id": "g23-7a", "label": "Antwort:", "prompt": "Vervollständige: Der Grossvater hat angeblich...", "modelAnswer": "- schon 1000 Kriege erlebt.\n- den Kampf gewonnen / sich selbst helfen können.\n- bloss zerrissene Hosen gehabt.\n- dem Löwen einen Geheimnamen ins Ohr geflüstert.\n- bewirkt, dass die Kinder mit dem Löwen spielen konnten."}]}, {"id": "g23-8", "rows": [{"id": "r1", "text": "Die Familie lebte unter anderem vom Eintrittsgeld, das sie für den Besuch ihrer Tiere verlangte."}, {"id": "r2", "text": "Der Grossvater lebte im Kosovo mit Merals Familie im selben Haushalt."}, {"id": "r3", "text": "Sarah bezweifelte als Zweitklässlerin den Wahrheitsgehalt von Merals Geschichten."}, {"id": "r4", "text": "Während sich Merals Familie in der Schweiz um Asyl bewarb, arbeitete die Mutter als Übersetzerin."}, {"id": "r5", "text": "Meral ist sich nicht sicher, ob Sarah sie in der kommenden Woche wirklich anrufen wird."}, {"id": "r6", "text": "Meral behauptet, sie wolle die Ohren von Sarah schonen."}, {"id": "r7", "text": "Am Anfang des Gesprächs in der Altstadt kennt Meral die aktuelle Adresse von Sarah."}, {"id": "r8", "text": "Meral hat eine ältere Schwester."}, {"id": "r9", "text": "Meral hat mehrere Cousinen."}], "type": "table-select", "number": 8, "prompt": "Kreuze bei den folgenden Aussagen an, ob sie mit den Informationen des Textes übereinstimmen (✓), nicht (-) oder ob es nicht entschieden werden kann (?).", "columns": [{"id": "c_true", "label": "✓"}, {"id": "c_unknown", "label": "?"}, {"id": "c_false", "label": "-"}], "subTasks": [{"id": "g23-8-sub", "label": "Tabelle", "prompt": "Kreuze an."}], "correctTableAnswers": {"r1": "c_false", "r2": "c_unknown", "r3": "c_true", "r4": "c_false", "r5": "c_true", "r6": "c_false", "r7": "c_false", "r8": "c_unknown", "r9": "c_true"}}, {"id": "g23-9", "type": "text-area", "number": 9, "prompt": "Sarah und Meral verhalten sich spiegelbildlich. Erkläre diese Aussage mit den Wörtern «Vergangenheit», «Gegenwart», «schwindelt an» und «zweifelt an».", "subTasks": [{"id": "g23-9a", "label": "Antwort:", "prompt": "Schreibe ganze Sätze.", "modelAnswer": "In der Vergangenheit schwindelte Meral Sarah an und Sarah zweifelte an Meral. In der Gegenwart schwindelt Sarah Meral an und Meral zweifelt an Sarah."}]}, {"id": "g23-10", "type": "multiple-choice", "number": 10, "prompt": "Kreuze jeweils nur die eine Lösung an, die der Bedeutung der fett gedruckten Wörter und Ausdrücke am besten entspricht.", "subTasks": [{"id": "g23-10a", "label": "a)", "prompt": "«Ich **schlenderte** durch die Marktgasse...» (Z. 1)", "options": ["trottete", "pilgerte", "bummelte", "ging", "marschierte"], "correctAnswer": "bummelte"}, {"id": "g23-10b", "label": "b)", "prompt": "«Ich erklärte Sarah damals scheinbar **gleichgültig**: ...» (Z. 10)", "options": ["gleichmässig", "unbeteiligt", "freudlos", "verbittert", "abgebrüht"], "correctAnswer": "unbeteiligt"}, {"id": "g23-10c", "label": "c)", "prompt": "«Grossvater hatte nach diesem Angriff nur **zerrissene** Hosen.» (Z. 24/25)", "options": ["geschlissene", "verschleisste", "löchrige", "zerfetzte", "abgerissene"], "correctAnswer": "zerfetzte"}, {"id": "g23-10d", "label": "d)", "prompt": "«Der Löwe war **sanft** geworden.» (Z. 36)", "options": ["zart", "wohlwollend", "zahm", "herzlich", "gnädig"], "correctAnswer": "zahm"}, {"id": "g23-10e", "label": "e)", "prompt": "«... meinte Sarah **distanziert**, ...» (Z. 42)", "options": ["aus der Ferne", "zugeknöpft", "böse", "barsch", "unhöflich"], "correctAnswer": "zugeknöpft"}]}, {"id": "g23-11", "type": "input", "number": 11, "prompt": "Kombiniere den Verbstamm jeweils mit einem zum Satz passenden Vormorphem.", "subTasks": [{"id": "g23-11a-1", "label": "a) greifen:", "prompt": "Der Löwe hatte endlich ____, dass mein Grossvater viel stärker war als er.", "correctAnswer": "begriffen"}, {"id": "g23-11a-2", "label": "a) greifen:", "prompt": "Die Polizei hätte gegen Löwenhalter sofort hart ____ müssen.", "modelAnswer": "durchgreifen / eingreifen", "correctAnswer": "durchgreifen"}, {"id": "g23-11b-1", "label": "b) bringen:", "prompt": "Die Lehrerin musste viel Geduld ____, um die Klasse zu beruhigen.", "correctAnswer": "aufbringen"}, {"id": "g23-11b-2", "label": "b) bringen:", "prompt": "Wir mussten den Nachweis ____, dass wir ein Recht auf Asyl hatten.", "correctAnswer": "erbringen"}]}, {"id": "g23-12", "type": "input", "number": 12, "prompt": "Fülle die Lücken mit den jeweils verlangten Verben zuerst im Präsens, dann im Präteritum korrekt aus.", "subTasks": [{"id": "g23-12a-pres", "label": "ertragen (Präsens):", "prompt": "____ du die Schmerzen?", "correctAnswer": "Erträgst"}, {"id": "g23-12a-past", "label": "ertragen (Präteritum):", "prompt": "____ du die Schmerzen?", "correctAnswer": "Ertrugst"}, {"id": "g23-12b-pres", "label": "treffen (Präsens):", "prompt": "____ du das Ziel?", "correctAnswer": "Triffst"}, {"id": "g23-12b-past", "label": "treffen (Präteritum):", "prompt": "____ du das Ziel?", "correctAnswer": "Trafst"}, {"id": "g23-12c-pres", "label": "heissen (Präsens):", "prompt": "____ du in diesem Spiel Karl oder Carlo?", "correctAnswer": "Heisst"}, {"id": "g23-12c-past", "label": "heissen (Präteritum):", "prompt": "____ du in diesem Spiel Karl oder Carlo?", "modelAnswer": "Hiessest / Hiesst", "correctAnswer": "Hiessest"}, {"id": "g23-12d-pres", "label": "empfehlen (Präsens):", "prompt": "____ du ihnen die Abkürzung?", "correctAnswer": "Empfiehlst"}, {"id": "g23-12d-past", "label": "empfehlen (Präteritum):", "prompt": "____ du ihnen die Abkürzung?", "correctAnswer": "Empfahlst"}, {"id": "g23-12e-pres", "label": "halten (Präsens):", "prompt": "____ du dich an die Abmachung?", "correctAnswer": "Hältst"}, {"id": "g23-12e-past", "label": "halten (Präteritum):", "prompt": "____ du dich an die Abmachung?", "modelAnswer": "Hieltst / Hieltest", "correctAnswer": "Hieltst"}]}, {"id": "g23-13", "type": "input", "number": 13, "prompt": "Bilde ausgehend vom Wortstamm der fett gedruckten Wörter ein neues Wort aus derselben Wortfamilie, das in die Lücke passt.", "subTasks": [{"id": "g23-13a", "label": "a)", "prompt": "Sarah war ... **misstrauisch**. -> Sarah empfand meinen Geschichten gegenüber ein", "correctAnswer": "Misstrauen"}, {"id": "g23-13b", "label": "b)", "prompt": "Löwe war nichts **Besonderes**. -> Tausend Kriege hatte er schon erlebt, da war ein Löwe keine", "suffix": "dagegen.", "correctAnswer": "Besonderheit"}, {"id": "g23-13c", "label": "c)", "prompt": "kam es oft zu **Streitigkeiten**. -> Weil meine Eltern all diese Zeit zusammen verbrachten,", "suffix": "sie oft.", "correctAnswer": "stritten"}, {"id": "g23-13d", "label": "d)", "prompt": "Löwe war **sanft** geworden. -> Der Löwe schien die", "suffix": "in Person zu sein.", "modelAnswer": "Sanftmut / Sanftheit / Sanftmütigkeit", "correctAnswer": "Sanftmut"}, {"id": "g23-13e", "label": "e)", "prompt": "waren **befreundet**. -> Meral und Sarah waren in der zweiten Klasse", "modelAnswer": "Freundinnen / Freunde", "correctAnswer": "Freundinnen"}]}, {"id": "g23-14", "type": "input", "number": 14, "prompt": "Gib zu den einzelnen Wortgruppen jeweils die passende Frage an.", "imageUrl": "/images/german-2023/gemini/task-14.png", "subTasks": [{"id": "g23-14a-1", "label": "a)", "prompt": "Am Anfang:", "imageUrl": "/images/german-2023/gemini/task-14-a.png", "correctAnswer": "wann?"}, {"id": "g23-14a-2", "label": "a)", "prompt": "Herr Lang:", "correctAnswer": "wer?"}, {"id": "g23-14a-3", "label": "a)", "prompt": "die Klasse:", "correctAnswer": "wen?"}, {"id": "g23-14a-4", "label": "a)", "prompt": "nach Ferienerlebnissen:", "correctAnswer": "wonach?"}, {"id": "g23-14b-1", "label": "b)", "prompt": "Geheimnamen:", "imageUrl": "/images/german-2023/gemini/task-14-b.png", "modelAnswer": "wen? / was?", "correctAnswer": "wen? / was?"}, {"id": "g23-14b-2", "label": "b)", "prompt": "der Grossvater:", "correctAnswer": "wer?"}, {"id": "g23-14b-3", "label": "b)", "prompt": "dem Löwen:", "correctAnswer": "wem?"}, {"id": "g23-14b-4", "label": "b)", "prompt": "ins Ohr:", "correctAnswer": "wohin?"}]}, {"id": "g23-15", "type": "input", "number": 15, "prompt": "Die Sätze unten weisen jeweils genau einen Grammatikfehler auf. Korrigiere ihn.", "subTasks": [{"id": "g23-15a", "label": "a)", "prompt": "Erst **wenn** Meral 28 Jahre alt war, begegneten sich die beiden zufällig wieder. ->", "correctAnswer": "als"}, {"id": "g23-15b", "label": "b)", "prompt": "Sarah hatte keine Zeit zum Plaudern, **weil sie hatte** noch viel zu erledigen. ->", "modelAnswer": "weil sie noch viel zu erledigen hatte / denn sie hatte...", "correctAnswer": "weil sie noch viel zu erledigen hatte"}, {"id": "g23-15c", "label": "c)", "prompt": "Sarah war damals die **Einzigste**, die mit Meral spielte. ->", "correctAnswer": "Einzige"}, {"id": "g23-15d", "label": "d)", "prompt": "Sarah ist immer etwa eine Handbreit grösser gewesen **wie** Meral. ->", "correctAnswer": "als"}, {"id": "g23-15e", "label": "e)", "prompt": "«Ich rufe **dir** nächste Woche an!» ->", "correctAnswer": "dich"}, {"id": "g23-15f", "label": "f)", "prompt": "Meral war sichtlich enttäuscht und **sass** auf eine Parkbank, um sich etwas zu sammeln. ->", "modelAnswer": "setzte sich (oder: sass auf einer Parkbank)", "correctAnswer": "setzte sich"}]}]}', '{"Ich schlenderte durch die Marktgasse und traf zufällig auf Sarah. Sie sah aus wie früher. Wenn ich","Sarah auch Ewigkeiten nicht mehr gesehen hatte, erkannte ich sie dennoch sofort wieder. Sarah war","zurückhaltend. Bei der Umarmung, bei der wir uns zur Begrüssung drückten, war ich diejenige, die","fester drückte. Sie habe nicht viel Zeit, sie müsse gleich weiter, sagte sie zu Beginn mit einer so leisen","Stimme, als wollte sie meine Ohren schonen. Ob sie nicht doch Zeit hätte, mit mir wenigstens eine","Tasse Tee trinken zu gehen? Sie habe keine Zeit, wiederholte sie und lächelte dabei verlegen, als ob","ich die Wahrheit nicht ertragen könnte. Ich erinnerte mich an eines unserer ersten Gespräche zurück,","als habe es erst gestern und nicht vor zwanzig Jahren in der zweiten Klasse der Primarschule stattge-",funden.,"Ich erklärte Sarah damals scheinbar gleichgültig: «Im Kosovo wohnten wir vor dem Krieg ausserhalb","des Dorfes, wir hatten Elefanten im Garten. Der kleinste steckte seinen Kopf durch das Fenster in","mein Zimmer im Erdgeschoss und wollte mit Nüssen gefüttert werden.»","«Wie Dumbo, der Elefant aus dem Trickfilm?», wollte Sarah staunend wissen.","«Ja, genau wie der hat er geheissen.» Dieser Name passte gut zu ihm. Ich hätte auf die Schnelle keinen","besseren erfinden können. «Ich wollte noch eine Giraffe, doch mein Vater meinte, die würde dann","sogar noch über die Fenster der zweiten Etage hinauswachsen, sodass die Leute im Dorf sie sehen","könnten. Wir aber wollten unsere Tiere geheim halten, damit niemand sie uns wegnehmen konnte.»","«Weshalb sollte euch jemand die Tiere wegnehmen, Meral? Und habt ihr die Tiere mit in die Schweiz",genommen?»,"Sarah war misstrauisch meinen Geschichten gegenüber. Jedes Mal, wenn ich ihr damals von meiner","Heimat erzählte, stellte sie mir viele Fragen.","«Wir hatten sogar einen Löwen im Garten, der war gefährlich. Einmal hat der Löwe meinen Gross-","vater angegriffen, doch der hat sich selbst helfen können. Tausend Kriege hatte er da schon erlebt, da","war ein Löwe rein gar nichts dagegen. Mein Grossvater hatte nach diesem Angriff nur zerrissene",Hosen.»,"«Ihr hattet einen Löwen als Haustier?», fragte Sarah zweifelnd.","Ich konnte nicht damit aufhören, ich hatte sonst ja nichts zu erzählen, nicht von Auslandferien oder","von tollen Geschenken zum Geburtstag oder von Ausflügen. Was hätte ich denn erzählen sollen nach","den Ferien, wenn Herr Lang uns im Unterricht fragte, was wir Spannendes erlebt hätten? Hätte ich","vielleicht erzählen sollen, dass meine Eltern sich oft gestritten hatten, weil sie sich jeden Tag Sorgen","machten? Dass sie als Asylbewerber nicht arbeiten und reisen durften, uns Mädchen anschrien? Oder","wie ich alleine war, weil niemand mich angerufen hatte, und dass ich mich die ganze Zeit über ge-","langweilt hatte? Oder vielleicht, wie ich oft geweint und meine Cousinen und Freundinnen vermisst",hatte?,"«Der Löwe, der übrigens auch so hiess, einfach nur ''Löwe''», ich wusste nämlich keinen anderen","Namen für ihn, «der Löwe war, nachdem er mit meinem Grossvater gekämpft hatte, sanft geworden,","spielte sogar mit mir und meiner Schwester im Garten. Wir mussten uns nicht mehr fürchten. Ich","glaube, mein Grossvater hatte ihm etwas ins Ohr geflüstert, einen Geheimnamen vielleicht, wie man","das bei den kleinen Kindern macht, um ihnen ihren Namen zu geben, man flüstert ihren Namen drei","Mal in ihr Ohr. Der Löwe war bestimmt nur darum böse gewesen, weil wir ihm keinen Namen gege-","ben hatten.»","«Treffen wir uns doch irgendwann einmal», meinte Sarah distanziert, «ich würde dich gerne wieder-","sehen. Wir haben uns schon so lange nicht gesprochen. Ich wollte dich anrufen. Aber ich arbeite viel","in der letzten Zeit und komme zu nichts. Ausserdem bin ich wieder umgezogen. Komm mich doch","besuchen, ich würde mich wirklich freuen.»","Ich sagte «ja» und drückte sie fest an mich. Ihre Handflächen klopften leicht auf meinen Rücken. «Ich","rufe dich nächste Woche an, versprochen!», rief sie mir noch über die Schultern zurückblickend zu,","bevor sie in einer Gasse verschwand.","Heute war es an mir, ihr misstrauisch nachzuschauen."}', '2026-02-22 22:49:47.642167+00', '2026-02-22 22:49:47.642167+00'),
	('german-2023-qwen', 'Deutsch 2023 (Langgymnasium)', 'German', 2023, 'Qwen 3 Max', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch.", "Du darfst wählen, in welcher Reihenfolge du die Aufgaben löst.", "In den Aufgaben 5, 6, 7, 9, 11, 12 und 13 führen Rechtschreib- und Grammatikfehler zu einem Punkteabzug."], "maxPoints": 51}, "questions": [{"id": "german23-1", "type": "input", "number": 1, "prompt": "a) Woher kommt Meral ursprünglich?\n\nb) Welches Geschlecht hat Meral?", "context": "", "subTasks": [{"id": "1a", "label": "a)", "prompt": "", "correctAnswer": "Kosovo"}, {"id": "1b", "label": "b)", "prompt": "", "correctAnswer": "weiblich"}]}, {"id": "german23-2", "type": "input", "number": 2, "prompt": "Es gibt in der Geschichte einen Zeitsprung von der Gegenwart in die Vergangenheit und wieder zurück in die Gegenwart. Das nennt man Rückblende.\n\na) Wo beginnt und endet die Rückblende in die Vergangenheit? Gib die entsprechenden Zeilen an.\n\nb) Vor wie vielen Jahren hat das Gespräch über die Elefanten im Garten stattgefunden?", "context": "", "subTasks": [{"id": "2a-start", "label": "Beginn Zeile", "prompt": "", "correctAnswer": "10"}, {"id": "2a-end", "label": "Ende Zeile", "prompt": "", "correctAnswer": "41"}, {"id": "2b", "label": "b)", "prompt": "", "correctAnswer": "20"}]}, {"id": "german23-3", "type": "text-area", "number": 3, "prompt": "Gleich im ersten Abschnitt wird deutlich, dass Meral das Verhalten von Sarah beim Wiedersehen als zurückhaltend empfindet. Halte stichwortartig vier Punkte fest, die dies verdeutlichen.", "context": "", "subTasks": [{"id": "3a", "label": "1.", "prompt": "", "modelAnswer": "schwächere Umarmung"}, {"id": "3b", "label": "2.", "prompt": "", "modelAnswer": "behauptet, wenig Zeit zu haben"}, {"id": "3c", "label": "3.", "prompt": "", "modelAnswer": "spricht mit leiser Stimme"}, {"id": "3d", "label": "4.", "prompt": "", "modelAnswer": "lächelt verlegen"}]}, {"id": "german23-4", "type": "input", "number": 4, "prompt": "In welchem Satz wird eindeutig klar, dass Meral erst durch Sarah auf den Namen Dumbo gekommen ist? Schreibe diesen einen Satz vollständig ab.", "context": "", "subTasks": [{"id": "4a", "label": "", "prompt": "", "modelAnswer": "Ich hätte auf die Schnelle keinen besseren erfinden können."}]}, {"id": "german23-5", "type": "input", "number": 5, "prompt": "a) Welches Haus entspricht am ehesten jenem, in welchem Merals Familie gemäss dem Gespräch gelebt haben soll? Gib die richtige Ziffer an.\n\nb) Nenne drei verschiedene Gründe für deine Wahl. Beziehe dich nur auf die sichtbaren Dinge und die unten aufgeführten Punkte (Lage, Gelände um das Gebäude und Merkmale am Gebäude). Stütze dich dabei auf Informationen aus dem Text.", "context": "", "subTasks": [{"id": "5a", "label": "a)", "prompt": "", "correctAnswer": "2"}, {"id": "5b1", "label": "1. Lage:", "prompt": "Das von mir gewählte Gebäude liegt", "modelAnswer": "ausserhalb des Dorfes"}, {"id": "5b2", "label": "2. Gelände:", "prompt": "Das von mir gewählte Gebäude hat", "modelAnswer": "einen Garten mit Bäumen"}, {"id": "5b3", "label": "3. Merkmale:", "prompt": "Das von mir gewählte Gebäude verfügt als einziges über", "modelAnswer": "Fenster im Erdgeschoss und im oberen Stock"}]}, {"id": "german23-6", "type": "text-area", "number": 6, "prompt": "a) Der Alltag von Merals Eltern in der Schweiz war von Stress und Sorgen geprägt. Erkläre, weshalb die Familie in den Schulferien nicht ins Ausland reisen konnte und die Kinder keine tollen Geschenke von den Eltern erhielten.\n\nb) Mit welchem Verhalten reagierte Meral gegenüber Sarah auf diese schwierige Situation bei sich zuhause? Antworte in einem ganzen Satz.", "context": "", "subTasks": [{"id": "6a", "label": "a.", "prompt": "", "modelAnswer": "Als Asylbewerber durften sie weder arbeiten noch reisen, daher hatten sie kein Geld."}, {"id": "6b", "label": "b.", "prompt": "", "modelAnswer": "Sie erfand Geschichten und log."}]}, {"id": "german23-7", "type": "text-area", "number": 7, "prompt": "Laut Meral hat der Grossvater den Löwen besänftigt, der angeblich in ihrem Garten gelebt hat. Das klingt unglaubwürdig. Zähle vier weitere Aussagen über den Grossvater auf, die an Merals Löwengeschichte unglaubwürdig sind.", "context": "", "subTasks": [{"id": "7a", "label": "1. Der Grossvater hat angeblich", "prompt": "", "modelAnswer": "1000 Kriege erlebt."}, {"id": "7b", "label": "2. Der Grossvater hat angeblich", "prompt": "", "modelAnswer": "nach dem Angriff nur zerrissene Hosen gehabt."}, {"id": "7c", "label": "3. Der Grossvater hat angeblich", "prompt": "", "modelAnswer": "dem Löwen einen Geheimnamen ins Ohr geflüstert."}, {"id": "7d", "label": "4. Der Grossvater hat angeblich", "prompt": "", "modelAnswer": "den Löwen ohne Verletzung besiegt."}]}, {"id": "german23-8", "rows": [{"id": "8a", "text": "Die Familie lebte unter anderem vom Eintrittsgeld, das sie für den Besuch ihrer Tiere verlangte."}, {"id": "8b", "text": "Der Grossvater lebte im Kosovo mit Merals Familie im selben Haushalt."}, {"id": "8c", "text": "Sarah bezweifelte als Zweitklässlerin den Wahrheitsgehalt von Merals Geschichten."}, {"id": "8d", "text": "Während sich Merals Familie in der Schweiz um Asyl bewarb, arbeitete die Mutter als Übersetzerin."}, {"id": "8e", "text": "Meral ist sich nicht sicher, ob Sarah sie in der kommenden Woche wirklich anrufen wird."}, {"id": "8f", "text": "Meral behauptet, sie wolle die Ohren von Sarah schonen."}, {"id": "8g", "text": "Am Anfang des Gesprächs in der Altstadt kennt Meral die aktuelle Adresse von Sarah."}, {"id": "8h", "text": "Meral hat eine ältere Schwester."}, {"id": "8i", "text": "Meral hat mehrere Cousinen."}], "type": "table-select", "number": 8, "prompt": "Kreuze bei den folgenden Aussagen an, ob sie mit den Informationen, die uns der Text gibt, übereinstimmen (✓) oder nicht (–). Setze das Kreuz beim Fragezeichen (?), wenn das aufgrund des Textes nicht entschieden werden kann. Es darf nur ein Kreuz pro Zeile gesetzt werden.", "columns": [{"id": "correct", "label": "✓"}, {"id": "unknown", "label": "?"}, {"id": "incorrect", "label": "–"}], "context": "", "subTasks": [], "correctTableAnswers": {"8a": "incorrect", "8b": "unknown", "8c": "correct", "8d": "incorrect", "8e": "correct", "8f": "incorrect", "8g": "incorrect", "8h": "unknown", "8i": "correct"}}, {"id": "german23-9", "type": "text-area", "number": 9, "prompt": "Sarah und Meral verhalten sich spiegelbildlich. Erkläre diese Aussage, indem du die Wörter «Vergangenheit» und «Gegenwart», «schwindelt an» und «zweifelt an» mit dem jeweiligen Verhalten von Meral und Sarah in Verbindung bringst. Die vier fettgedruckten Begriffe müssen in deiner Antwort mindestens einmal vorkommen.", "context": "", "subTasks": [{"id": "9a", "label": "", "prompt": "", "modelAnswer": "In der Vergangenheit schwindelte Meral Sarah an und Sarah zweifelte an Merals Geschichten. In der Gegenwart schwindelt Sarah Meral an und Meral zweifelt an Sarahs Aussagen."}]}, {"id": "german23-10", "type": "multiple-choice", "number": 10, "prompt": "Kreuze jeweils nur die eine Lösung an, die der Bedeutung der fett gedruckten Wörter und Ausdrücke am besten entspricht. Deine Lösung muss inhaltlich zum Text passen.", "context": "", "subTasks": [{"id": "10a", "label": "«Ich schlenderte durch die Marktgasse...» (Z. 1)", "options": ["trottete", "pilgerte", "bummelte", "ging", "marschierte"], "correctAnswer": "bummelte"}, {"id": "10b", "label": "«Ich erklärte Sarah damals scheinbar gleichgültig:...» (Z. 10)", "options": ["gleichmässig", "unbeteiligt", "freudlos", "verbittert", "abgebrüht"], "correctAnswer": "unbeteiligt"}, {"id": "10c", "label": "«Grossvater hatte nach diesem Angriff nur zerrissene Hosen.» (Z. 24/25)", "options": ["geschlissene", "verschleisste", "löchrige", "zerfetzte", "abgerissene"], "correctAnswer": "zerfetzte"}, {"id": "10d", "label": "«Der Löwe war sanft geworden.» (Z. 36)", "options": ["zart", "wohlwollend", "zahm", "herzlich", "gnädig"], "correctAnswer": "zahm"}, {"id": "10e", "label": "«... meinte Sarah distanziert,...» (Z. 42)", "options": ["aus der Ferne", "zugeknöpft", "böse", "barsch", "unhöflich"], "correctAnswer": "zugeknöpft"}]}, {"id": "german23-11", "type": "input", "number": 11, "prompt": "a) Kombiniere den Verbstamm von «greifen» jeweils mit einem zum Satz passenden Vormorphem und setze die richtige Lösung in die Lücke.\n\nb) Kombiniere den Verbstamm von «bringen» jeweils mit einem zum Satz passenden Vormorphem und setze die richtige Lösung in die Lücke.", "context": "", "subTasks": [{"id": "11a1", "label": "Der Löwe hatte endlich", "prompt": "", "correctAnswer": "begriffen"}, {"id": "11a2", "label": "Die Polizei hätte ... hart", "prompt": "", "correctAnswer": "durchgreifen"}, {"id": "11b1", "label": "Die Lehrerin musste viel Geduld", "prompt": "", "correctAnswer": "aufbringen"}, {"id": "11b2", "label": "Wir mussten den Nachweis", "prompt": "", "correctAnswer": "erbringen"}]}, {"id": "german23-12", "type": "input", "number": 12, "prompt": "Fülle die Lücken mit den jeweils verlangten Verben zuerst im Präsens, dann im Präteritum korrekt aus.", "context": "", "subTasks": [{"id": "12a-pres", "label": "ertragen – Präsens:", "prompt": "", "correctAnswer": "Erträgst"}, {"id": "12a-past", "label": "ertragen – Präteritum:", "prompt": "", "correctAnswer": "Ertrugst"}, {"id": "12b-pres", "label": "treffen – Präsens:", "prompt": "", "correctAnswer": "Triffst"}, {"id": "12b-past", "label": "treffen – Präteritum:", "prompt": "", "correctAnswer": "Trafst"}, {"id": "12c-pres", "label": "heissen – Präsens:", "prompt": "", "correctAnswer": "Heisst"}, {"id": "12c-past", "label": "heissen – Präteritum:", "prompt": "", "correctAnswer": "Hiessest"}, {"id": "12d-pres", "label": "empfehlen – Präsens:", "prompt": "", "correctAnswer": "Empfiehlst"}, {"id": "12d-past", "label": "empfehlen – Präteritum:", "prompt": "", "correctAnswer": "Empfahlst"}, {"id": "12e-pres", "label": "halten – Präsens:", "prompt": "", "correctAnswer": "Hältst"}, {"id": "12e-past", "label": "halten – Präteritum:", "prompt": "", "correctAnswer": "Hieltst"}]}, {"id": "german23-13", "type": "input", "number": 13, "prompt": "Bilde – ausgehend vom Wortstamm (Stamm-Morphem) der fett gedruckten Wörter – ein neues Wort aus derselben Wortfamilie. Es muss in die Lücke passen.", "context": "", "subTasks": [{"id": "13a", "label": "Sarah empfand ... ein", "prompt": "Misstrauen.", "correctAnswer": "stetiges"}, {"id": "13b", "label": "da war ein Löwe keine", "prompt": "dagegen.", "correctAnswer": "Besonderheit"}, {"id": "13c", "label": "Weil meine Eltern ... verbrachten,", "prompt": "sie oft.", "correctAnswer": "stritten"}, {"id": "13d", "label": "der Löwe ... die", "prompt": "in Person zu sein.", "correctAnswer": "Sanftmut"}, {"id": "13e", "label": "Meral und Sarah waren ...", "prompt": "", "correctAnswer": "Freundinnen"}]}, {"id": "german23-14", "type": "text-area", "number": 14, "prompt": "Stelle die folgenden Sätze wie im Beispiel dar und gib zu den einzelnen Wortgruppen jeweils die passende Frage an.", "context": "Beispiel: Meral erinnert ihren Grossvater an den Kampf.\nMeral wer?\nihren Grossvater wen?\nan den Kampf. woran?", "subTasks": [{"id": "14a1", "label": "Am Anfang", "prompt": "", "modelAnswer": "wann?"}, {"id": "14a2", "label": "Herr Lang", "prompt": "", "modelAnswer": "wer?"}, {"id": "14a3", "label": "die Klasse", "prompt": "", "modelAnswer": "wen?"}, {"id": "14a4", "label": "nach Ferienerlebnissen.", "prompt": "", "modelAnswer": "wonach?"}, {"id": "14b1", "label": "Geheimnamen", "prompt": "", "modelAnswer": "was?"}, {"id": "14b2", "label": "der Grossvater", "prompt": "", "modelAnswer": "wer?"}, {"id": "14b3", "label": "dem Löwen", "prompt": "", "modelAnswer": "wem?"}, {"id": "14b4", "label": "ins Ohr", "prompt": "", "modelAnswer": "wohin?"}]}, {"id": "german23-15", "type": "input", "number": 15, "prompt": "Die Sätze unten haben eine korrekte Rechtschreibung, weisen aber jeweils genau einen Grammatikfehler auf. Korrigiere diese Fehler, indem du je ein Wort durchstreichst und ein anderes darüberschreibst.", "context": "", "subTasks": [{"id": "15a", "label": "a.", "prompt": "Erst wenn Meral 28 Jahre alt war, begegneten sich die beiden zufällig wieder.", "correctAnswer": "trafen"}, {"id": "15b", "label": "b.", "prompt": "Sarah hatte keine Zeit zum Plaudern, weil sie hatte noch viel zu erledigen.", "correctAnswer": "hatte"}, {"id": "15c", "label": "c.", "prompt": "Sarah war damals von allen Schülerinnen in der Klasse die Einzigste, die mit Meral spielte.", "correctAnswer": "Einzige"}, {"id": "15d", "label": "d.", "prompt": "Sarah ist immer etwa eine Handbreit grösser gewesen wie Meral.", "correctAnswer": "als"}, {"id": "15e", "label": "e.", "prompt": "Sarah schaute Meral nicht in die Augen und versprach: «Ich rufe dir nächste Woche an!»", "correctAnswer": "dich"}, {"id": "15f", "label": "f.", "prompt": "Meral war sichtlich enttäuscht und sass auf eine Parkbank, um sich etwas zu sammeln.", "correctAnswer": "eine"}]}]}', '{"Ich schlenderte durch die Marktgasse und traf zufällig auf Sarah. Sie sah aus wie früher. Wenn","ich Sarah auch Ewigkeiten nicht mehr gesehen hatte, erkannte ich sie dennoch sofort wieder.","Sarah war zurückhaltend. Bei der Umarmung, bei der wir uns zur Begrüssung drückten, war","ich diejenige, die fester drückte. Sie habe nicht viel Zeit, sie müsse gleich weiter, sagte sie zu","Beginn mit einer so leisen Stimme, als wollte sie meine Ohren schonen. Ob sie nicht doch Zeit","hätte, mit mir wenigstens eine Tasse Tee trinken zu gehen? Sie habe keine Zeit, wiederholte","sie und lächelte dabei verlegen, als ob ich die Wahrheit nicht ertragen könnte. Ich erinnerte","mich an eines unserer ersten Gespräche zurück, als habe es erst gestern und nicht vor","zwanzig Jahren in der zweiten Klasse der Primarschule stattgefunden.","Ich erklärte Sarah damals scheinbar gleichgültig: «Im Kosovo wohnten wir vor dem Krieg","ausserhalb des Dorfes, wir hatten Elefanten im Garten. Der kleinste steckte seinen Kopf","durch das Fenster in mein Zimmer im Erdgeschoss und wollte mit Nüssen gefüttert werden.»","«Wie Dumbo, der Elefant aus dem Trickfilm?», wollte Sarah staunend wissen.","«Ja, genau wie der hat er geheissen.» Dieser Name passte gut zu ihm. Ich hätte auf die","Schnelle keinen besseren erfinden können. «Ich wollte noch eine Giraffe, doch mein Vater","meinte, die würde dann sogar noch über die Fenster der zweiten Etage hinauswachsen,","sodass die Leute im Dorf sie sehen könnten. Wir aber wollten unsere Tiere geheim halten,","damit niemand sie uns wegnehmen konnte.» «Weshalb sollte euch jemand die Tiere","wegnehmen, Meral? Und habt ihr die Tiere mit in die Schweiz genommen?» Sarah war","misstrauisch meinen Geschichten gegenüber. Jedes Mal, wenn ich ihr damals von meiner","Heimat erzählte, stellte sie mir viele Fragen.","«Wir hatten sogar einen Löwen im Garten, der war gefährlich. Einmal hat der Löwe meinen","Grossvater angegriffen, doch der hat sich selbst helfen können. Tausend Kriege hatte er da","schon erlebt, da war ein Löwe rein gar nichts dagegen. Mein Grossvater hatte nach diesem","Angriff nur zerrissene Hosen.» «Ihr hattet einen Löwen als Haustier?», fragte Sarah zweifelnd.","Ich konnte nicht damit aufhören, ich hatte sonst ja nichts zu erzählen, nicht von Auslandferien","oder von tollen Geschenken zum Geburtstag oder von Ausflügen. Was hätte ich denn erzählen","sollen nach den Ferien, wenn Herr Lang uns im Unterricht fragte, was wir Spannendes","erlebt hätten? Hätte ich vielleicht erzählen sollen, dass meine Eltern sich oft gestritten hatten,","weil sie sich jeden Tag Sorgen machten? Dass sie als Asylbewerber* nicht arbeiten und","reisen durften, uns Mädchen anschrien? Oder wie ich alleine war, weil niemand mich","angerufen hatte, und dass ich mich die ganze Zeit über gelangweilt hatte? Oder vielleicht,","wie ich oft geweint und meine Cousinen und Freundinnen vermisst hatte?","«Der Löwe, der übrigens auch so hiess, einfach nur ‘Löwe’», ich wusste nämlich keinen","anderen Namen für ihn, «der Löwe war, nachdem er mit meinem Grossvater gekämpft hatte,","sanft geworden, spielte sogar mit mir und meiner Schwester im Garten. Wir mussten uns","nicht mehr fürchten. Ich glaube, mein Grossvater hatte ihm etwas ins Ohr geflüstert, einen","Geheimnamen vielleicht, wie man das bei den kleinen Kindern macht, um ihnen ihren Namen","zu geben, man flüstert ihren Namen drei Mal in ihr Ohr. Der Löwe war bestimmt nur darum","böse gewesen, weil wir ihm keinen Namen gegeben hatten.» «Treffen wir uns doch","irgendwann einmal», meinte Sarah distanziert, «ich würde dich gerne wiedersehen. Wir","haben uns schon so lange nicht gesprochen. Ich wollte dich anrufen. Aber ich arbeite viel","in der letzten Zeit und komme zu nichts. Ausserdem bin ich wieder umgezogen. Komm mich","doch besuchen, ich würde mich wirklich freuen.» Ich sagte «ja» und drückte sie fest an mich.","Ihre Handflächen klopften leicht auf meinen Rücken. «Ich rufe dich nächste Woche an,","versprochen!», rief sie mir noch über die Schultern zurückblickend zu, bevor sie in einer","Gasse verschwand. Heute war es an mir, ihr misstrauisch nachzuschauen."}', '2026-02-22 22:49:47.709977+00', '2026-02-22 22:49:47.709977+00'),
	('german-2023', 'Sprachprüfung Deutsch 2023 (Langgymnasium)', 'German', 2023, NULL, '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch.", "Die Reihenfolge darfst du frei wählen.", "In den Aufgaben 5, 6, 7, 9, 11, 12 und 13 führen Rechtschreibe- und Grammatikfehler zu einem Punkteabzug."], "maxPoints": 51}, "questions": [{"id": "g23-1", "type": "input", "number": 1, "prompt": "Fragen zur Person Meral", "subTasks": [{"id": "g23-1a", "label": "a)", "prompt": "Woher kommt Meral ursprünglich?", "modelAnswer": "Kosovo / Kosovo-Albanien / Republik Kosovo"}, {"id": "g23-1b", "label": "b)", "prompt": "Welches Geschlecht hat Meral?", "modelAnswer": "weiblich (Mädchen, Frau)"}]}, {"id": "g23-2", "type": "input", "number": 2, "prompt": "Es gibt in der Geschichte einen Zeitsprung (Rückblende).", "subTasks": [{"id": "g23-2a-start", "label": "a)", "prompt": "Die Rückblende in die Vergangenheit beginnt auf der Zeile", "correctAnswer": 10}, {"id": "g23-2a-end", "label": "und", "prompt": "endet auf der Zeile", "correctAnswer": 41}, {"id": "g23-2b", "label": "b)", "prompt": "Vor wie vielen Jahren hat das Gespräch über die Elefanten im Garten stattgefunden?", "suffix": "Jahren", "correctAnswer": 20}]}, {"id": "g23-3", "type": "text-area", "number": 3, "prompt": "Gleich im ersten Abschnitt wird deutlich, dass Meral das Verhalten von Sarah beim Wiedersehen als zurückhaltend empfindet. Halte stichwortartig vier Punkte fest, die dies verdeutlichen.", "subTasks": [{"id": "g23-3a", "label": "Punkte:", "prompt": "Nenne 4 Beobachtungen.", "modelAnswer": "1. schwächere Umarmung / drückt weniger\n2. (bloss) Ausrede / angeblich keine Zeit\n3. leise Stimme (als ob sie Ohren schonen wolle)\n4. lächelt verlegen\n5. wiederholt Ausrede"}]}, {"id": "g23-4", "type": "text-area", "number": 4, "prompt": "In welchem Satz wird eindeutig klar, dass Meral erst durch Sarah auf den Namen Dumbo gekommen ist? Schreibe diesen einen Satz vollständig ab.", "subTasks": [{"id": "g23-4a", "label": "Antwort:", "prompt": "Satz aus dem Text:", "correctAnswer": "«Ich hätte auf die Schnelle keinen besseren erfinden können.»"}]}, {"id": "g23-5", "type": "input", "number": 5, "prompt": "Betrachte die auf dem Bild sichtbaren Teile der fünf mit Ziffern markierten Gebäude. Lies noch einmal das Gespräch auf den Zeilen 10 bis 17.", "imageUrl": "/images/german-2023/gemini/task-5.png", "subTasks": [{"id": "g23-5a", "label": "a)", "prompt": "Welches Haus entspricht am ehesten jenem, in welchem Merals Familie gemäss diesem Gespräch gelebt haben soll?", "correctAnswer": "2"}, {"id": "g23-5b-1", "label": "b) 1.", "prompt": "Lage: Das von mir gewählte Gebäude liegt...", "modelAnswer": "ausserhalb des Dorfes / versteckt / zwischen Bäumen / so, dass es Sichtschutz bietet"}, {"id": "g23-5b-2", "label": "b) 2.", "prompt": "Gelände um das Gebäude: Das von mir gewählte Gebäude hat...", "modelAnswer": "Verstecke für Tiere / einen Garten / Bäume"}, {"id": "g23-5b-3", "label": "b) 3.", "prompt": "Merkmale am Gebäude: Das von mir gewählte Gebäude verfügt als einziges über...", "modelAnswer": "Fenster auf zwei Etagen / Fenster im Parterre und zweiten Stock"}]}, {"id": "g23-6", "type": "text-area", "number": 6, "prompt": "Der Alltag von Merals Eltern in der Schweiz war von Stress und Sorgen geprägt.", "subTasks": [{"id": "g23-6a", "label": "a)", "prompt": "Erkläre, weshalb die Familie in den Schulferien nicht ins Ausland reisen konnte und die Kinder keine tollen Geschenke erhielten.", "modelAnswer": "Juristisch: Reiseverbot für Asylbewerber. Finanziell: Arbeitsverbot / Armut / kein Geld."}, {"id": "g23-6b", "label": "b)", "prompt": "Mit welchem Verhalten reagierte Meral gegenüber Sarah auf diese schwierige Situation bei sich zuhause?", "modelAnswer": "Sie lügt / schwindelt / erfindet Geschichten / macht sich interessant."}]}, {"id": "g23-7", "type": "text-area", "number": 7, "prompt": "Laut Meral hat der Grossvater den Löwen besänftigt. Zähle vier weitere Aussagen über den Grossvater auf, die unglaubwürdig sind.", "subTasks": [{"id": "g23-7a", "label": "Antwort:", "prompt": "Vervollständige: Der Grossvater hat angeblich...", "modelAnswer": "- schon 1000 Kriege erlebt.\n- den Kampf gewonnen / sich selbst helfen können.\n- bloss zerrissene Hosen gehabt.\n- dem Löwen einen Geheimnamen ins Ohr geflüstert.\n- bewirkt, dass die Kinder mit dem Löwen spielen konnten."}]}, {"id": "g23-8", "rows": [{"id": "r1", "text": "Die Familie lebte unter anderem vom Eintrittsgeld, das sie für den Besuch ihrer Tiere verlangte."}, {"id": "r2", "text": "Der Grossvater lebte im Kosovo mit Merals Familie im selben Haushalt."}, {"id": "r3", "text": "Sarah bezweifelte als Zweitklässlerin den Wahrheitsgehalt von Merals Geschichten."}, {"id": "r4", "text": "Während sich Merals Familie in der Schweiz um Asyl bewarb, arbeitete die Mutter als Übersetzerin."}, {"id": "r5", "text": "Meral ist sich nicht sicher, ob Sarah sie in der kommenden Woche wirklich anrufen wird."}, {"id": "r6", "text": "Meral behauptet, sie wolle die Ohren von Sarah schonen."}, {"id": "r7", "text": "Am Anfang des Gesprächs in der Altstadt kennt Meral die aktuelle Adresse von Sarah."}, {"id": "r8", "text": "Meral hat eine ältere Schwester."}, {"id": "r9", "text": "Meral hat mehrere Cousinen."}], "type": "table-select", "number": 8, "prompt": "Kreuze bei den folgenden Aussagen an, ob sie mit den Informationen des Textes übereinstimmen (✓), nicht (-) oder ob es nicht entschieden werden kann (?).", "columns": [{"id": "c_true", "label": "✓"}, {"id": "c_unknown", "label": "?"}, {"id": "c_false", "label": "-"}], "subTasks": [{"id": "g23-8-sub", "label": "Tabelle", "prompt": "Kreuze an."}], "correctTableAnswers": {"r1": "c_false", "r2": "c_unknown", "r3": "c_true", "r4": "c_false", "r5": "c_true", "r6": "c_false", "r7": "c_false", "r8": "c_unknown", "r9": "c_true"}}, {"id": "g23-9", "type": "text-area", "number": 9, "prompt": "Sarah und Meral verhalten sich spiegelbildlich. Erkläre diese Aussage mit den Wörtern «Vergangenheit», «Gegenwart», «schwindelt an» und «zweifelt an».", "subTasks": [{"id": "g23-9a", "label": "Antwort:", "prompt": "Schreibe ganze Sätze.", "modelAnswer": "In der Vergangenheit schwindelte Meral Sarah an und Sarah zweifelte an Meral. In der Gegenwart schwindelt Sarah Meral an und Meral zweifelt an Sarah."}]}, {"id": "g23-10", "type": "multiple-choice", "number": 10, "prompt": "Kreuze jeweils nur die eine Lösung an, die der Bedeutung der fett gedruckten Wörter und Ausdrücke am besten entspricht.", "subTasks": [{"id": "g23-10a", "label": "a)", "prompt": "«Ich **schlenderte** durch die Marktgasse...» (Z. 1)", "options": ["trottete", "pilgerte", "bummelte", "ging", "marschierte"], "correctAnswer": "bummelte"}, {"id": "g23-10b", "label": "b)", "prompt": "«Ich erklärte Sarah damals scheinbar **gleichgültig**: ...» (Z. 10)", "options": ["gleichmässig", "unbeteiligt", "freudlos", "verbittert", "abgebrüht"], "correctAnswer": "unbeteiligt"}, {"id": "g23-10c", "label": "c)", "prompt": "«Grossvater hatte nach diesem Angriff nur **zerrissene** Hosen.» (Z. 24/25)", "options": ["geschlissene", "verschleisste", "löchrige", "zerfetzte", "abgerissene"], "correctAnswer": "zerfetzte"}, {"id": "g23-10d", "label": "d)", "prompt": "«Der Löwe war **sanft** geworden.» (Z. 36)", "options": ["zart", "wohlwollend", "zahm", "herzlich", "gnädig"], "correctAnswer": "zahm"}, {"id": "g23-10e", "label": "e)", "prompt": "«... meinte Sarah **distanziert**, ...» (Z. 42)", "options": ["aus der Ferne", "zugeknöpft", "böse", "barsch", "unhöflich"], "correctAnswer": "zugeknöpft"}]}, {"id": "g23-11", "type": "input", "number": 11, "prompt": "Kombiniere den Verbstamm jeweils mit einem zum Satz passenden Vormorphem.", "subTasks": [{"id": "g23-11a-1", "label": "a) greifen:", "prompt": "Der Löwe hatte endlich ____, dass mein Grossvater viel stärker war als er.", "correctAnswer": "begriffen"}, {"id": "g23-11a-2", "label": "a) greifen:", "prompt": "Die Polizei hätte gegen Löwenhalter sofort hart ____ müssen.", "modelAnswer": "durchgreifen / eingreifen", "correctAnswer": "durchgreifen"}, {"id": "g23-11b-1", "label": "b) bringen:", "prompt": "Die Lehrerin musste viel Geduld ____, um die Klasse zu beruhigen.", "correctAnswer": "aufbringen"}, {"id": "g23-11b-2", "label": "b) bringen:", "prompt": "Wir mussten den Nachweis ____, dass wir ein Recht auf Asyl hatten.", "correctAnswer": "erbringen"}]}, {"id": "g23-12", "type": "input", "number": 12, "prompt": "Fülle die Lücken mit den jeweils verlangten Verben zuerst im Präsens, dann im Präteritum korrekt aus.", "subTasks": [{"id": "g23-12a-pres", "label": "ertragen (Präsens):", "prompt": "____ du die Schmerzen?", "correctAnswer": "Erträgst"}, {"id": "g23-12a-past", "label": "ertragen (Präteritum):", "prompt": "____ du die Schmerzen?", "correctAnswer": "Ertrugst"}, {"id": "g23-12b-pres", "label": "treffen (Präsens):", "prompt": "____ du das Ziel?", "correctAnswer": "Triffst"}, {"id": "g23-12b-past", "label": "treffen (Präteritum):", "prompt": "____ du das Ziel?", "correctAnswer": "Trafst"}, {"id": "g23-12c-pres", "label": "heissen (Präsens):", "prompt": "____ du in diesem Spiel Karl oder Carlo?", "correctAnswer": "Heisst"}, {"id": "g23-12c-past", "label": "heissen (Präteritum):", "prompt": "____ du in diesem Spiel Karl oder Carlo?", "modelAnswer": "Hiessest / Hiesst", "correctAnswer": "Hiessest"}, {"id": "g23-12d-pres", "label": "empfehlen (Präsens):", "prompt": "____ du ihnen die Abkürzung?", "correctAnswer": "Empfiehlst"}, {"id": "g23-12d-past", "label": "empfehlen (Präteritum):", "prompt": "____ du ihnen die Abkürzung?", "correctAnswer": "Empfahlst"}, {"id": "g23-12e-pres", "label": "halten (Präsens):", "prompt": "____ du dich an die Abmachung?", "correctAnswer": "Hältst"}, {"id": "g23-12e-past", "label": "halten (Präteritum):", "prompt": "____ du dich an die Abmachung?", "modelAnswer": "Hieltst / Hieltest", "correctAnswer": "Hieltst"}]}, {"id": "g23-13", "type": "input", "number": 13, "prompt": "Bilde ausgehend vom Wortstamm der fett gedruckten Wörter ein neues Wort aus derselben Wortfamilie, das in die Lücke passt.", "subTasks": [{"id": "g23-13a", "label": "a)", "prompt": "Sarah war ... **misstrauisch**. -> Sarah empfand meinen Geschichten gegenüber ein", "correctAnswer": "Misstrauen"}, {"id": "g23-13b", "label": "b)", "prompt": "Löwe war nichts **Besonderes**. -> Tausend Kriege hatte er schon erlebt, da war ein Löwe keine", "suffix": "dagegen.", "correctAnswer": "Besonderheit"}, {"id": "g23-13c", "label": "c)", "prompt": "kam es oft zu **Streitigkeiten**. -> Weil meine Eltern all diese Zeit zusammen verbrachten,", "suffix": "sie oft.", "correctAnswer": "stritten"}, {"id": "g23-13d", "label": "d)", "prompt": "Löwe war **sanft** geworden. -> Der Löwe schien die", "suffix": "in Person zu sein.", "modelAnswer": "Sanftmut / Sanftheit / Sanftmütigkeit", "correctAnswer": "Sanftmut"}, {"id": "g23-13e", "label": "e)", "prompt": "waren **befreundet**. -> Meral und Sarah waren in der zweiten Klasse", "modelAnswer": "Freundinnen / Freunde", "correctAnswer": "Freundinnen"}]}, {"id": "g23-14", "type": "input", "number": 14, "prompt": "Gib zu den einzelnen Wortgruppen jeweils die passende Frage an.", "imageUrl": "/images/german-2023/gemini/task-14.png", "subTasks": [{"id": "g23-14a-1", "label": "a)", "prompt": "Am Anfang:", "imageUrl": "/images/german-2023/gemini/task-14-a.png", "correctAnswer": "wann?"}, {"id": "g23-14a-2", "label": "a)", "prompt": "Herr Lang:", "correctAnswer": "wer?"}, {"id": "g23-14a-3", "label": "a)", "prompt": "die Klasse:", "correctAnswer": "wen?"}, {"id": "g23-14a-4", "label": "a)", "prompt": "nach Ferienerlebnissen:", "correctAnswer": "wonach?"}, {"id": "g23-14b-1", "label": "b)", "prompt": "Geheimnamen:", "imageUrl": "/images/german-2023/gemini/task-14-b.png", "modelAnswer": "wen? / was?", "correctAnswer": "wen? / was?"}, {"id": "g23-14b-2", "label": "b)", "prompt": "der Grossvater:", "correctAnswer": "wer?"}, {"id": "g23-14b-3", "label": "b)", "prompt": "dem Löwen:", "correctAnswer": "wem?"}, {"id": "g23-14b-4", "label": "b)", "prompt": "ins Ohr:", "correctAnswer": "wohin?"}]}, {"id": "g23-15", "type": "input", "number": 15, "prompt": "Die Sätze unten weisen jeweils genau einen Grammatikfehler auf. Korrigiere ihn.", "subTasks": [{"id": "g23-15a1", "label": "a) falsches Wort:", "prompt": "Erst wenn Meral 28 Jahre alt war, begegneten sich die beiden zufällig wieder. ->", "correctAnswer": "als"}, {"id": "g23-15a2", "label": "a) korrektur:", "prompt": "Erst wenn Meral 28 Jahre alt war, begegneten sich die beiden zufällig wieder. ->", "correctAnswer": "als"}, {"id": "g23-15b1", "label": "b) falsches Wort:", "prompt": "Sarah hatte keine Zeit zum Plaudern, weil sie hatte noch viel zu erledigen. ->", "correctAnswer": "weil"}, {"id": "g23-15b2", "label": "b) korrektur:", "prompt": "Sarah hatte keine Zeit zum Plaudern, weil sie hatte noch viel zu erledigen. ->", "correctAnswer": "denn"}, {"id": "g23-15c1", "label": "c) falsches Wort:", "prompt": "Sarah war damals die Einzigste, die mit Meral spielte. ->", "correctAnswer": "Einzigste"}, {"id": "g23-15c2", "label": "c) korrektur:", "prompt": "Sarah war damals die Einzigste, die mit Meral spielte. ->", "correctAnswer": "Einzige"}, {"id": "g23-15d1", "label": "d) falsches Wort:", "prompt": "Sarah ist immer etwa eine Handbreit grösser gewesen wie Meral. ->", "correctAnswer": "wie"}, {"id": "g23-15d2", "label": "d) korrektur:", "prompt": "Sarah ist immer etwa eine Handbreit grösser gewesen wie Meral. ->", "correctAnswer": "als"}, {"id": "g23-15e1", "label": "e) falsches Wort", "prompt": "«Ich rufe dir nächste Woche an!» ->", "correctAnswer": "dir"}, {"id": "g23-15e2", "label": "e) korrektur", "prompt": "«Ich rufe dir nächste Woche an!» ->", "correctAnswer": "dich"}, {"id": "g23-15f1", "label": "f) falsches Wort:", "prompt": "Meral war sichtlich enttäuscht und sass auf eine Parkbank, um sich etwas zu sammeln. ->", "correctAnswer": "sass"}, {"id": "g23-15f2", "label": "f) korrektur:", "prompt": "Meral war sichtlich enttäuscht und sass auf eine Parkbank, um sich etwas zu sammeln. ->", "correctAnswer": "setzte sich"}]}]}', '{"Ich schlenderte durch die Marktgasse und traf zufällig auf Sarah. Sie sah aus wie früher. Wenn ich","Sarah auch Ewigkeiten nicht mehr gesehen hatte, erkannte ich sie dennoch sofort wieder. Sarah war","zurückhaltend. Bei der Umarmung, bei der wir uns zur Begrüssung drückten, war ich diejenige, die","fester drückte. Sie habe nicht viel Zeit, sie müsse gleich weiter, sagte sie zu Beginn mit einer so leisen","Stimme, als wollte sie meine Ohren schonen. Ob sie nicht doch Zeit hätte, mit mir wenigstens eine","Tasse Tee trinken zu gehen? Sie habe keine Zeit, wiederholte sie und lächelte dabei verlegen, als ob","ich die Wahrheit nicht ertragen könnte. Ich erinnerte mich an eines unserer ersten Gespräche zurück,","als habe es erst gestern und nicht vor zwanzig Jahren in der zweiten Klasse der Primarschule stattge-",funden.,"Ich erklärte Sarah damals scheinbar gleichgültig: «Im Kosovo wohnten wir vor dem Krieg ausserhalb","des Dorfes, wir hatten Elefanten im Garten. Der kleinste steckte seinen Kopf durch das Fenster in","mein Zimmer im Erdgeschoss und wollte mit Nüssen gefüttert werden.»","«Wie Dumbo, der Elefant aus dem Trickfilm?», wollte Sarah staunend wissen.","«Ja, genau wie der hat er geheissen.» Dieser Name passte gut zu ihm. Ich hätte auf die Schnelle keinen","besseren erfinden können. «Ich wollte noch eine Giraffe, doch mein Vater meinte, die würde dann","sogar noch über die Fenster der zweiten Etage hinauswachsen, sodass die Leute im Dorf sie sehen","könnten. Wir aber wollten unsere Tiere geheim halten, damit niemand sie uns wegnehmen konnte.»","«Weshalb sollte euch jemand die Tiere wegnehmen, Meral? Und habt ihr die Tiere mit in die Schweiz",genommen?»,"Sarah war misstrauisch meinen Geschichten gegenüber. Jedes Mal, wenn ich ihr damals von meiner","Heimat erzählte, stellte sie mir viele Fragen.","«Wir hatten sogar einen Löwen im Garten, der war gefährlich. Einmal hat der Löwe meinen Gross-","vater angegriffen, doch der hat sich selbst helfen können. Tausend Kriege hatte er da schon erlebt, da","war ein Löwe rein gar nichts dagegen. Mein Grossvater hatte nach diesem Angriff nur zerrissene",Hosen.»,"«Ihr hattet einen Löwen als Haustier?», fragte Sarah zweifelnd.","Ich konnte nicht damit aufhören, ich hatte sonst ja nichts zu erzählen, nicht von Auslandferien oder","von tollen Geschenken zum Geburtstag oder von Ausflügen. Was hätte ich denn erzählen sollen nach","den Ferien, wenn Herr Lang uns im Unterricht fragte, was wir Spannendes erlebt hätten? Hätte ich","vielleicht erzählen sollen, dass meine Eltern sich oft gestritten hatten, weil sie sich jeden Tag Sorgen","machten? Dass sie als Asylbewerber nicht arbeiten und reisen durften, uns Mädchen anschrien? Oder","wie ich alleine war, weil niemand mich angerufen hatte, und dass ich mich die ganze Zeit über ge-","langweilt hatte? Oder vielleicht, wie ich oft geweint und meine Cousinen und Freundinnen vermisst",hatte?,"«Der Löwe, der übrigens auch so hiess, einfach nur ''Löwe''», ich wusste nämlich keinen anderen","Namen für ihn, «der Löwe war, nachdem er mit meinem Grossvater gekämpft hatte, sanft geworden,","spielte sogar mit mir und meiner Schwester im Garten. Wir mussten uns nicht mehr fürchten. Ich","glaube, mein Grossvater hatte ihm etwas ins Ohr geflüstert, einen Geheimnamen vielleicht, wie man","das bei den kleinen Kindern macht, um ihnen ihren Namen zu geben, man flüstert ihren Namen drei","Mal in ihr Ohr. Der Löwe war bestimmt nur darum böse gewesen, weil wir ihm keinen Namen gege-","ben hatten.»","«Treffen wir uns doch irgendwann einmal», meinte Sarah distanziert, «ich würde dich gerne wieder-","sehen. Wir haben uns schon so lange nicht gesprochen. Ich wollte dich anrufen. Aber ich arbeite viel","in der letzten Zeit und komme zu nichts. Ausserdem bin ich wieder umgezogen. Komm mich doch","besuchen, ich würde mich wirklich freuen.»","Ich sagte «ja» und drückte sie fest an mich. Ihre Handflächen klopften leicht auf meinen Rücken. «Ich","rufe dich nächste Woche an, versprochen!», rief sie mir noch über die Schultern zurückblickend zu,","bevor sie in einer Gasse verschwand. Heute war es an mir, ihr misstrauisch nachzuschauen."}', '2026-02-22 22:49:47.768087+00', '2026-02-22 22:49:47.768087+00'),
	('german-2024-claude', 'Sprachprüfung Deutsch 2024 (Langgymnasium)', 'German', 2024, 'Claude Opus 4.5', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch. Du brauchst ihn zur Lösung der folgenden Aufgaben.", "Du darfst wählen, in welcher Reihenfolge du die Aufgaben löst.", "In den Aufgaben 4, 7, 8, 11, 14 und 15 führen Rechtschreib- und Grammatikfehler zu einem Punkteabzug.", "Du hast 45 Minuten Zeit."], "maxPoints": 46}, "questions": [{"id": "g24-1", "type": "input", "number": 1, "prompt": "Die Brücke wird am Anfang (Zeilen 1-8) mit zwei Adjektiven beschrieben, die beide «sehr gross» bedeuten. Notiere die zwei Adjektive.", "subTasks": [{"id": "g24-1a", "label": "1. Adjektiv:", "correctAnswer": "gigantisch"}, {"id": "g24-1b", "label": "2. Adjektiv:", "correctAnswer": "riesig"}]}, {"id": "g24-2", "type": "input", "number": 2, "prompt": "Begründe, warum Jans Mutter gemäss dem Text nicht auf die Brücke mitkommt. Vervollständige dazu den Satz grammatikalisch korrekt mit zwei Wörtern. Verändere die vorgegebenen Bestandteile des Satzes nicht.", "context": "Jans Mutter bleibt auf dem Parkplatz, denn sie leidet ___.", "subTasks": [{"id": "g24-2a", "label": "Ergänzung:", "modelAnswer": "an Höhenangst / unter Höhenangst", "correctAnswer": "an/unter Höhenangst"}]}, {"id": "g24-3", "type": "text-area", "number": 3, "prompt": "Jan und sein Vater haben unterschiedliche Gründe für die Wanderung.", "subTasks": [{"id": "g24-3a", "label": "a)", "prompt": "In den Zeilen 9-11 wird Jans Grund angegeben, die Wanderung zu unternehmen. Formuliere seinen Grund. Die Wörter «ernst» und «gemeinsam» darfst du nicht verwenden.", "modelAnswer": "Jan will zeigen, dass er etwas zusammen mit der Familie / dem Vater / den Eltern erleben / unternehmen will. Er möchte nicht kindisch scheinen."}, {"id": "g24-3b", "label": "b)", "prompt": "In den Zeilen 12 und 13 wird der Grund von Jans Vater angegeben, die Wanderung auf die Brücke zu unternehmen. Formuliere seinen Grund. In deiner Antwort müssen die Wörter «auslassen» und «Meisterleistung» vorkommen.", "modelAnswer": "Der Vater lässt keine Gelegenheit aus, technische Meisterleistungen anzuschauen / zu bestaunen."}]}, {"id": "g24-4", "type": "text-area", "number": 4, "prompt": "Auf der Brücke angekommen sieht Jan die tief unter ihm liegende Wasseroberfläche (Sehsinn). Zusätzlich nimmt er die Situation auf Zeilen 14-22 auch mit anderen Sinnen wahr. Formuliere in drei vollständigen Sätzen, was genau Jan mit weiteren Sinnen wahrnimmt. Jeder Sinn und jedes Beispiel dürfen nur einmal vorkommen.", "subTasks": [{"id": "g24-4a", "label": "1.", "modelAnswer": "Er spürt/fühlt den Wind im Gesicht. (Tastsinn)"}, {"id": "g24-4b", "label": "2.", "modelAnswer": "Er hört den ohrenbetäubenden Lärm der Lastwagen/Fahrzeuge. (Hörsinn)"}, {"id": "g24-4c", "label": "3.", "modelAnswer": "Er schmeckt/riecht die salzige Meeresluft. (Geschmacks-/Geruchssinn) ODER Er nimmt das Beben/Schwingen der Brücke wahr. (Gleichgewichtssinn)"}]}, {"id": "g24-5", "rows": [{"id": "r1", "text": "Susan und die Mutter suchen sich auf dem Parkplatz ein schattiges Plätzchen."}, {"id": "r2", "text": "Jan und sein Vater brauchen eine Stunde für den Weg vom Parkplatz bis zum Scheitel der Brücke."}, {"id": "r3", "text": "Jans Vater ist Ingenieur von Beruf."}, {"id": "r4", "text": "Jan mag seine Schwester nicht."}, {"id": "r5", "text": "Die Brücke führt über eine Meerenge."}, {"id": "r6", "text": "Jan und sein Vater überqueren die Brücke ganz."}], "type": "table-select", "number": 5, "prompt": "Kreuze bei den folgenden Aussagen an, ob sie mit dem Inhalt der Geschichte übereinstimmen (✓) oder nicht (–). Setze das Kreuz beim Fragezeichen (?), wenn das nicht entschieden werden kann. Es darf nur ein Kreuz pro Zeile gesetzt werden.", "columns": [{"id": "yes", "label": "✓"}, {"id": "no", "label": "–"}, {"id": "unknown", "label": "?"}], "subTasks": [{"id": "g24-5a", "label": "Tabelle"}], "correctTableAnswers": {"r1": "yes", "r2": "unknown", "r3": "unknown", "r4": "unknown", "r5": "no", "r6": "no"}}, {"id": "g24-6", "type": "text-area", "number": 6, "prompt": "Im Text verspürt Jan Angst.", "subTasks": [{"id": "g24-6a", "label": "a)", "prompt": "Formuliere in eigenen Worten, um welche Angst es sich handelt.", "modelAnswer": "Die Angst, den Vater zu verlieren / die Angst davor, dass der Vater stirbt / die Angst vor dem Tod des Vaters."}, {"id": "g24-6b", "label": "b)", "prompt": "Gib die Zeile an, in welcher Jan diese Angst ausspricht.", "correctAnswer": "38"}]}, {"id": "g24-7", "type": "text-area", "number": 7, "prompt": "Lies die Zeilen 28 bis 41 nochmals durch. Jan wirkt hier eher wie ein Erwachsener und Jans Vater eher wie ein Kind. Nenne drei Punkte, die zeigen, dass Jan eher die Rolle eines Erwachsenen einnimmt. Formuliere jeweils einen vollständigen Satz.", "subTasks": [{"id": "g24-7a", "label": "1. Was Jan tut:", "modelAnswer": "Jan hält den Vater zurück / beschützt den Vater / sichert ihn an der Brüstung / bändigt den Vater."}, {"id": "g24-7b", "label": "2. Wie Jan aussieht:", "modelAnswer": "Jan ist grösser / stärker als sein Vater."}, {"id": "g24-7c", "label": "3. Worüber Jan nachdenkt:", "modelAnswer": "Er denkt darüber nach, dass er den Vater liebt / Er denkt über den Tod des Vaters nach / Er denkt über die Zukunft nach."}]}, {"id": "g24-8", "type": "text-area", "number": 8, "prompt": "Jan und sein Vater erleben auf der Brücke einen «endlosen Augenblick unerwarteten Glücks» (Z. 35-36). Erkläre in einem vollständigen Satz, was sie so glücklich macht.", "subTasks": [{"id": "g24-8a", "label": "Erklärung:", "modelAnswer": "Sie merken, dass sie zusammengehören / Es wird ihnen bewusst, wie gern sie einander haben / wie wichtig sie füreinander sind / Sie zeigen einander, dass sie einander lieben."}]}, {"id": "g24-9", "rows": [{"id": "r1", "text": "Jans verschmitztes Grinsen drückt aus, dass Jan sich über das Wiedersehen mit der Mutter freut."}, {"id": "r2", "text": "Jans verschmitztes Grinsen drückt aus, dass Jan erleichtert ist, unverletzt wieder zurück zu sein."}, {"id": "r3", "text": "Jans verschmitztes Grinsen drückt aus, dass Jan ganz bewusst nicht erzählt, was er mit dem Vater erlebt hat."}, {"id": "r4", "text": "Jans verschmitztes Grinsen drückt aus, dass Jan die Antwort des Vaters absichtlich nicht klarer ausformuliert."}, {"id": "r5", "text": "Jans verschmitztes Grinsen drückt aus, dass Jan die imposante Brücke gefallen hat."}, {"id": "r6", "text": "Jans verschmitztes Grinsen drückt aus, dass Jan der Mutter absichtlich etwas vorenthält."}], "type": "table-select", "number": 9, "prompt": "Als Jan und der Vater wieder zurück auf dem Parkplatz sind, antwortet Jan auf die Frage der Mutter, was sie auf der Brücke so lange getan hätten, mit einem verschmitzten Grinsen. In der Tabelle unten findest du Erklärungen für dieses verschmitzte Grinsen. Kreuze an: Welche Erklärungen treffen zu (R für richtig), welche nicht (F für falsch)?", "columns": [{"id": "r", "label": "R"}, {"id": "f", "label": "F"}], "context": "Falsch gesetzte Kreuze geben Abzug. Das Auslassen einer Antwort führt zu keinem Abzug. Setze nur ein Kreuz pro Zeile.", "subTasks": [{"id": "g24-9a", "label": "Tabelle"}], "correctTableAnswers": {"r1": "f", "r2": "f", "r3": "r", "r4": "r", "r5": "f", "r6": "r"}}, {"id": "g24-10", "type": "multiple-choice", "number": 10, "prompt": "In jedem Satz ist ein Ausdruck fett hervorgehoben. Unter dem Satz finden sich fünf Ausdrücke. Vier davon sind Synonyme des fett gedruckten Ausdrucks. Ein Ausdruck passt nicht. Streiche nur diesen einen unpassenden Ausdruck durch. Deine Lösungen müssen inhaltlich zum Text passen.", "subTasks": [{"id": "g24-10a", "label": "a)", "prompt": "Der Balkon bedeutete für die Mutter mehr **Stress** als Erholung. (Z. 4-5)", "options": ["Zeitdruck", "Belastung", "Anspannung", "Mühsal", "Strapaze"], "correctAnswer": "Zeitdruck"}, {"id": "g24-10b", "label": "b)", "prompt": "Der Ausflug auf die Brücke **kam nicht in Frage** für sie. (Z. 5)", "options": ["kam nicht in Betracht", "war kein Thema", "war undenkbar", "war fraglich", "war ausgeschlossen"], "correctAnswer": "war fraglich"}, {"id": "g24-10c", "label": "c)", "prompt": "«**Ich bin dabei!**», sagte er deswegen. (Z. 12)", "options": ["Ich komme mit!", "Ich bin tätig!", "Ich nehme teil!", "Ich ziehe mit!", "Ich bin mit von der Partie!"], "correctAnswer": "Ich bin tätig!"}, {"id": "g24-10d", "label": "d)", "prompt": "Aber Jan hielt ihn **fest** im Klammergriff. (Z. 34-35)", "options": ["sicher", "eisern", "entschlossen", "entschieden", "brutal"], "correctAnswer": "brutal"}, {"id": "g24-10e", "label": "e)", "prompt": "«Was habt ihr da oben so lang gemacht?», fragte sie ihren Mann **gereizt**. (Z. 45-46)", "options": ["missgelaunt", "lustlos", "ungehalten", "missmutig", "mürrisch"], "correctAnswer": "lustlos"}]}, {"id": "g24-11", "type": "input", "number": 11, "prompt": "Bilde ausgehend vom Wortstamm (Stamm-Morphem) der fett gedruckten Wörter ein neues Wort aus derselben Wortfamilie, das in die Lücke passt. Es darf nur ein einziges Wort pro Lücke eingesetzt werden. Die Bedeutung des rechten Satzes muss mit der des linken Satzes übereinstimmen. Der Lückentext darf nicht verändert werden.", "subTasks": [{"id": "g24-11a", "label": "a)", "prompt": "Er hatte dem Urlaub mit den Eltern **zugestimmt**. → Für den Urlaub mit den Eltern hatte er seine ___ gegeben.", "correctAnswer": "Zustimmung"}, {"id": "g24-11b", "label": "b)", "prompt": "Jan rief seinem Vater **übermütig** zu, dass er runterspringen wollte. → Mit einem gewissen ___ rief Jan seinem Vater zu, dass er runterspringen wollte.", "correctAnswer": "Übermut"}, {"id": "g24-11c", "label": "c)", "prompt": "Manchmal will man zu viel **riskieren**. → Manchmal geht man zu grosse ___ ein.", "correctAnswer": "Risiken"}, {"id": "g24-11d", "label": "d)", "prompt": "Der Vater gab seinen gespielten **Widerstand** auf. → Der Vater tat nicht mehr so, als ob er ___ würde.", "correctAnswer": "widerstehen"}, {"id": "g24-11e", "label": "e)", "prompt": "Es ergriff ihn ein **berauschendes** Gefühl von Weite und Freiheit. → Er spürte die Weite und die Freiheit wie in einem ___.", "correctAnswer": "Rausch"}]}, {"id": "g24-12", "type": "text-area", "number": 12, "prompt": "Lies die Zeilen 12 und 13 noch einmal. Erkläre, was sich inhaltlich verändert, wenn du «der» auf Zeile 13 durch «er» ersetzt. Ergänze dazu den Satzanfang.", "context": "Wenn «der» durch «er» ersetzt wird, ___", "subTasks": [{"id": "g24-12a", "label": "Ergänzung:", "modelAnswer": "...nutzt Jan jede Gelegenheit. / ...ist nicht mehr klar, dass der Vater gemeint ist. / ...ist Jan (mit «er») gemeint."}]}, {"id": "g24-13", "rows": [{"id": "r1", "text": "Als die **beiden** antrotteten, sprang sie auf."}, {"id": "r2", "text": "Jan nahm das **Beben** der Brücke wahr."}, {"id": "r3", "text": "Wenn du mal nicht mehr **da** bist, wird ein Loch in meinem Leben sein."}, {"id": "r4", "text": "Was habt ihr da oben **heute** gemacht?"}, {"id": "r5", "text": "Die Pfeiler stachen **regelrecht** in den Himmel."}], "type": "table-select", "number": 13, "prompt": "Kreuze an, ob es sich bei den fett gedruckten Wörtern um Nomen, Verben oder Adjektive handelt. Falls sie zu keiner dieser Wortarten gehören, setzt du das Kreuz bei «nichts davon». Es darf nur ein Kreuz pro Zeile gesetzt werden.", "columns": [{"id": "nomen", "label": "Nomen"}, {"id": "verb", "label": "Verb"}, {"id": "adjektiv", "label": "Adjektiv"}, {"id": "nichts", "label": "nichts davon"}], "subTasks": [{"id": "g24-13a", "label": "Tabelle"}], "correctTableAnswers": {"r1": "nomen", "r2": "nomen", "r3": "nichts", "r4": "nichts", "r5": "nichts"}}, {"id": "g24-14", "type": "input", "number": 14, "prompt": "Jeder der folgenden Sätze weist genau einen Fehler auf. Korrigiere diesen Fehler jeweils, indem du ihn durchstreichst und die richtige Lösung über den Fehler schreibst. Korrigiere pro Satz nur einen Fehler.", "subTasks": [{"id": "g24-14a", "label": "a)", "prompt": "Jan und sein Vater sind zuerst nicht sicher, **dass** die Brücke tatsächlich so hoch ist.", "modelAnswer": "dass → ob", "correctAnswer": "ob"}, {"id": "g24-14b", "label": "b)", "prompt": "Jan **erschrak** den Vater, als er ihn plötzlich von hinten packte.", "modelAnswer": "erschrak → erschreckte", "correctAnswer": "erschreckte"}, {"id": "g24-14c", "label": "c)", "prompt": "Die Mutter empfahl: «Ihr nehmt besser einen Rucksack, **daran** trägt ihr nicht so schwer.»", "modelAnswer": "daran → darin (oder: trägt → tragt)", "correctAnswer": "daran → darin"}, {"id": "g24-14d", "label": "d)", "prompt": "«Was hat denn so lange gedauert**.**», nörgelte Jans Schwester.", "modelAnswer": ". → ?", "correctAnswer": "?"}, {"id": "g24-14e", "label": "e)", "prompt": "Wenn **einem** technische Grosstaten interessieren, besichtigt man diese stets gerne.", "modelAnswer": "einem → einen", "correctAnswer": "einen"}, {"id": "g24-14f", "label": "f)", "prompt": "Der Vater wäre gerne noch **höcher** hinaufgestiegen, um die Aussicht zu bewundern.", "modelAnswer": "höcher → höher", "correctAnswer": "höher"}]}, {"id": "g24-15", "type": "text-area", "number": 15, "prompt": "Schreibe die folgenden Sätze in die verlangten Zeitformen um. Du musst die Sätze jeweils vollständig abschreiben.", "subTasks": [{"id": "g24-15a", "label": "a)", "prompt": "Staunend nahm Jan den Lärm wahr, während die Lastwagen vorbeifuhren. → **Perfekt:**", "modelAnswer": "Staunend hat Jan den Lärm wahrgenommen, während die Lastwagen vorbeigefahren sind."}, {"id": "g24-15b", "label": "b)", "prompt": "Jan umgriff seinen Vater. → **Präsens:**", "modelAnswer": "Jan umgreift seinen Vater."}, {"id": "g24-15c", "label": "c)", "prompt": "Der Vater wand sich aus Jans Armen und drehte sich zu ihm um. → **Perfekt:**", "modelAnswer": "Der Vater hat sich aus Jans Armen gewunden und (hat) sich zu ihm umgedreht."}]}]}', '{"Sie hatten nicht erwartet, dass es über eine solch gigantische Brücke auch einen Fussweg geben","könnte. Schon aus mehreren Kilometern Entfernung sah man die Brücke in einem eleganten Bogen","den Fluss überqueren. Die Pfeiler stachen regelrecht in den Himmel.","Doch Jans Mutter hatte solche Höhenangst, dass selbst Kaffeetrinken daheim auf dem Balkon für","sie mehr Stress als Erholung bedeutete. Der Ausflug auf die Brücke kam nicht in Frage für sie.","Susan, Jans Schwester, schmollte seit Paris, wo sie gerne noch ein paar Tage länger geblieben wä-","re, und blieb lieber beleidigt eine Stunde auf dem brütend heissen Parkplatz, statt zum höchsten","Punkt der riesigen Brücke zu wandern.","Jan hatte nichts übrig für solche Kindereien. Mit dem Maturitätszeugnis in der Tasche hatte er dem","gemeinsamen Urlaub mit den Eltern zugestimmt, nun wollte er auch zeigen, dass es ihm ernst war","mit ›gemeinsam‹.","«Ich bin dabei!», sagte Jan deswegen, als ihn sein Vater fragte, ob wenigstens er mitkomme, denn","der nutzte jede Gelegenheit, technische Grosstaten im Detail zu besichtigen.","Der Weg neben den Fahrspuren war zu schmal, um nebeneinander gehen zu können. Staunend","nahm Jan das leichte Beben wahr, das jeder Lastwagen verursachte. Er hörte den ohrenbetäuben-","den Lärm der Fahrzeugflut. Dicht folgte er dem Rücken seines Vaters. Dieser drehte sich um, sah","ihn an, lachte. So etwas wie Kleinbubenglück leuchtete für einen Moment in seinen Augen auf.","«Wir sind gleich oben!», schrie der Vater, lief die letzten Meter und stellte sich breitbeinig über die","Fuge, die den Scheitel der Brücke markierte. Er schaute aufs Meer hinaus. Jan stellte sich neben","ihn. Jeder Lastwagen brachte die Brücke zum Schwingen. Der Wind blies ihm salzige Luft ins Ge-","sicht. Er schaute abwärts, auf die tief unter ihm liegende Wasserfläche, und es ergriff ihn ein be-","rauschendes Gefühl von Weite und Freiheit.","«Jetzt würd'' ich am liebsten runterspringen!», rief Jan übermütig. Er wollte dem Vater Angst ma-","chen, aber der nickte bloss.","«Manchmal will man zu viel riskieren – das kenne ich auch!» Der Vater ging ganz nach vorne ans","Geländer, neigte sich weit darüber und breitete die Arme aus, als wollte er sich in den weiten Luft-","raum zwischen Brücke und Wasser hineingleiten lassen.","«Das wäre doch ''n cooler Abgang! Nicht wahr?», schrie er. Jan hasste es, wenn sein Vater so","sprach wie ein Jugendlicher. Aber diesmal ging er auf das Spiel ein, packte seinen Vater bei der","Jacke, zog ihn mit einem Ruck zurück – vielleicht war es auch wirkliche Angst um ihn –, umgriff","ihn von hinten mit beiden Armen und drückte ihn an sich. Sein Vater war einen Kopf kleiner und","inzwischen bestimmt auch schwächer, sie hatten schon vor Jahren damit aufgehört, im spieleri-","schen Raufen ihre Kraft zu messen.","«Lass mich, lass mich!», schrie der Vater albern und wand sich hin und her. Aber Jan hielt ihn fest","im Klammergriff, bis der Vater seinen gespielten Widerstand aufgab. Für einen endlosen Augen-","blick unerwarteten Glücks standen sie bewegungslos, dann drehte der Vater den Kopf zu ihm um","und strahlte Jan ins Gesicht.","«Wenn du mal nicht mehr da bist, wird ein riesiges, verdammtes Loch in meinem Leben sein!»,","schrie Jan unvermittelt. Er fragte sich, ob es nicht lächerlich war, mit fast neunzehn Jahren so et-","was zu seinem Vater zu sagen. Der Vater wand sich aus Jans Armen und drehte sich zu ihm um.","«Das ist in Ordnung so», sagte er glücklich und nickte dabei, «das muss so sein.»","Noch einen Moment blieben sie ganz vorne an der Brüstung stehen, dann gingen sie denselben","schmalen Fusspfad zurück. Auf dem Parkplatz hatte sich die Mutter mit Susan hinter dem Auto in","den schütteren Schatten eines frischgepflanzten Bäumchens gesetzt. Als die beiden nach einer","Stunde antrotteten, sprang sie auf. «Was habt ihr da oben so lange gemacht?», fragte sie ihren","Mann ein wenig gereizt. «Runtergeguckt», sagte der Vater.","Sie verdrehte die Augen, schüttelte entnervt den Kopf. Dann sah sie Jan fragend an. «Runterge-","guckt!», sagte Jan und grinste verschmitzt."}', '2026-02-22 22:49:47.823197+00', '2026-02-22 22:49:47.823197+00'),
	('german-2024-gemini', 'Sprachprüfung Deutsch 2024 (Langgymnasium)', 'German', 2024, 'Gemini 3 Pro', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch.", "Du darfst wählen, in welcher Reihenfolge du die Aufgaben löst.", "In den Aufgaben 4, 7, 8, 11, 14 und 15 führen Rechtschreib- und Grammatikfehler zu einem Punkteabzug."], "maxPoints": 46}, "questions": [{"id": "g24-1", "type": "input", "number": 1, "prompt": "Die Brücke wird am Anfang (Zeilen 1-8) mit zwei Adjektiven beschrieben, die beide «sehr gross» bedeuten.", "subTasks": [{"id": "g24-1a", "label": "Notiere die zwei Adjektive:", "prompt": "Adjektive aus dem Text:", "modelAnswer": "gigantisch, riesig", "correctAnswer": "gigantisch, riesig"}]}, {"id": "g24-2", "type": "input", "number": 2, "prompt": "Begründe, warum Jans Mutter gemäss dem Text nicht auf die Brücke mitkommt. Vervollständige dazu den Satz grammatikalisch korrekt mit zwei Wörtern.", "subTasks": [{"id": "g24-2a", "label": "Antwort:", "prompt": "Jans Mutter bleibt auf dem Parkplatz, denn sie leidet", "modelAnswer": "an Höhenangst / unter Höhenangst", "correctAnswer": "an Höhenangst"}]}, {"id": "g24-3", "type": "text-area", "number": 3, "prompt": "Jan und sein Vater haben unterschiedliche Gründe für die Wanderung.", "subTasks": [{"id": "g24-3a", "label": "a)", "prompt": "In den Zeilen 9-11 wird Jans Grund angegeben. Formuliere seinen Grund (ohne die Wörter «ernst» und «gemeinsam» zu verwenden):", "modelAnswer": "Jan will zeigen, dass er etwas zusammen mit der Familie / den Eltern unternehmen möchte."}, {"id": "g24-3b", "label": "b)", "prompt": "Formuliere den Grund des Vaters (verwende die Wörter «auslassen» und «Meisterleistung»):", "modelAnswer": "Der Vater lässt keine Gelegenheit aus, technische Meisterleistungen zu besichtigen."}]}, {"id": "g24-4", "type": "text-area", "number": 4, "prompt": "Auf der Brücke nimmt Jan die Situation auch mit anderen Sinnen wahr. Formuliere in drei vollständigen Sätzen, was genau Jan mit weiteren Sinnen wahrnimmt.", "context": "Jeder Sinn und jedes Beispiel dürfen nur einmal vorkommen.", "subTasks": [{"id": "g24-4a", "label": "1.", "prompt": "Satz 1:", "modelAnswer": "Der Wind bläst ihm ins Gesicht (Tastsinn)."}, {"id": "g24-4b", "label": "2.", "prompt": "Satz 2:", "modelAnswer": "Er hört den ohrenbetäubenden Lärm der Lastwagen (Hörsinn)."}, {"id": "g24-4c", "label": "3.", "prompt": "Satz 3:", "modelAnswer": "Er spürt das Beben der Brücke (Gleichgewichtssinn/Tastsinn)."}]}, {"id": "g24-5", "rows": [{"id": "r1", "text": "Susan und die Mutter suchen sich auf dem Parkplatz ein schattiges Plätzchen."}, {"id": "r2", "text": "Jan und sein Vater brauchen eine Stunde für den Weg vom Parkplatz bis zum Scheitel der Brücke."}, {"id": "r3", "text": "Jans Vater ist Ingenieur von Beruf."}, {"id": "r4", "text": "Jan mag seine Schwester nicht."}, {"id": "r5", "text": "Die Brücke führt über eine Meerenge."}, {"id": "r6", "text": "Jan und sein Vater überqueren die Brücke ganz."}], "type": "table-select", "number": 5, "prompt": "Kreuze bei den folgenden Aussagen an, ob sie mit dem Inhalt der Geschichte übereinstimmen (✓) oder nicht (-). Setze das Kreuz beim Fragezeichen (?), wenn das nicht entschieden werden kann.", "columns": [{"id": "c_true", "label": "✓"}, {"id": "c_false", "label": "-"}, {"id": "c_unknown", "label": "?"}], "subTasks": [{"id": "g24-5-sub", "label": "Tabelle", "prompt": "Kreuze an."}], "correctTableAnswers": {"r1": "c_true", "r2": "c_false", "r3": "c_unknown", "r4": "c_unknown", "r5": "c_false", "r6": "c_false"}}, {"id": "g24-6", "type": "text-area", "number": 6, "prompt": "Im Text verspürt Jan Angst.", "subTasks": [{"id": "g24-6a", "label": "a)", "prompt": "Formuliere in eigenen Worten, um welche Angst es sich handelt.", "modelAnswer": "Es ist die Angst, den Vater zu verlieren / dass der Vater stirbt."}, {"id": "g24-6b", "label": "b)", "prompt": "Gib die Zeile an, in welcher Jan diese Angst ausspricht. Zeile:", "modelAnswer": "38", "correctAnswer": "38"}]}, {"id": "g24-7", "type": "text-area", "number": 7, "prompt": "Lies die Zeilen 28 bis 41 nochmals durch. Jan wirkt hier eher wie ein Erwachsener. Nenne drei Punkte, die dies zeigen.", "subTasks": [{"id": "g24-7a", "label": "1.", "prompt": "Was Jan tut:", "modelAnswer": "Jan hält den Vater zurück / beschützt ihn / sichert ihn."}, {"id": "g24-7b", "label": "2.", "prompt": "Wie Jan aussieht:", "modelAnswer": "Jan ist grösser / stärker als sein Vater."}, {"id": "g24-7c", "label": "3.", "prompt": "Worüber Jan nachdenkt:", "modelAnswer": "Er denkt darüber nach, ob das, was er sagt, lächerlich wirkt / über seine Gefühle zum Vater."}]}, {"id": "g24-8", "type": "text-area", "number": 8, "prompt": "Jan und sein Vater erleben auf der Brücke einen «endlosen Augenblick unerwarteten Glücks». Erkläre in einem vollständigen Satz, was sie so glücklich macht.", "subTasks": [{"id": "g24-8a", "label": "Antwort:", "prompt": "Erklärung:", "modelAnswer": "Sie merken, dass sie zusammengehören / wie wichtig sie füreinander sind."}]}, {"id": "g24-9", "rows": [{"id": "r1", "text": "...dass Jan sich über das Wiedersehen mit der Mutter freut."}, {"id": "r2", "text": "...dass Jan erleichtert ist, unverletzt wieder zurück zu sein."}, {"id": "r3", "text": "...dass Jan ganz bewusst nicht erzählt, was er mit dem Vater erlebt hat."}, {"id": "r4", "text": "...dass Jan die Antwort des Vaters absichtlich nicht klarer ausformuliert."}, {"id": "r5", "text": "...dass Jan die imposante Brücke gefallen hat."}, {"id": "r6", "text": "...dass Jan der Mutter absichtlich etwas vorenthält."}], "type": "table-select", "number": 9, "prompt": "In der Tabelle unten findest du Erklärungen für Jans verschmitztes Grinsen am Ende. Kreuze an: Welche Erklärungen treffen zu (R), welche nicht (F)?", "columns": [{"id": "c_right", "label": "R"}, {"id": "c_false", "label": "F"}], "subTasks": [{"id": "g24-9-sub", "label": "Tabelle", "prompt": "Kreuze an."}], "correctTableAnswers": {"r1": "c_false", "r2": "c_false", "r3": "c_right", "r4": "c_right", "r5": "c_false", "r6": "c_right"}}, {"id": "g24-10", "type": "multiple-choice", "number": 10, "prompt": "In jedem Satz ist ein Ausdruck fett hervorgehoben. Vier der Auswahlmöglichkeiten sind Synonyme, eine passt nicht. Wähle den **unpassenden** Ausdruck.", "subTasks": [{"id": "g24-10a", "label": "a)", "prompt": "Der Balkon bedeutete für die Mutter mehr **Stress** als Erholung.", "options": ["Zeitdruck", "Belastung", "Anspannung", "Mühsal", "Strapaze"], "correctAnswer": "Zeitdruck"}, {"id": "g24-10b", "label": "b)", "prompt": "Der Ausflug **kam nicht in Frage**.", "options": ["kam nicht in Betracht", "war kein Thema", "war undenkbar", "war fraglich", "war ausgeschlossen"], "correctAnswer": "war fraglich"}, {"id": "g24-10c", "label": "c)", "prompt": "«Ich **bin dabei**!», sagte er.", "options": ["Ich komme mit!", "Ich bin tätig!", "Ich nehme teil!", "Ich ziehe mit!", "Ich bin mit von der Partie!"], "correctAnswer": "Ich bin tätig!"}, {"id": "g24-10d", "label": "d)", "prompt": "Aber Jan hielt ihn **fest** im Klammergriff.", "options": ["sicher", "eisern", "entschlossen", "entschieden", "brutal"], "correctAnswer": "brutal"}, {"id": "g24-10e", "label": "e)", "prompt": "Fragte sie ihren Mann **gereizt**.", "options": ["missgelaunt", "lustlos", "ungehalten", "missmutig", "mürrisch"], "correctAnswer": "lustlos"}]}, {"id": "g24-11", "type": "input", "number": 11, "prompt": "Bilde ausgehend vom Wortstamm der fett gedruckten Wörter ein neues Wort aus derselben Wortfamilie, das in die Lücke passt.", "subTasks": [{"id": "g24-11a", "label": "a)", "prompt": "Er hatte ... **zugestimmt**. -> Für den Urlaub hatte er seine", "suffix": "gegeben.", "correctAnswer": "Zustimmung"}, {"id": "g24-11b", "label": "b)", "prompt": "Jan rief ... **übermütig** zu. -> Mit einem gewissen", "suffix": "rief Jan seinem Vater zu...", "correctAnswer": "Übermut"}, {"id": "g24-11c", "label": "c)", "prompt": "Manchmal will man zu viel **riskieren**. -> Manchmal geht man zu grosse", "suffix": "ein.", "correctAnswer": "Risiken"}, {"id": "g24-11d", "label": "d)", "prompt": "Vater gab ... **Widerstand** auf. -> Vater tat nicht mehr so, als ob er", "suffix": "würde.", "correctAnswer": "widerstehen"}, {"id": "g24-11e", "label": "e)", "prompt": "Es ergriff ihn ein **berauschendes** Gefühl. -> Er spürte die Weite ... wie in einem", "correctAnswer": "Rausch"}]}, {"id": "g24-12", "type": "input", "number": 12, "prompt": "Erkläre, was sich inhaltlich verändert, wenn du «der» auf Zeile 13 durch «er» ersetzt: «Wenn der durch er ersetzt wird, ...»", "subTasks": [{"id": "g24-12a", "label": "Antwort:", "prompt": "Vervollständige den Satz:", "modelAnswer": "ist nicht mehr klar, dass der Vater gemeint ist / könnte Jan gemeint sein."}]}, {"id": "g24-13", "rows": [{"id": "r1", "text": "ALS DIE BEIDEN **ANTROTTETEN**, SPRANG SIE AUF."}, {"id": "r2", "text": "JAN NAHM DAS **BEBEN** DER BRÜCKE WAHR."}, {"id": "r3", "text": "WENN DU MAL NICHT MEHR DA BIST, WIRD EIN LOCH IN **MEINEM** LEBEN SEIN."}, {"id": "r4", "text": "WAS HABT IHR DA OBEN **HEUTE** GEMACHT?"}, {"id": "r5", "text": "DIE PFEILER STACHEN **REGELRECHT** IN DEN HIMMEL."}], "type": "table-select", "number": 13, "prompt": "Kreuze an, ob es sich bei den fett gedruckten Wörtern um Nomen, Verben oder Adjektive handelt. Falls nichts davon zutrifft, kreuze «nichts davon» an.", "columns": [{"id": "c_nomen", "label": "Nomen"}, {"id": "c_verb", "label": "Verb"}, {"id": "c_adj", "label": "Adjektiv"}, {"id": "c_none", "label": "nichts davon"}], "subTasks": [{"id": "g24-13-sub", "label": "Tabelle", "prompt": "Bestimme die Wortart."}], "correctTableAnswers": {"r1": "c_verb", "r2": "c_nomen", "r3": "c_none", "r4": "c_none", "r5": "c_adj"}}, {"id": "g24-14", "type": "input", "number": 14, "prompt": "Jeder der folgenden Sätze weist genau einen Fehler auf. Korrigiere ihn.", "subTasks": [{"id": "g24-14a", "label": "a)", "prompt": "Jan und sein Vater sind zuerst nicht sicher, **dass** die Brücke tatsächlich so hoch ist. ->", "correctAnswer": "ob"}, {"id": "g24-14b", "label": "b)", "prompt": "Jan **erschrak** den Vater, als er ihn plötzlich von hinten packte. ->", "correctAnswer": "erschreckte"}, {"id": "g24-14c", "label": "c)", "prompt": "Die Mutter empfahl: «Ihr nehmt besser einen Rucksack, daran **trägt** ihr nicht so schwer.» ->", "correctAnswer": "tragt"}, {"id": "g24-14d", "label": "d)", "prompt": "«Was hat denn so lange gedauert**[.]**», nörgelte Jans Schwester. ->", "correctAnswer": "?"}, {"id": "g24-14e", "label": "e)", "prompt": "Wenn **einem** technische Grosstaten interessieren, besichtigt man diese stets gerne. ->", "correctAnswer": "einen"}, {"id": "g24-14f", "label": "f)", "prompt": "Der Vater wäre gerne noch **höcher** hinaufgestiegen. ->", "correctAnswer": "höher"}]}, {"id": "g24-15", "type": "input", "number": 15, "prompt": "Schreibe die Sätze in die verlangten Zeitformen um.", "subTasks": [{"id": "g24-15a", "label": "a) Perfekt:", "prompt": "Staunend nahm Jan den Lärm wahr, während die Lastwagen vorbeifuhren.", "modelAnswer": "Staunend hat Jan den Lärm wahrgenommen, während die Lastwagen vorbeigefahren sind."}, {"id": "g24-15b", "label": "b) Präsens:", "prompt": "Jan umgriff seinen Vater.", "modelAnswer": "Jan umgreift seinen Vater."}, {"id": "g24-15c", "label": "c) Perfekt:", "prompt": "Der Vater wand sich aus Jans Armen und drehte sich zu ihm um.", "modelAnswer": "Der Vater hat sich aus Jans Armen gewunden und sich zu ihm umgedreht."}]}]}', '{"Sie hatten nicht erwartet, dass es über eine solch gigantische Brücke auch einen Fussweg geben","könnte. Schon aus mehreren Kilometern Entfernung sah man die Brücke in einem eleganten Bogen","den Fluss überqueren. Die Pfeiler stachen regelrecht in den Himmel.","Doch Jans Mutter hatte solche Höhenangst, dass selbst Kaffeetrinken daheim auf dem Balkon für","sie mehr Stress als Erholung bedeutete. Der Ausflug auf die Brücke kam nicht in Frage für sie.","Susan, Jans Schwester, schmollte seit Paris, wo sie gerne noch ein paar Tage länger geblieben wä-","re, und blieb lieber beleidigt eine Stunde auf dem brütend heissen Parkplatz, statt zum höchsten","Punkt der riesigen Brücke zu wandern.","Jan hatte nichts übrig für solche Kindereien. Mit dem Maturitätszeugnis in der Tasche hatte er dem","gemeinsamen Urlaub mit den Eltern zugestimmt, nun wollte er auch zeigen, dass es ihm ernst war","mit gemeinsam.","«Ich bin dabei!», sagte Jan deswegen, als ihn sein Vater fragte, ob wenigstens er mitkomme, denn","der nutzte jede Gelegenheit, technische Grosstaten im Detail zu besichtigen.","Der Weg neben den Fahrspuren war zu schmal, um nebeneinander gehen zu können. Staunend","nahm Jan das leichte Beben wahr, das jeder Lastwagen verursachte. Er hörte den ohrenbetäuben-","den Lärm der Fahrzeugflut. Dicht folgte er dem Rücken seines Vaters. Dieser drehte sich um, sah","ihn an, lachte. So etwas wie Kleinbubenglück leuchtete für einen Moment in seinen Augen auf.","«Wir sind gleich oben!», schrie der Vater, lief die letzten Meter und stellte sich breitbeinig über die","Fuge, die den Scheitel der Brücke markierte. Er schaute aufs Meer hinaus. Jan stellte sich neben",ihn.,"Jeder Lastwagen brachte die Brücke zum Schwingen. Der Wind blies ihm salzige Luft ins Ge-",sicht.,"Er schaute abwärts, auf die tief unter ihm liegende Wasserfläche, und es ergriff ihn ein be-","rauschendes Gefühl von Weite und Freiheit.","«Jetzt würd'' ich am liebsten runterspringen!», rief Jan übermütig. Er wollte dem Vater Angst ma-","chen, aber der nickte bloss.","«Manchmal will man zu viel riskieren – das kenne ich auch!» Der Vater ging ganz nach vorne ans","Geländer, neigte sich weit darüber und breitete die Arme aus, als wollte er sich in den weiten Luft-","raum zwischen Brücke und Wasser hineingleiten lassen.","«Das wäre doch ''n cooler Abgang! Nicht wahr?», schrie er. Jan hasste es, wenn sein Vater so","sprach wie ein Jugendlicher. Aber diesmal ging er auf das Spiel ein, packte seinen Vater bei der","Jacke, zog ihn mit einem Ruck zurück – vielleicht war es auch wirkliche Angst um ihn –, umgriff","ihn von hinten mit beiden Armen und drückte ihn an sich. Sein Vater war einen Kopf kleiner und","inzwischen bestimmt auch schwächer, sie hatten schon vor Jahren damit aufgehört, im spieleri-","schen Raufen ihre Kraft zu messen.","«Lass mich, lass mich!», schrie der Vater albern und wand sich hin und her. Aber Jan hielt ihn fest","im Klammergriff, bis der Vater seinen gespielten Widerstand aufgab. Für einen endlosen Augen-","blick unerwarteten Glücks standen sie bewegungslos, dann drehte der Vater den Kopf zu ihm um","und strahlte Jan ins Gesicht.","«Wenn du mal nicht mehr da bist, wird ein riesiges, verdammtes Loch in meinem Leben sein!»,","schrie Jan unvermittelt. Er fragte sich, ob es nicht lächerlich war, mit fast neunzehn Jahren so et-","was zu seinem Vater zu sagen. Der Vater wand sich aus Jans Armen und drehte sich zu ihm um.","«Das ist in Ordnung so», sagte er glücklich und nickte dabei, «das muss so sein.»","Noch einen Moment blieben sie ganz vorne an der Brüstung stehen, dann gingen sie denselben","schmalen Fusspfad zurück. Auf dem Parkplatz hatte sich die Mutter mit Susan hinter dem Auto in","den schütteren Schatten eines frischgepflanzten Bäumchens gesetzt. Als die beiden nach einer","Stunde antrotteten, sprang sie auf. «Was habt ihr da oben so lange gemacht?», fragte sie ihren","Mann ein wenig gereizt. «Runtergeguckt», sagte der Vater.","Sie verdrehte die Augen, schüttelte entnervt den Kopf. Dann sah sie Jan fragend an. «Runterge-","guckt!», sagte Jan und grinste verschmitzt."}', '2026-02-22 22:49:47.877309+00', '2026-02-22 22:49:47.877309+00'),
	('german-2024-qwen', 'Deutsch 2024 (Langgymnasium)', 'German', 2024, 'Qwen 3 Max', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch.", "Du darfst wählen, in welcher Reihenfolge du die Aufgaben löst.", "In den Aufgaben 4, 7, 8, 11, 14 und 15 führen Rechtschreib- und Grammatikfehler zu einem Punkteabzug."], "maxPoints": 46}, "questions": [{"id": "german24-1", "type": "input", "number": 1, "prompt": "Die Brücke wird am Anfang (Zeilen 1–8) mit zwei Adjektiven beschrieben, die beide „sehr gross“ bedeuten. Notiere die zwei Adjektive.", "context": "", "subTasks": [{"id": "1a", "label": "-", "prompt": "", "correctAnswer": "gigantisch"}, {"id": "1b", "label": "-", "prompt": "", "correctAnswer": "riesig"}]}, {"id": "german24-2", "type": "input", "number": 2, "prompt": "Begründe, warum Jans Mutter gemäss dem Text nicht auf die Brücke mitkommt. Vervollständige dazu den Satz grammatikalisch korrekt mit zwei Wörtern. Verändere die vorgegebenen Bestandteile des Satzes nicht.", "context": "Jans Mutter bleibt auf dem Parkplatz, denn sie leidet", "subTasks": [{"id": "2a", "label": "", "prompt": "", "correctAnswer": "unter Höhenangst"}]}, {"id": "german24-3", "type": "text-area", "number": 3, "prompt": "Jan und sein Vater haben unterschiedliche Gründe für die Wanderung.\n\na. In den Zeilen 9–11 wird Jans Grund angegeben, die Wanderung zu unternehmen. Formuliere seinen Grund. Die Wörter „ernst“ und „gemeinsam“ darfst du nicht verwenden.\n\nb. In den Zeilen 12 und 13 wird der Grund von Jans Vater angegeben, die Wanderung auf die Brücke zu unternehmen. Formuliere seinen Grund. In deiner Antwort müssen die Wörter „auslassen“ und „Meisterleistung“ vorkommen.", "context": "", "subTasks": [{"id": "3a", "label": "a.", "prompt": "", "modelAnswer": "Jan möchte etwas mit seinem Vater unternehmen und nicht kindisch wirken."}, {"id": "3b", "label": "b.", "prompt": "", "modelAnswer": "Der Vater lässt keine Gelegenheit aus, technische Meisterleistungen zu besichtigen."}]}, {"id": "german24-4", "type": "text-area", "number": 4, "prompt": "Auf der Brücke angekommen sieht Jan die tief unter ihm liegende Wasseroberfläche (Sehsinn). Zusätzlich nimmt er die Situation auf Zeilen 14–22 auch mit anderen Sinnen wahr. Formuliere in drei vollständigen Sätzen, was genau Jan mit weiteren Sinnen wahrnimmt. Jeder Sinn und jedes Beispiel dürfen nur einmal vorkommen.", "context": "", "subTasks": [{"id": "4a", "label": "1.", "prompt": "", "modelAnswer": "Er spürt den Wind, der ihm salzige Luft ins Gesicht bläst."}, {"id": "4b", "label": "2.", "prompt": "", "modelAnswer": "Er hört den ohrenbetäubenden Lärm der Lastwagen."}, {"id": "4c", "label": "3.", "prompt": "", "modelAnswer": "Er nimmt das leichte Beben der Brücke wahr."}]}, {"id": "german24-5", "rows": [{"id": "5a", "text": "Susan und die Mutter suchen sich auf dem Parkplatz ein schattiges Plätzchen."}, {"id": "5b", "text": "Jan und sein Vater brauchen eine Stunde für den Weg vom Parkplatz bis zum Scheitel der Brücke."}, {"id": "5c", "text": "Jans Vater ist Ingenieur von Beruf."}, {"id": "5d", "text": "Jan mag seine Schwester nicht."}, {"id": "5e", "text": "Die Brücke führt über eine Meerenge."}, {"id": "5f", "text": "Jan und sein Vater überqueren die Brücke ganz."}], "type": "table-select", "number": 5, "prompt": "Kreuze bei den folgenden Aussagen an, ob sie mit dem Inhalt der Geschichte übereinstimmen (!) oder nicht (–). Setze das Kreuz beim Fragezeichen (?), wenn das nicht entschieden werden kann. Es darf nur ein Kreuz pro Zeile gesetzt werden.", "columns": [{"id": "correct", "label": "!"}, {"id": "incorrect", "label": "–"}, {"id": "unknown", "label": "?"}], "context": "", "subTasks": [], "correctTableAnswers": {"5a": "correct", "5b": "incorrect", "5c": "unknown", "5d": "unknown", "5e": "incorrect", "5f": "incorrect"}}, {"id": "german24-6", "type": "text-area", "number": 6, "prompt": "Im Text verspürt Jan Angst.\n\na. Formuliere in eigenen Worten, um welche Angst es sich handelt.\n\nb. Gib die Zeile an, in welcher Jan diese Angst ausspricht.", "context": "", "subTasks": [{"id": "6a", "label": "a.", "prompt": "", "modelAnswer": "Jan fürchtet den Verlust seines Vaters."}, {"id": "6b", "label": "b. Zeile", "prompt": "", "correctAnswer": "38"}]}, {"id": "german24-7", "type": "text-area", "number": 7, "prompt": "Lies die Zeilen 28 bis 41 nochmals durch. Jan wirkt hier eher wie ein Erwachsener und Jans Vater eher wie ein Kind. Nenne drei Punkte, die zeigen, dass Jan eher die Rolle eines Erwachsenen einnimmt. Formuliere jeweils einen vollständigen Satz.", "context": "", "subTasks": [{"id": "7a", "label": "1. Was Jan tut:", "prompt": "", "modelAnswer": "Jan hält seinen Vater fest und beschützt ihn."}, {"id": "7b", "label": "2. Wie Jan aussieht:", "prompt": "", "modelAnswer": "Jan ist grösser und stärker als sein Vater."}, {"id": "7c", "label": "3. Worüber Jan nachdenkt:", "prompt": "", "modelAnswer": "Jan denkt darüber nach, wie wichtig ihm sein Vater ist."}]}, {"id": "german24-8", "type": "text-area", "number": 8, "prompt": "Jan und sein Vater erleben auf der Brücke einen «endlosen Augenblick unerwarteten Glücks» (Z. 35–36). Erkläre in einem vollständigen Satz, was sie so glücklich macht.", "context": "", "subTasks": [{"id": "8a", "label": "", "prompt": "", "modelAnswer": "Sie erkennen, wie sehr sie einander lieben und wie wichtig sie füreinander sind."}]}, {"id": "german24-9", "rows": [{"id": "9a", "text": "... dass Jan sich über das Wiedersehen mit der Mutter freut."}, {"id": "9b", "text": "... dass Jan erleichtert ist, unverletzt wieder zurück zu sein."}, {"id": "9c", "text": "... dass Jan ganz bewusst nicht erzählt, was er mit dem Vater erlebt hat."}, {"id": "9d", "text": "... dass Jan die Antwort des Vaters absichtlich nicht klarer ausformuliert."}, {"id": "9e", "text": "... dass Jan die imposante Brücke gefallen hat."}, {"id": "9f", "text": "... dass Jan der Mutter absichtlich etwas vorenthält."}], "type": "table-select", "number": 9, "prompt": "Als Jan und der Vater wieder zurück auf dem Parkplatz sind, antwortet Jan auf die Frage der Mutter, was sie auf der Brücke so lange getan hätten, mit einem verschmitzten Grinsen. In der Tabelle unten findest du Erklärungen für dieses verschmitzte Grinsen. Kreuze an: Welche Erklärungen treffen zu (R für richtig), welche nicht (F für falsch)? Falsch gesetzte Kreuze geben Abzug. Das Auslassen einer Antwort führt zu keinem Abzug. Setze nur ein Kreuz pro Zeile.", "columns": [{"id": "correct", "label": "R"}, {"id": "incorrect", "label": "F"}], "context": "", "subTasks": [], "correctTableAnswers": {"9a": "incorrect", "9b": "incorrect", "9c": "correct", "9d": "correct", "9e": "incorrect", "9f": "correct"}}, {"id": "german24-10", "rows": [{"id": "10a", "text": "Zeitdruck, Belastung, Anspannung, Mühsal, Strapaze"}, {"id": "10b", "text": "kam nicht in Betracht, war kein Thema, war undenkbar, war fraglich, war ausgeschlossen"}, {"id": "10c", "text": "Ich komme mit!, Ich bin tätig!, Ich nehme teil!, Ich ziehe mit!, Ich bin mit von der Partie!"}, {"id": "10d", "text": "sicher, eisern, entschlossen, entschieden, brutal"}, {"id": "10e", "text": "missgelaunt, lustlos, ungehalten, missmutig, mürrisch"}], "type": "table-select", "number": 10, "prompt": "In jedem Satz ist ein Ausdruck fett hervorgehoben. Unter dem Satz finden sich fünf Ausdrücke. Vier davon sind Synonyme des fett gedruckten Ausdrucks. Ein Ausdruck passt nicht. Streiche nur diesen einen unpassenden Ausdruck durch. Deine Lösungen müssen inhaltlich zum Text passen.", "columns": [{"id": "wrong", "label": "✖"}], "context": "", "subTasks": [], "correctTableAnswers": {"10a": "wrong", "10b": "wrong", "10c": "wrong", "10d": "wrong", "10e": "wrong"}}, {"id": "german24-11", "type": "input", "number": 11, "prompt": "Bilde ausgehend vom Wortstamm (Stamm-Morphem) der fett gedruckten Wörter ein neues Wort aus derselben Wortfamilie, das in die Lücke passt. Es darf nur ein einziges Wort pro Lücke eingesetzt werden. Die Bedeutung des rechten Satzes muss mit der des linken Satzes übereinstimmen. Der Lückentext darf nicht verändert werden.", "context": "", "subTasks": [{"id": "11a", "label": "a.", "prompt": "Für den Urlaub mit den Eltern hatte er seine", "correctAnswer": "Zustimmung"}, {"id": "11b", "label": "b.", "prompt": "Mit einem gewissen", "correctAnswer": "Übermut"}, {"id": "11c", "label": "c.", "prompt": "Manchmal geht man zu grosse", "correctAnswer": "Risiken"}, {"id": "11d", "label": "d.", "prompt": "Der Vater tat nicht mehr so, als ob er", "correctAnswer": "widerstehen"}, {"id": "11e", "label": "e.", "prompt": "Er spürte die Weite und die Freiheit wie in einem", "correctAnswer": "Rausch"}]}, {"id": "german24-12", "type": "text-area", "number": 12, "prompt": "Lies die Zeilen 12 und 13 noch einmal. Erkläre, was sich inhaltlich verändert, wenn du „der“ auf Zeile 13 durch „er“ ersetzt. Ergänze dazu den Satzanfang.", "context": "Wenn „der“ durch „er“ ersetzt wird,", "subTasks": [{"id": "12a", "label": "", "prompt": "", "modelAnswer": "ist nicht mehr klar, dass der Vater gemeint ist, sondern Jan."}]}, {"id": "german24-13", "rows": [{"id": "13a", "text": "ALS DIE BEIDEN **ANTROTTETEN**, SPRANG SIE AUF."}, {"id": "13b", "text": "JAN NAHM DAS **BEBEN** DER BRÜCKE WAHR."}, {"id": "13c", "text": "WENN DU MAL NICHT MEHR DA BIST, WIRD EIN **LOCH** IN MEINEM LEBEN SEIN."}, {"id": "13d", "text": "WAS HABT IHR DA OBEN HEUTE **GEMACHT**?"}, {"id": "13e", "text": "DIE **PFEILER** STACHEN REGELRECHT IN DEN HIMMEL."}], "type": "table-select", "number": 13, "prompt": "Kreuze an, ob es sich bei den fett gedruckten Wörtern um Nomen, Verben oder Adjektive handelt. Falls sie zu keiner dieser Wortarten gehören, setzt du das Kreuz bei «nichts davon». Es darf nur ein Kreuz pro Zeile gesetzt werden.", "columns": [{"id": "noun", "label": "Nomen"}, {"id": "verb", "label": "Verb"}, {"id": "adj", "label": "Adjektiv"}, {"id": "none", "label": "nichts davon"}], "context": "", "subTasks": [], "correctTableAnswers": {"13a": "verb", "13b": "noun", "13c": "noun", "13d": "verb", "13e": "noun"}}, {"id": "german24-14", "type": "input", "number": 14, "prompt": "Jeder der folgenden Sätze weist genau einen Fehler auf. Korrigiere diesen Fehler jeweils, indem du ihn durchstreichst und die richtige Lösung über den Fehler schreibst. Korrigiere pro Satz nur einen Fehler.", "context": "", "subTasks": [{"id": "14a", "label": "a.", "prompt": "Jan und sein Vater sind zuerst nicht sicher, dass die Brücke tatsächlich so hoch ist.", "correctAnswer": "ob"}, {"id": "14b", "label": "b.", "prompt": "Jan erschrak den Vater, als er ihn plötzlich von hinten packte.", "correctAnswer": "erschreckte"}, {"id": "14c", "label": "c.", "prompt": "Die Mutter empfahl: «Ihr nehmt besser einen Rucksack, daran trägt ihr nicht so schwer.»", "correctAnswer": "tragt"}, {"id": "14d", "label": "d.", "prompt": "«Was hat denn so lange gedauert.», nörgelte Jans Schwester.", "correctAnswer": "?"}, {"id": "14e", "label": "e.", "prompt": "Wenn einem technische Grosstaten interessieren, besichtigt man diese stets gerne.", "correctAnswer": "einen"}, {"id": "14f", "label": "f.", "prompt": "Der Vater wäre gerne noch höcher hinaufgestiegen, um die Aussicht zu bewundern.", "correctAnswer": "höher"}]}, {"id": "german24-15", "type": "input", "number": 15, "prompt": "Schreibe die folgenden Sätze in die verlangten Zeitformen um. Du musst die Sätze jeweils vollständig abschreiben.", "context": "", "subTasks": [{"id": "15a", "label": "a. Perfekt:", "prompt": "Staunend nahm Jan den Lärm wahr, während die Lastwagen vorbeifuhren.", "modelAnswer": "Staunend hat Jan den Lärm wahrgenommen, während die Lastwagen vorbeigefahren sind."}, {"id": "15b", "label": "b. Präsens:", "prompt": "Jan umgriff seinen Vater.", "modelAnswer": "Jan umgreift seinen Vater."}, {"id": "15c", "label": "c. Perfekt:", "prompt": "Der Vater wand sich aus Jans Armen und drehte sich zu ihm um.", "modelAnswer": "Der Vater hat sich aus Jans Armen gewunden und hat sich zu ihm umgedreht."}]}]}', '{"Sie hatten nicht erwartet, dass es über eine solch gigantische Brücke auch einen Fussweg","geben könnte. Schon aus mehreren Kilometern Entfernung sah man die Brücke in einem","eleganten Bogen den Fluss überqueren. Die Pfeiler stachen regelrecht in den Himmel.","Doch Jans Mutter hatte solche Höhenangst, dass selbst Kaffeetrinken daheim auf dem Balkon","für sie mehr Stress als Erholung bedeutete. Der Ausflug auf die Brücke kam nicht in Frage für",sie.,"Susan, Jans Schwester, schmollte seit Paris, wo sie gerne noch ein paar Tage länger geblieben","wäre, und blieb lieber beleidigt eine Stunde auf dem brütend heissen Parkplatz, statt zum","höchsten Punkt der riesigen Brücke zu wandern.","Jan hatte nichts übrig für solche Kindereien. Mit dem Maturitätszeugnis in der Tasche hatte er","dem gemeinsamen Urlaub mit den Eltern zugestimmt, nun wollte er auch zeigen, dass es ihm","ernst war mit ›gemeinsam‹.","«Ich bin dabei!», sagte Jan deswegen, als ihn sein Vater fragte, ob wenigstens er mitkomme,","denn der nutzte jede Gelegenheit, technische Grosstaten im Detail zu besichtigen.","Der Weg neben den Fahrspuren war zu schmal, um nebeneinander gehen zu können. Staunend","nahm Jan das leichte Beben wahr, das jeder Lastwagen verursachte. Er hörte den ohrenbetäu-","benden Lärm der Fahrzeugflut. Dicht folgte er dem Rücken seines Vaters. Dieser drehte sich um,","sah ihn an, lachte. So etwas wie Kleinbubenglück leuchtete für einen Moment in seinen Augen",auf.,"«Wir sind gleich oben!», schrie der Vater, lief die letzten Meter und stellte sich breitbeinig über","die Fuge, die den Scheitel der Brücke markierte. Er schaute aufs Meer hinaus. Jan stellte sich","neben ihn. Jeder Lastwagen brachte die Brücke zum Schwingen. Der Wind blies ihm salzige Luft","ins Gesicht. Er schaute abwärts, auf die tief unter ihm liegende Wasserfläche, und es ergriff ihn","ein berauschendes Gefühl von Weite und Freiheit.","«Jetzt würd’ ich am liebsten runterspringen!», rief Jan übermütig. Er wollte dem Vater Angst","machen, aber der nickte bloss.","«Manchmal will man zu viel riskieren – das kenne ich auch!» Der Vater ging ganz nach vorne","ans Geländer, neigte sich weit darüber und breitete die Arme aus, als wollte er sich in den","weiten Luftraum zwischen Brücke und Wasser hineingleiten lassen.","«Das wäre doch ’n cooler Abgang! Nicht wahr?», schrie er. Jan hasste es, wenn sein Vater so","sprach wie ein Jugendlicher. Aber diesmal ging er auf das Spiel ein, packte seinen Vater bei der","Jacke, zog ihn mit einem Ruck zurück – vielleicht war es auch wirkliche Angst um ihn –, umgriff","ihn von hinten mit beiden Armen und drückte ihn an sich. Sein Vater war einen Kopf kleiner und","inzwischen bestimmt auch schwächer, sie hatten schon vor Jahren damit aufgehört, im","spielerischen Raufen ihre Kraft zu messen.","«Lass mich, lass mich!», schrie der Vater albern und wand sich hin und her. Aber Jan hielt ihn","fest im Klammergriff, bis der Vater seinen gespielten Widerstand aufgab. Für einen endlosen","Augenblick unerwarteten Glücks standen sie bewegungslos, dann drehte der Vater den Kopf zu","ihm um und strahlte Jan ins Gesicht.","«Wenn du mal nicht mehr da bist, wird ein riesiges, verdammtes Loch in meinem Leben sein!»,","schrie Jan unvermittelt. Er fragte sich, ob es nicht lächerlich war, mit fast neunzehn Jahren so","etwas zu seinem Vater zu sagen. Der Vater wand sich aus Jans Armen und drehte sich zu ihm um.","«Das ist in Ordnung so», sagte er glücklich und nickte dabei, «das muss so sein.» Noch einen","Moment blieben sie ganz vorne an der Brüstung stehen, dann gingen sie denselben schmalen","Fusspfad zurück. Auf dem Parkplatz hatte sich die Mutter mit Susan hinter dem Auto in den","schütteren Schatten eines frischgepflanzten Bäumchens gesetzt. Als die beiden nach einer","Stunde antrotteten, sprang sie auf. «Was habt ihr da oben so lange gemacht?», fragte sie ihren","Mann ein wenig gereizt. «Runtergeguckt», sagte der Vater.","Sie verdrehte die Augen, schüttelte entnervt den Kopf. Dann sah sie Jan fragend an. «Runterge-","guckt!», sagte Jan und grinste verschmitzt."}', '2026-02-22 22:49:47.935578+00', '2026-02-22 22:49:47.935578+00'),
	('german-2025-claude', 'Sprachprüfung Deutsch 2025 (Langgymnasium)', 'German', 2025, 'Claude Opus 4.5', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch. Du brauchst ihn zur Lösung der folgenden Aufgaben.", "Du darfst wählen, in welcher Reihenfolge du die Aufgaben löst.", "In den Aufgaben 3, 6, 8, 11 und 13 führen Rechtschreibe- und Grammatikfehler zu einem Punkteabzug.", "Du hast 45 Minuten Zeit."], "maxPoints": 48}, "questions": [{"id": "g25-1", "type": "input", "number": 1, "prompt": "Zu welcher Rasse gehört Lorenz'' Hund?", "subTasks": [{"id": "g25-1a", "label": "Rasse:", "correctAnswer": "Labrador"}]}, {"id": "g25-2", "type": "text-area", "number": 2, "prompt": "Lies die Zeilen 1 bis 8 noch einmal: Was überrascht Lorenz daran, wie Cougar auf Jennifer reagiert?", "context": "Ihn überrascht, dass ___", "subTasks": [{"id": "g25-2a", "label": "Ergänzung:", "modelAnswer": "...sein sonst misstrauischer Hund sich streicheln lässt. / Cougar sich streicheln/umarmen lässt. / Cougar nicht misstrauisch/zutraulich/nett ist."}]}, {"id": "g25-3", "type": "text-area", "number": 3, "prompt": "Lies die Zeilen 22-26 noch einmal.", "subTasks": [{"id": "g25-3a", "label": "a)", "prompt": "Der Text gibt uns hier einen Hinweis, der erklären kann, warum Lorenz seinen Hund Cougar genannt hat. Um welchen Hinweis handelt es sich?", "modelAnswer": "Die (Fell-)Farbe / Die Fellfarbe der Tiere ist sehr ähnlich."}, {"id": "g25-3b", "label": "b) Erster Grund:", "prompt": "Jennifer findet den Namen Cougar witzig, weil er aus ihrer Sicht nicht passt. Erkläre genau, warum sie den Namen unpassend findet, indem du zwei unterschiedliche Gründe nennst. Der Name ist aus ihrer Sicht unpassend, denn...", "modelAnswer": "...der Name eines Pumas/einer Raubkatze passt nicht zu einem Hund/einem Haustier. / Pumas sind (Raub-)Katzen. / Cougar ist ein Hund."}, {"id": "g25-3c", "label": "b) Zweiter Grund:", "prompt": "Der Name ist aus ihrer Sicht unpassend, denn...", "modelAnswer": "...Pumas sind Wildtiere/gefährlich. / Cougar ist ein Haustier/zahm. / Pumas sind stärker/grösser/schwerer/schneller (als Hunde)."}]}, {"id": "g25-4", "type": "input", "number": 4, "prompt": "Gib Zeilennummern an.", "subTasks": [{"id": "g25-4a", "label": "a)", "prompt": "Auf den ersten Blick scheint Cougar für Lorenz nicht so wichtig zu sein. Gib die Zeilennummer des Satzes an, in dem diese Information zu finden ist. Führe beide Zeilen an, wenn der Satz über zwei Zeilen geht.", "modelAnswer": "Zeile(n) Nr. 17-18 (toleriert: 2-3 / 20)", "correctAnswer": "17-18"}, {"id": "g25-4b", "label": "b) Erster Satz:", "prompt": "Diese oberflächliche Betrachtung ist jedoch falsch: Cougar bedeutet viel für Lorenz. Gib drei unterschiedliche Sätze zwischen Zeile 27 und Zeile 48 an, die das zeigen.", "modelAnswer": "Zeile Nr. 27"}, {"id": "g25-4c", "label": "b) Zweiter Satz:", "modelAnswer": "Zeilen Nr. 33-34"}, {"id": "g25-4d", "label": "b) Dritter Satz:", "modelAnswer": "Zeilen Nr. 36-37"}]}, {"id": "g25-5", "rows": [{"id": "r1", "text": "Lorenz ist vom Dorf in die Stadt gezogen."}, {"id": "r2", "text": "Die Geschichte spielt im Herbst."}, {"id": "r3", "text": "Lorenz reagiert im Gespräch mit Jennifer immer selbstbewusst."}, {"id": "r4", "text": "Es scheint, als ob Cougar bei Jennifer bleiben möchte."}, {"id": "r5", "text": "Dass Cougar drei Mal bellt, ist der eindeutige Beweis dafür, dass er viel lieber bei Jennifer als bei Lorenz wäre."}, {"id": "r6", "text": "Lorenz verlangt von Jennifer mehr Geld für den Hund."}, {"id": "r7", "text": "Lorenz fühlt sich von Cougar verraten."}], "type": "table-select", "number": 5, "prompt": "Kreuze bei den folgenden Aussagen an, ob sie mit dem Inhalt der Geschichte übereinstimmen (✓) oder nicht (–). Setze das Kreuz beim Fragezeichen (?), wenn das nicht entschieden werden kann. Es darf nur ein Kreuz pro Zeile gesetzt werden.", "columns": [{"id": "yes", "label": "✓"}, {"id": "no", "label": "–"}, {"id": "unknown", "label": "?"}], "subTasks": [{"id": "g25-5a", "label": "Tabelle"}], "correctTableAnswers": {"r1": "unknown", "r2": "unknown", "r3": "no", "r4": "yes", "r5": "no", "r6": "no", "r7": "yes"}}, {"id": "g25-6", "type": "text-area", "number": 6, "prompt": "Fragen zu den Liedern am Anfang und Ende des Textes.", "subTasks": [{"id": "g25-6a", "label": "a)", "prompt": "Warum ist es für das Textverständnis wichtig zu wissen, dass Lorenz am Anfang (Z. 1) und am Ende (Z. 47-48) zwei unterschiedliche Lieder wählt? Antworte, indem du den Satz mit einem passenden Nomen ergänzt: Die beiden Lieder widerspiegeln die jeweilige ___ von Lorenz.", "modelAnswer": "Stimmung / Gefühlslage / Laune", "correctAnswer": "Stimmung"}, {"id": "g25-6b", "label": "b)", "prompt": "Die Lieder zeigen ausserdem, dass mit Lorenz im Laufe der Ereignisse etwas geschehen ist. Erkläre in einem Satz, was sich bei ihm verändert hat.", "modelAnswer": "Lorenz'' Stimmung/Gefühlslage hat sich verbessert/vom Negativen ins Positive gewandelt. / Zuerst hat Lorenz Heimweh, dann ist er fröhlich. / Lorenz hat nun eine Freundin. / Lorenz ist nicht mehr einsam. / Lorenz kann Cougar behalten."}]}, {"id": "g25-7", "type": "input", "number": 7, "prompt": "Lorenz durchlebt ein Wechselbad von Gefühlen. Ergänze die Lücken mit je einem passenden Nomen aus der Box. Du darfst jedes Nomen höchstens einmal verwenden. Es muss stets dem Text «Cougar» entsprechen.", "context": "**Nomen zur Auswahl:** Betroffenheit, Ekel, Elend, Enttäuschung, Erleichterung, Hilflosigkeit, Liebeskummer, Neugier, Sehnsucht, Verunsicherung, Wut\n\n**Beispiele:** Am Anfang des Textes hört Lorenz ein Lied, das **Sehnsucht** ausdrückt. Dann begegnet Lorenz Jennifer, die Cougar einfach so umarmt und auch einen solchen Hund haben möchte. Ihre bettelnden Augen führen bei Lorenz zu **Verunsicherung**.", "subTasks": [{"id": "g25-7a", "label": "a)", "prompt": "Nun will Jennifer Cougar kaufen und dessen Blick scheint Lorenz zum Verkauf zu ermuntern. Darüber verspürt Lorenz ___. (Z. 17)", "correctAnswer": "Enttäuschung"}, {"id": "g25-7b", "label": "b)", "prompt": "Jennifer reicht Lorenz drei Münzen. Danach schauen die beiden ihn mit flehenden Augen an. Lorenz spürt in diesem Moment ___. (Z. 27)", "correctAnswer": "Betroffenheit"}, {"id": "g25-7c", "label": "c)", "prompt": "Nun greift Jennifers Mutter ins Geschehen ein. Sie erkennt nämlich Lorenz'' zunehmende ___. (Z. 34)", "correctAnswer": "Hilflosigkeit"}, {"id": "g25-7d", "label": "d)", "prompt": "Als Jennifer behauptet, Cougar habe sie lieber als Lorenz, bellt der Hund scheinbar bestätigend. Jetzt erfasst Lorenz ___. (Z. 36)", "correctAnswer": "Elend"}, {"id": "g25-7e", "label": "e)", "prompt": "Die Mutter weist Jennifer darauf hin, dass Lorenz bestimmt nach Hause gehen müsse. Sie bietet Lorenz so einen Ausweg an. Diesen erfasst ___. (Z. 41)", "correctAnswer": "Erleichterung"}]}, {"id": "g25-8", "rows": [{"id": "r1", "text": "Der Satz zeigt eindeutig, dass alle Hunde die Menschensprache verstehen."}, {"id": "r2", "text": "Der Satz zeigt, dass Cougar Jennifer mag."}, {"id": "r3", "text": "Der Satz zeigt den Hund, als wäre er ein Mensch, weil er scheinbar versteht, was die Menschen sprechen."}], "type": "table-select", "number": 8, "prompt": "Welche Wirkung hat der Satz auf Zeile 36: «Cougar bellte drei Mal laut, als wollte er unbedingt zustimmen»?", "columns": [{"id": "yes", "label": "✓"}, {"id": "no", "label": "–"}, {"id": "unknown", "label": "?"}], "context": "Kreuze an, ob die Antworten richtig (✓) oder falsch (–) sind. Setze ein Kreuz bei (?), wenn das aufgrund des Textes nicht entschieden werden kann. Es darf nur ein Kreuz pro Zeile gesetzt werden.", "subTasks": [{"id": "g25-8a", "label": "a) Tabelle"}, {"id": "g25-8b", "label": "b)", "prompt": "Vergleiche die zwei folgenden Sätze:\nSatz A: «Als Zustimmung bellte Cougar drei Mal laut.»\nSatz B: «Cougar bellte drei Mal laut, als wollte er unbedingt zustimmen.»\nSatz A unterscheidet sich inhaltlich von Satz B. Erkläre den Unterschied in eigenen Worten.", "modelAnswer": "In Satz A stimmt der Hund wirklich zu / ist die Aussage eine Tatsache. In Satz B hingegen ist es unsicher/nur eine Möglichkeit, ob das Bellen als Zustimmung zu verstehen ist / ist die Aussage eine Vermutung/Möglichkeit/Behauptung."}], "correctTableAnswers": {"r1": "no", "r2": "unknown", "r3": "yes"}}, {"id": "g25-9", "type": "multiple-choice", "number": 9, "prompt": "Kreuze jeweils nur die Lösung an, die der Bedeutung der fett gedruckten Wörter und Ausdrücke am besten entspricht. Deine Lösung muss inhaltlich zum Text passen.", "subTasks": [{"id": "g25-9a", "label": "a)", "prompt": "«‹Das ist ja ein lieber Hund›, **schwärmte** das Kind» (Z. 6)", "options": ["sagte … leise", "sagte … laut", "sagte … begeistert", "sagte … übermütig", "sagte … weinerlich"], "correctAnswer": "sagte … begeistert"}, {"id": "g25-9b", "label": "b)", "prompt": "«Das Kind […] umarmte das **verdutzte** Tier.» (Z. 6)", "options": ["verängstigte", "misstrauische", "zutrauliche", "erstaunte", "arglose"], "correctAnswer": "erstaunte"}, {"id": "g25-9c", "label": "c)", "prompt": "«[…] dass er sich nun mit dem erstbesten Mädchen gegen ihn **verschwor**?» (Z. 18/19)", "options": ["zusammentat", "einschwor", "vertat", "bewarb", "aufmachte"], "correctAnswer": "zusammentat"}, {"id": "g25-9d", "label": "d)", "prompt": "«Lorenz fuhr Cougar **behutsam** durch das Fell» (Z. 19)", "options": ["ruhig", "gelassen", "vorsichtig", "nachdenklich", "behütet"], "correctAnswer": "vorsichtig"}]}, {"id": "g25-10", "type": "table-select", "number": 10, "prompt": "In der linken Spalte wird ein Wortfeld genannt. Kreuze in der rechten Spalte jene **zwei** Verben an, die am wenigsten in das angegebene Wortfeld passen.", "subTasks": [{"id": "g25-10a", "label": "a) jemanden verärgern", "options": ["enttäuschen", "frustrieren", "verdriessen", "verdonnern", "bedrohen"], "modelAnswer": "verdonnern, bedrohen"}, {"id": "g25-10b", "label": "b) sehen", "options": ["schauen", "blinzeln", "gaffen", "versehen", "beobachten"], "modelAnswer": "blinzeln, versehen"}, {"id": "g25-10c", "label": "c) flehen", "options": ["mahnen", "beschwören", "anbeten", "bitten", "beknien"], "modelAnswer": "mahnen, anbeten"}, {"id": "g25-10d", "label": "d) gehen", "options": ["unterlaufen", "schreiten", "sich begeben", "vergehen", "aufsuchen"], "modelAnswer": "unterlaufen, vergehen"}]}, {"id": "g25-11", "type": "input", "number": 11, "prompt": "Bilde ausgehend vom Wortstamm (Stamm-Morphem) der fett gedruckten Wörter ein neues Wort aus derselben Wortfamilie. Es muss in die Lücke passen. Es darf nur ein einziges Wort pro Lücke eingesetzt werden. Die Bedeutung des rechten Satzes muss mit der des linken Satzes übereinstimmen. Der Lückentext darf nicht verändert werden.", "subTasks": [{"id": "g25-11a", "label": "a)", "prompt": "Lorenz schaute ziemlich **fasziniert** zu. → Lorenz schaute mit einer gewissen ___ zu.", "correctAnswer": "Faszination"}, {"id": "g25-11b", "label": "b)", "prompt": "Sie **seufzte**: «Ich möchte so gerne auch einen Hund haben.» → ___ meinte sie: «Ich möchte so gerne auch einen Hund haben.»", "correctAnswer": "Seufzend"}, {"id": "g25-11c", "label": "c)", "prompt": "Lorenz'' **Musterung** seines Hundes zeugte von seiner Überraschung. → Lorenz ___ seinen Hund überrascht.", "correctAnswer": "musterte"}, {"id": "g25-11d", "label": "d)", "prompt": "Beinahe **flehentlich** schaute sie ihn an. → Sie schaute ihn beinahe ___ an.", "modelAnswer": "flehend (toleriert: anflehend)", "correctAnswer": "flehend"}, {"id": "g25-11e", "label": "e)", "prompt": "Jenny **klammerte** sich verliebt an Cougar. → Jennys ___ von Cougar verdeutlichte ihre Verliebtheit.", "modelAnswer": "Umklammerung / Umklammern", "correctAnswer": "Umklammerung"}, {"id": "g25-11f", "label": "f)", "prompt": "Cougar bellte drei Mal, als wolle er **unbedingt** zustimmen. → Cougar bellte drei Mal, als wolle er ___ zustimmen.", "correctAnswer": "bedingungslos"}]}, {"id": "g25-12", "type": "input", "number": 12, "prompt": "Setze jeweils ein passendes Wort in die Lücke, sodass stets ein inhaltlich und grammatikalisch korrekter Satz entsteht. Der Sinn des Lösungssatzes muss zur Geschichte «Cougar» passen.", "subTasks": [{"id": "g25-12a", "label": "a)", "prompt": "Cougar starrt Lorenz in einer solchen Art und Weise an, ___ es ganz so scheint, als wolle er ebenso zustimmen.", "modelAnswer": "dass / sodass / womit / wodurch (toleriert: worauf)", "correctAnswer": "dass"}, {"id": "g25-12b", "label": "b)", "prompt": "Ist das ein Grund, ___ sich mit dem erstbesten Mädchen gegen ihn ___ verschwören?", "modelAnswer": "um ... zu", "correctAnswer": "um ... zu"}, {"id": "g25-12c", "label": "c)", "prompt": "___ Lorenz Jennifers Angebot ablehnt, fährt er Cougar behutsam durch das goldfarbene Fell.", "modelAnswer": "Indem / Während / Als (toleriert: Bevor / Ehe / Sobald)", "correctAnswer": "Indem"}, {"id": "g25-12d", "label": "d)", "prompt": "Allem Anschein zum ___ wolle er aber Cougar nicht verkaufen, meinte Lorenz zu Jennifer.", "correctAnswer": "Trotz"}]}, {"id": "g25-13", "type": "input", "number": 13, "prompt": "Die Sätze unten weisen jeweils genau einen Grammatikfehler auf. Korrigiere diese Fehler, indem du je ein Wort durchstreichst und ein anderes darüberschreibst. Zwei oder mehr Korrekturen pro Satz ergeben in jedem Fall 0 Punkte.", "subTasks": [{"id": "g25-13a", "label": "a)", "prompt": "Das Mädchen, das auf Lorenz **zulaufte**, war klein.", "modelAnswer": "zulaufte → zulief (toleriert: zukam/zurannte)", "correctAnswer": "zulief"}, {"id": "g25-13b", "label": "b)", "prompt": "Er nahm die Stöpsel aus den Ohren, **weil** er konnte Jennifer sonst schlicht und einfach nicht verstehen.", "modelAnswer": "weil → denn", "correctAnswer": "denn"}, {"id": "g25-13c", "label": "c)", "prompt": "Jennifer war grösser **wie** Cougar, wirkte auf Lorenz jedoch wie ein kleines Kind auf dem Heimweg.", "modelAnswer": "wie → als (toleriert: denn)", "correctAnswer": "als"}, {"id": "g25-13d", "label": "d)", "prompt": "Sie machte Lorenz **sein** bestes Angebot, das aus den drei Münzen bestand, die sie bei sich trug.", "modelAnswer": "sein → ihr", "correctAnswer": "ihr"}, {"id": "g25-13e", "label": "e)", "prompt": "Die Mutter notierte sich Lorenz'' Handynummer und versprach, **ihm** anzurufen, wenn Jennifer bereit sei.", "modelAnswer": "ihm → ihn (toleriert: Lorenz)", "correctAnswer": "ihn"}]}, {"id": "g25-14", "type": "text-area", "number": 14, "prompt": "Stelle die folgenden Sätze wie im Beispiel dar und gib zu den einzelnen Wortgruppen jeweils die passende Frage an.", "context": "**Beispiel:** Am Anfang zerrt Cougar heftig an der Leine.\n- Am Anfang → wann?\n- Cougar → wer?\n- heftig → wie?\n- an der Leine → woran?", "subTasks": [{"id": "g25-14a", "label": "a)", "prompt": "Der Kleinen begegnet heute unverhofft Cougar.", "modelAnswer": "Der Kleinen → wem? | heute → wann? | unverhofft → wie? | Cougar → wer?"}, {"id": "g25-14b", "label": "b)", "prompt": "Später denkt Lorenz lächelnd über die Geschichte nach.", "modelAnswer": "Später → wann? | Lorenz → wer? | lächelnd → wie? | über die Geschichte → worüber?"}, {"id": "g25-14c", "label": "c)", "prompt": "Sollte er Cougar Jennifer darum verkaufen?", "modelAnswer": "er → wer? | Cougar → wen? | Jennifer → wem? | darum → warum?/wieso?/weshalb?/weswegen?"}]}]}', '{"Lorenz hatte Ohrstöpsel an und hörte Musik. Ein sehnsüchtiges Lied, das ihn an daheim erinnerte. In seiner","Hand hielt Lorenz eine Leine. An der Leine zog ein Hund. Sein Hund. Ein lieber Hund, ein netter Hund,","aber nur ein Hund. Wenn jemand alleine ist, dann bleibt einem nur der Hund als treuer Freund. Lorenz war","froh, dass seine Eltern ihm nach seinem Umzug hierher den Labrador gekauft hatten. Er nahm den","Kopfhörer ab, denn vor ihm stand ein kleines Mädchen.","«Oh, wie süss! Das ist ja ein lieber Hund!», schwärmte das Kind und umarmte das verdutzte Tier. Lorenz","schaute erstaunt und fasziniert zu, wie sich sein sonst eher misstrauischer Hund streicheln liess.","«Das ist Cougar», sagte Lorenz.","Sie löste sich wieder von Cougar und blickte den Hund sehnsüchtig aus rehbraunen Augen an:","«Ich möchte so gerne auch einen Hund haben», seufzte sie. «Genau so einen wie den da. Wie lieb er mich","anschaut!» Das Mädchen schaute Lorenz mit ihren grossen Augen bittend, beinahe flehend an. Lorenz","lächelte etwas unsicher und meinte: «Kauf dir halt auch einen!»","«Ich will aber genau den da», sagte das Mädchen und deutete auf Cougar. «Darf ich ihn dir abkaufen?» Sie","lächelte Lorenz erwartungsvoll an. Gleichzeitig nahm sie Cougar in die Arme und auch er begann mit","seinen unschuldigen Hundeaugen Lorenz anzustarren. Ganz so, als wollte er ebenso sagen: «Bitte, bitte,","verkauf mich an das Mädchen!»","Lorenz musterte seinen Hund etwas enttäuscht. Sicher, er hatte ihn nicht immer so gut behandelt, war","nicht immer Gassi gegangen, hatte ihn nicht immer rechtzeitig gefüttert. Aber war das ein Grund, dass er","sich nun mit dem erstbesten Mädchen gegen ihn verschwor? Lorenz fuhr Cougar behutsam durch das Fell:","«Tut mir leid, aber eigentlich will ich ihn behalten.»","«Warum heisst er Cougar? Und was bedeutet überhaupt Cougar?», fragte das Mädchen.","«Cougar ist Englisch und bedeutet in unserer Sprache Puma», antwortete Lorenz. «Das sind diese","goldfarbenen Berglöwen.» Sie lachte. «Das ist lustig! Denn es passt, aber auch nicht. Das wäre, wie wenn","unsere graue Nachbarskatze Wolfi hiesse. Cougar, ich hab dich lieb.» Sie gab dem Hund einen zarten Kuss","auf das dunkelblonde Fell. Das Mädchen griff in seine Tasche und zog drei Münzen heraus: «Mehr hab ich","nicht», murmelte es kleinlaut. Hund und Mädchen starrten Lorenz beinahe beschwörend an.","«Ach, Cougar», seufzte Lorenz betroffen, «willst du mich denn wirklich loswerden?»","Das Mädchen drückte ihm das Geld in die Hand und begann zu betteln: «Bitte, bitte, verkaufe mir dein","süsses, liebes, braves Hundilein.»","Inzwischen war die Mutter des Mädchens aus ihrem Haus nach draussen gekommen und beobachtete","schmunzelnd das Feilschen. Das Mädchen klammerte sich verliebt an Cougar. Cougar begann winselnd zu","jaulen. Und Lorenz versuchte, dem Mädchen die Münzen zurückzugeben. Jetzt griff die Mutter ein:","«Jennifer! Du kannst dem jungen Mann doch nicht den Hund abkaufen. Der hat ihn doch auch lieb», worauf","Lorenz hilflos nickte. Jennifer wollte von Cougar nicht ablassen. «Bitte, Mami. Bitte, lass mich den Hund","behalten. Der Hund hat mich viel lieber als ihn. Nicht wahr, Cougar?»","Cougar bellte drei Mal laut, als wollte er unbedingt zustimmen. Lorenz fühlte sich hundselend, denn die","Vorstellung, dass er seinen einzigen Freund in der fremden Stadt verlor, schnürte ihm die Kehle zu. Die","Mutter kniete sich zu ihrer Tochter hinab und streichelte ihr durchs Haar: «Nicht traurig sein, Jenny. Zum","Geburtstag darfst du dir einen Hund wünschen, dann bist du alt genug. Jetzt bedank dich bei dem Mann,","dass du mit dem Hund spielen durftest. Aber er muss jetzt bestimmt nach Hause.»","Lorenz atmete erleichtert auf: «Vielen Dank», sagte er zu der Frau.","Endlich löste sich Jenny von Cougar: «Tschüss, lieber Cougar. Ich hoffe, wir sehen uns bald wieder.»","Sie wandte sich an Lorenz: «Vielleicht darf ich mit euch spazieren gehen?»","Lorenz nickte: «Wenn du magst, klingle ich morgen bei dir.»","Die Mutter nickte Lorenz zu und verabschiedete sich. Dann ging sie zurück ins Haus. Als Lorenz sich nach","einigen Metern noch einmal umdrehte, stand Jennifer noch immer an der Strasse. Sie winkte beiden zu.","Lorenz steckte sich wieder die Kopfhörerstöpsel in die Ohren und ging weiter: Als nächstes Lied wählte er","eines, das zum fröhlichen Tanzen einlud."}', '2026-02-22 22:49:47.993678+00', '2026-02-22 22:49:47.993678+00'),
	('german-2025-gemini', 'Sprachprüfung Deutsch 2025 (Langgymnasium)', 'German', 2025, 'Gemini 3 Pro', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch.", "Du darfst wählen, in welcher Reihenfolge du die Aufgaben löst.", "In den Aufgaben 3, 6, 8, 11 und 13 führen Rechtschreibe- und Grammatikfehler zu einem Punkteabzug."], "maxPoints": 48}, "questions": [{"id": "g25-1", "type": "input", "number": 1, "prompt": "Zu welcher Rasse gehört Lorenz'' Hund?", "subTasks": [{"id": "g25-1a", "label": "Antwort:", "prompt": "Rasse:", "modelAnswer": "Labrador", "correctAnswer": "Labrador"}]}, {"id": "g25-2", "type": "text-area", "number": 2, "prompt": "Lies die Zeilen 1 bis 8 noch einmal: Was überrascht Lorenz daran, wie Cougar auf Jennifer reagiert?", "subTasks": [{"id": "g25-2a", "label": "Antwort:", "prompt": "Ihn überrascht, dass...", "modelAnswer": "sein sonst misstrauischer Hund sich streicheln lässt / zutraulich ist."}]}, {"id": "g25-3", "type": "text-area", "number": 3, "prompt": "Fragen zum Namen ''Cougar''.", "subTasks": [{"id": "g25-3a", "label": "a)", "prompt": "Lies die Zeilen 22-26. Der Text gibt einen Hinweis, der erklären kann, warum Lorenz seinen Hund Cougar genannt hat. Um welchen Hinweis handelt es sich?", "modelAnswer": "Die (Fell-)Farbe / Die Fellfarbe ist ähnlich (goldfarben)."}, {"id": "g25-3b", "label": "b)", "prompt": "Jennifer findet den Namen unpassend. Nenne zwei unterschiedliche Gründe.", "modelAnswer": "1. Pumas sind Katzen, Cougar ist ein Hund. 2. Pumas sind Wildtiere/gefährlich, Cougar ist ein Haustier/zahm."}]}, {"id": "g25-4", "type": "input", "number": 4, "prompt": "Beziehung zwischen Lorenz und Cougar.", "subTasks": [{"id": "g25-4a", "label": "a)", "prompt": "Auf den ersten Blick scheint Cougar für Lorenz nicht so wichtig zu sein. Gib die Zeilennummer des Satzes an, der dies zeigt (z.B. ''2-3'').", "modelAnswer": "2-3 (oder 3, oder 17-18)", "correctAnswer": "2-3"}, {"id": "g25-4b-1", "label": "b) 1.", "prompt": "Gib einen Satz an (Zeile 27-48), der zeigt, dass Cougar viel für Lorenz bedeutet. Zeile(n):", "modelAnswer": "27 (Ach, Cougar, seufzte Lorenz betroffen...)", "correctAnswer": "27"}, {"id": "g25-4b-2", "label": "b) 2.", "prompt": "Zweiter Satz. Zeile(n):", "modelAnswer": "33-34 (Der hat ihn doch auch lieb...)", "correctAnswer": "33-34"}, {"id": "g25-4b-3", "label": "b) 3.", "prompt": "Dritter Satz. Zeile(n):", "modelAnswer": "36-37 (Lorenz fühlte sich hundselend...)", "correctAnswer": "36-37"}]}, {"id": "g25-5", "rows": [{"id": "r1", "text": "Lorenz ist vom Dorf in die Stadt gezogen."}, {"id": "r2", "text": "Die Geschichte spielt im Herbst."}, {"id": "r3", "text": "Lorenz reagiert im Gespräch mit Jennifer immer selbstbewusst."}, {"id": "r4", "text": "Es scheint, als ob Cougar bei Jennifer bleiben möchte."}, {"id": "r5", "text": "Dass Cougar drei Mal bellt, ist der eindeutige Beweis dafür, dass er viel lieber bei Jennifer als bei Lorenz wäre."}, {"id": "r6", "text": "Lorenz verlangt von Jennifer mehr Geld für den Hund."}, {"id": "r7", "text": "Lorenz fühlt sich von Cougar verraten."}], "type": "table-select", "number": 5, "prompt": "Kreuze bei den folgenden Aussagen an, ob sie mit dem Inhalt der Geschichte übereinstimmen (✓), nicht (-) oder ob es nicht entschieden werden kann (?).", "columns": [{"id": "c_true", "label": "✓"}, {"id": "c_false", "label": "-"}, {"id": "c_unknown", "label": "?"}], "subTasks": [{"id": "g25-5-sub", "label": "Tabelle", "prompt": "Kreuze an."}], "correctTableAnswers": {"r1": "c_unknown", "r2": "c_unknown", "r3": "c_false", "r4": "c_true", "r5": "c_false", "r6": "c_false", "r7": "c_true"}}, {"id": "g25-6", "type": "input", "number": 6, "prompt": "Bedeutung der Lieder für das Textverständnis.", "subTasks": [{"id": "g25-6a", "label": "a)", "prompt": "Die beiden Lieder widerspiegeln die jeweilige ____ von Lorenz.", "modelAnswer": "Stimmung / Gefühlslage / Laune", "correctAnswer": "Stimmung"}, {"id": "g25-6b", "label": "b)", "prompt": "Erkläre in einem Satz, was sich bei ihm verändert hat.", "modelAnswer": "Lorenz'' Stimmung hat sich vom Negativen ins Positive gewandelt / Er ist nicht mehr einsam."}]}, {"id": "g25-7", "type": "input", "number": 7, "prompt": "Lorenz durchlebt ein Wechselbad von Gefühlen. Ergänze die Lücken mit je einem passenden Nomen aus der Box.", "context": "Box: Betroffenheit, Ekel, Elend, Enttäuschung, Erleichterung, Hilflosigkeit, Liebeskummer, Neugier, Sehnsucht, Verunsicherung, Wut", "subTasks": [{"id": "g25-7a", "label": "a)", "prompt": "Nun will Jennifer Cougar kaufen und dessen Blick scheint Lorenz zum Verkauf zu ermuntern. Darüber verspürt Lorenz", "correctAnswer": "Enttäuschung"}, {"id": "g25-7b", "label": "b)", "prompt": "Jennifer reicht Lorenz drei Münzen. Lorenz spürt in diesem Moment", "correctAnswer": "Betroffenheit"}, {"id": "g25-7c", "label": "c)", "prompt": "Nun greift Jennifers Mutter ins Geschehen ein. Sie erkennt nämlich Lorenz'' zunehmende", "correctAnswer": "Hilflosigkeit"}, {"id": "g25-7d", "label": "d)", "prompt": "Als Jennifer behauptet, Cougar habe sie lieber als Lorenz, bellt der Hund. Jetzt erfasst Lorenz", "correctAnswer": "Elend"}, {"id": "g25-7e", "label": "e)", "prompt": "Die Mutter bietet Lorenz einen Ausweg an. Diesen erfasst", "correctAnswer": "Erleichterung"}]}, {"id": "g25-8", "rows": [{"id": "r1", "text": "Der Satz zeigt eindeutig, dass alle Hunde die Menschensprache verstehen."}, {"id": "r2", "text": "Der Satz zeigt, dass Cougar Jennifer mag."}, {"id": "r3", "text": "Der Satz zeigt den Hund, als wäre er ein Mensch, weil er scheinbar versteht, was die Menschen sprechen."}], "type": "table-select", "number": 8, "prompt": "Wirkung des Satzes: «Cougar bellte drei Mal laut, als wollte er unbedingt zustimmen».", "columns": [{"id": "c_true", "label": "✓"}, {"id": "c_false", "label": "-"}, {"id": "c_unknown", "label": "?"}], "subTasks": [{"id": "g25-8-sub", "label": "Tabelle", "prompt": "Kreuze an."}, {"id": "g25-8b", "label": "b)", "prompt": "Vergleich Satz A («Als Zustimmung bellte Cougar...») und B («...als wollte er...»). Erkläre den Unterschied.", "modelAnswer": "In Satz A ist es eine Tatsache (er stimmt zu), in Satz B ist es nur eine Vermutung/Möglichkeit."}], "correctTableAnswers": {"r1": "c_false", "r2": "c_unknown", "r3": "c_true"}}, {"id": "g25-9", "type": "multiple-choice", "number": 9, "prompt": "Kreuze jeweils nur die Lösung an, die der Bedeutung der fett gedruckten Wörter und Ausdrücke am besten entspricht.", "subTasks": [{"id": "g25-9a", "label": "a)", "prompt": "«... **schwärmte** das Kind» (Z. 6)", "options": ["sagte leise", "sagte laut", "sagte begeistert", "sagte übermütig", "sagte weinerlich"], "correctAnswer": "sagte begeistert"}, {"id": "g25-9b", "label": "b)", "prompt": "«... umarmte das **verdutzte** Tier» (Z. 6)", "options": ["verängstigte", "misstrauische", "zutrauliche", "erstaunte", "arglose"], "correctAnswer": "erstaunte"}, {"id": "g25-9c", "label": "c)", "prompt": "«... dass er sich ... gegen ihn **verschwor**?» (Z. 18/19)", "options": ["zusammentat", "einschwor", "vertat", "bewarb", "aufmachte"], "correctAnswer": "zusammentat"}, {"id": "g25-9d", "label": "d)", "prompt": "«Lorenz fuhr Cougar **behutsam** durch das Fell» (Z. 19)", "options": ["ruhig", "gelassen", "vorsichtig", "nachdenklich", "behütet"], "correctAnswer": "vorsichtig"}]}, {"id": "g25-10", "rows": [{"id": "r1_1", "text": "Wortfeld: (jemanden) verärgern -> enttäuschen"}, {"id": "r1_2", "text": "frustrieren"}, {"id": "r1_3", "text": "verdriessen"}, {"id": "r1_4", "text": "verdonnern"}, {"id": "r1_5", "text": "bedrohen"}, {"id": "r2_1", "text": "Wortfeld: sehen -> schauen"}, {"id": "r2_2", "text": "blinzeln"}, {"id": "r2_3", "text": "gaffen"}, {"id": "r2_4", "text": "versehen"}, {"id": "r2_5", "text": "beobachten"}, {"id": "r3_1", "text": "Wortfeld: flehen -> mahnen"}, {"id": "r3_2", "text": "beschwören"}, {"id": "r3_3", "text": "anbeten"}, {"id": "r3_4", "text": "bitten"}, {"id": "r3_5", "text": "beknien"}, {"id": "r4_1", "text": "Wortfeld: gehen -> unterlaufen"}, {"id": "r4_2", "text": "schreiten"}, {"id": "r4_3", "text": "sich begeben"}, {"id": "r4_4", "text": "vergehen"}, {"id": "r4_5", "text": "aufsuchen"}], "type": "table-select", "number": 10, "prompt": "Kreuze in der rechten Spalte jene zwei Verben an, die am **wenigsten** in das angegebene Wortfeld passen.", "columns": [{"id": "c_fit", "label": "Passt"}, {"id": "c_odd", "label": "Passt nicht"}], "subTasks": [{"id": "g25-10-sub", "label": "Tabelle", "prompt": "Wähle die unpassenden Verben (je 2 pro Wortfeld)."}], "correctTableAnswers": {"r1_1": "c_fit", "r1_2": "c_fit", "r1_3": "c_fit", "r1_4": "c_odd", "r1_5": "c_odd", "r2_1": "c_fit", "r2_2": "c_odd", "r2_3": "c_fit", "r2_4": "c_odd", "r2_5": "c_fit", "r3_1": "c_odd", "r3_2": "c_fit", "r3_3": "c_odd", "r3_4": "c_fit", "r3_5": "c_fit", "r4_1": "c_odd", "r4_2": "c_fit", "r4_3": "c_fit", "r4_4": "c_odd", "r4_5": "c_fit"}}, {"id": "g25-11", "type": "input", "number": 11, "prompt": "Bilde ausgehend vom Wortstamm der fett gedruckten Wörter ein neues Wort aus derselben Wortfamilie.", "subTasks": [{"id": "g25-11a", "label": "a)", "prompt": "**fasziniert** -> Lorenz schaute mit einer gewissen ____ zu.", "correctAnswer": "Faszination"}, {"id": "g25-11b", "label": "b)", "prompt": "**seufzte** -> «Ich möchte so gerne auch einen Hund haben», meinte sie ____.", "correctAnswer": "seufzend"}, {"id": "g25-11c", "label": "c)", "prompt": "**Musterung** -> Lorenz ____ seinen Hund überrascht.", "correctAnswer": "musterte"}, {"id": "g25-11d", "label": "d)", "prompt": "**flehentlich** -> Sie schaute ihn beinahe ____ an.", "modelAnswer": "flehend / anflehend", "correctAnswer": "flehend"}, {"id": "g25-11e", "label": "e)", "prompt": "**klammerte** -> Jennys ____ von Cougar verdeutlichte ihre Verliebtheit.", "modelAnswer": "Umklammerung / Umklammern", "correctAnswer": "Umklammerung"}, {"id": "g25-11f", "label": "f)", "prompt": "**unbedingt** -> Cougar bellte drei Mal, als wolle er ____ zustimmen.", "correctAnswer": "bedingungslos"}]}, {"id": "g25-12", "type": "input", "number": 12, "prompt": "Setze jeweils ein passendes Wort in die Lücke.", "subTasks": [{"id": "g25-12a", "label": "a)", "prompt": "Cougar starrt Lorenz in einer solchen Art und Weise an, ____ es ganz so scheint, als wolle er ebenso zustimmen.", "modelAnswer": "dass / sodass / womit", "correctAnswer": "dass"}, {"id": "g25-12b", "label": "b)", "prompt": "Ist das ein Grund, ____ sich mit dem erstbesten Mädchen gegen ihn ____ verschwören?", "modelAnswer": "um ... zu", "correctAnswer": "um ... zu"}, {"id": "g25-12c", "label": "c)", "prompt": "____ Lorenz Jennifers Angebot ablehnt, fährt er Cougar behutsam durch das goldfarbene Fell.", "modelAnswer": "Indem / Während / Als", "correctAnswer": "Indem"}, {"id": "g25-12d", "label": "d)", "prompt": "Allem Anschein zum ____ wolle er aber Cougar nicht verkaufen, meinte Lorenz zu Jennifer.", "correctAnswer": "Trotz"}]}, {"id": "g25-13", "type": "input", "number": 13, "prompt": "Die Sätze unten weisen jeweils genau einen Grammatikfehler auf. Korrigiere diese Fehler.", "subTasks": [{"id": "g25-13a", "label": "a)", "prompt": "Das Mädchen, das auf Lorenz **zulaufte**, war klein. ->", "correctAnswer": "zulief"}, {"id": "g25-13b", "label": "b)", "prompt": "Er nahm die Stöpsel aus den Ohren, **weil** er konnte Jennifer sonst schlicht und einfach nicht verstehen. ->", "correctAnswer": "denn"}, {"id": "g25-13c", "label": "c)", "prompt": "Jennifer war grösser **wie** Cougar, wirkte auf Lorenz jedoch wie ein kleines Kind. ->", "correctAnswer": "als"}, {"id": "g25-13d", "label": "d)", "prompt": "Sie machte Lorenz sein bestes Angebot, das aus den drei Münzen bestand, die sie bei sich trug. (**sein** bestes) ->", "correctAnswer": "ihr"}, {"id": "g25-13e", "label": "e)", "prompt": "Die Mutter notierte sich Lorenz Handynummer und versprach, **ihm** anzurufen. ->", "correctAnswer": "ihn"}]}, {"id": "g25-14", "type": "input", "number": 14, "prompt": "Stelle die folgenden Sätze wie im Beispiel dar und gib zu den einzelnen Wortgruppen jeweils die passende Frage an.", "subTasks": [{"id": "g25-14a-1", "label": "a) Der Kleinen", "prompt": "Frage:", "correctAnswer": "wem?"}, {"id": "g25-14a-2", "label": "heute", "prompt": "Frage:", "correctAnswer": "wann?"}, {"id": "g25-14a-3", "label": "unverhofft", "prompt": "Frage:", "correctAnswer": "wie?"}, {"id": "g25-14a-4", "label": "Cougar", "prompt": "Frage:", "correctAnswer": "wer?"}, {"id": "g25-14b-1", "label": "b) Später", "prompt": "Frage:", "correctAnswer": "wann?"}, {"id": "g25-14b-2", "label": "Lorenz", "prompt": "Frage:", "correctAnswer": "wer?"}, {"id": "g25-14b-3", "label": "lächelnd", "prompt": "Frage:", "correctAnswer": "wie?"}, {"id": "g25-14b-4", "label": "über die Geschichte", "prompt": "Frage:", "modelAnswer": "worüber? / über was?", "correctAnswer": "worüber?"}, {"id": "g25-14c-1", "label": "c) er", "prompt": "Frage:", "correctAnswer": "wer?"}, {"id": "g25-14c-2", "label": "Cougar", "prompt": "Frage:", "correctAnswer": "wen?"}, {"id": "g25-14c-3", "label": "Jennifer", "prompt": "Frage:", "correctAnswer": "wem?"}, {"id": "g25-14c-4", "label": "darum", "prompt": "Frage:", "modelAnswer": "warum? / wieso? / weshalb? / weswegen?", "correctAnswer": "warum?"}]}]}', '{"Lorenz hatte Ohrstöpsel an und hörte Musik. Ein sehnsüchtiges Lied, das ihn an daheim erinnerte. In seiner","Hand hielt Lorenz eine Leine. An der Leine zog ein Hund. Sein Hund. Ein lieber Hund, ein netter Hund,","aber nur ein Hund. Wenn jemand alleine ist, dann bleibt einem nur der Hund als treuer Freund. Lorenz war","froh, dass seine Eltern ihm nach seinem Umzug hierher den Labrador gekauft hatten. Er nahm den","Kopfhörer ab, denn vor ihm stand ein kleines Mädchen.","«Oh, wie süss! Das ist ja ein lieber Hund!», schwärmte das Kind und umarmte das verdutzte Tier. Lorenz","schaute erstaunt und fasziniert zu, wie sich sein sonst eher misstrauischer Hund streicheln liess.","«Das ist Cougar», sagte Lorenz.","Sie löste sich wieder von Cougar und blickte den Hund sehnsüchtig aus rehbraunen Augen an:","«Ich möchte so gerne auch einen Hund haben», seufzte sie. «Genau so einen wie den da. Wie lieb er mich","anschaut!» Das Mädchen schaute Lorenz mit ihren grossen Augen bittend, beinahe flehend an. Lorenz","lächelte etwas unsicher und meinte: «Kauf dir halt auch einen!»","«Ich will aber genau den da», sagte das Mädchen und deutete auf Cougar. «Darf ich ihn dir abkaufen?» Sie","lächelte Lorenz erwartungsvoll an. Gleichzeitig nahm sie Cougar in die Arme und auch er begann mit","seinen unschuldigen Hundeaugen Lorenz anzustarren. Ganz so, als wollte er ebenso sagen: «Bitte, bitte,","verkauf mich an das Mädchen!»","Lorenz musterte seinen Hund etwas enttäuscht. Sicher, er hatte ihn nicht immer so gut behandelt, war","nicht immer Gassi gegangen, hatte ihn nicht immer rechtzeitig gefüttert. Aber war das ein Grund, dass er","sich nun mit dem erstbesten Mädchen gegen ihn verschwor?","Lorenz fuhr Cougar behutsam durch das Fell:","«Tut mir leid, aber eigentlich will ich ihn behalten.»","«Warum heisst er Cougar? Und was bedeutet überhaupt Cougar?», fragte das Mädchen.","«Cougar ist Englisch und bedeutet in unserer Sprache Puma», antwortete Lorenz. «Das sind diese","goldfarbenen Berglöwen.»","Sie lachte. «Das ist lustig! Denn es passt, aber auch nicht. Das wäre, wie wenn","unsere graue Nachbarskatze Wolfi hiesse. Cougar, ich hab dich lieb.» Sie gab dem Hund einen zarten Kuss","auf das dunkelblonde Fell. Das Mädchen griff in seine Tasche und zog drei Münzen heraus: «Mehr hab ich","nicht», murmelte es kleinlaut. Hund und Mädchen starrten Lorenz beinahe beschwörend an.","«Ach, Cougar», seufzte Lorenz betroffen, «willst du mich denn wirklich loswerden?»","Das Mädchen drückte ihm das Geld in die Hand und begann zu betteln: «Bitte, bitte, verkaufe mir dein","süsses, liebes, braves Hundilein.»","Inzwischen war die Mutter des Mädchens aus ihrem Haus nach draussen gekommen und beobachtete","schmunzelnd das Feilschen. Das Mädchen klammerte sich verliebt an Cougar. Cougar begann winselnd zu","jaulen. Und Lorenz versuchte, dem Mädchen die Münzen zurückzugeben. Jetzt griff die Mutter ein:","«Jennifer! Du kannst dem jungen Mann doch nicht den Hund abkaufen. Der hat ihn doch auch lieb», worauf","Lorenz hilflos nickte. Jennifer wollte von Cougar nicht ablassen. «Bitte, Mami. Bitte, lass mich den Hund","behalten. Der Hund hat mich viel lieber als ihn. Nicht wahr, Cougar?»","Cougar bellte drei Mal laut, als wollte er unbedingt zustimmen. Lorenz fühlte sich hundselend, denn die","Vorstellung, dass er seinen einzigen Freund in der fremden Stadt verlor, schnürte ihm die Kehle zu. Die","Mutter kniete sich zu ihrer Tochter hinab und streichelte ihr durchs Haar: «Nicht traurig sein, Jenny. Zum","Geburtstag darfst du dir einen Hund wünschen, dann bist du alt genug. Jetzt bedank dich bei dem Mann,","dass du mit dem Hund spielen durftest. Aber er muss jetzt bestimmt nach Hause.»","Lorenz atmete erleichtert auf: «Vielen Dank», sagte er zu der Frau.","Endlich löste sich Jenny von Cougar: «Tschüss, lieber Cougar. Ich hoffe, wir sehen uns bald wieder.»","Sie wandte sich an Lorenz: «Vielleicht darf ich mit euch spazieren gehen?»","Lorenz nickte: «Wenn du magst, klingle ich morgen bei dir.»","Die Mutter nickte Lorenz zu und verabschiedete sich. Dann ging sie zurück ins Haus. Als Lorenz sich nach","einigen Metern noch einmal umdrehte, stand Jennifer noch immer an der Strasse. Sie winkte beiden zu.","Lorenz steckte sich wieder die Kopfhörerstöpsel in die Ohren und ging weiter: Als nächstes Lied wählte er","eines, das zum fröhlichen Tanzen einlud."}', '2026-02-22 22:49:48.102139+00', '2026-02-22 22:49:48.102139+00'),
	('german-2025-qwen', 'Deutsch 2025 (Langgymnasium)', 'German', 2025, 'Qwen 3 Max', '{"meta": {"time": "45 Minuten", "hints": ["Lies den Text auf dem beiliegenden Textblatt sorgfältig durch.", "Du darfst wählen, in welcher Reihenfolge du die Aufgaben löst.", "In den Aufgaben 3, 6, 8, 11 und 13 führen Rechtschreib- und Grammatikfehler zu einem Punkteabzug."], "maxPoints": 48}, "questions": [{"id": "german25-1", "type": "input", "number": 1, "prompt": "Zu welcher Rasse gehört Lorenz'' Hund?", "context": "", "subTasks": [{"id": "1a", "label": "", "prompt": "", "modelAnswer": "Labrador", "correctAnswer": "Labrador"}]}, {"id": "german25-2", "type": "text-area", "number": 2, "prompt": "Lies die Zeilen 1 bis 8 noch einmal: Was überrascht Lorenz daran, wie Cougar auf Jennifer reagiert?", "context": "", "subTasks": [{"id": "2a", "label": "", "prompt": "Ihn überrascht, dass", "modelAnswer": "sein sonst misstrauischer Hund sich streicheln lässt."}]}, {"id": "german25-3", "type": "text-area", "number": 3, "prompt": "a. Lies die Zeilen 22–26 noch einmal: Der Text gibt uns hier einen Hinweis, der erklären kann, warum Lorenz seinen Hund Cougar genannt hat. Um welchen Hinweis handelt es sich?\n\nb. Jennifer findet den Namen Cougar witzig, weil er aus ihrer Sicht nicht passt. Erkläre genau, warum sie den Namen unpassend findet, indem du zwei unterschiedliche Gründe nennst.", "context": "", "subTasks": [{"id": "3a", "label": "a.", "prompt": "Um welchen Hinweis handelt es sich?", "modelAnswer": "um die goldfarbene Fellfarbe, die bei Pumas und Cougar gleich ist."}, {"id": "3b1", "label": "Erster Grund:", "prompt": "Der Name ist aus ihrer Sicht unpassend, denn", "modelAnswer": "Cougar ist ein Hund und kein Raubtier wie ein Puma."}, {"id": "3b2", "label": "Zweiter Grund:", "prompt": "Der Name ist aus ihrer Sicht unpassend, denn", "modelAnswer": "Pumas sind Wildtiere, Cougar ist ein zahmes Haustier."}]}, {"id": "german25-4", "type": "input", "number": 4, "prompt": "a. Auf den ersten Blick scheint Cougar für Lorenz nicht so wichtig zu sein. Gib die Zeilennummer des Satzes an, in dem diese Information zu finden ist.\n\nb. Diese oberflächliche Betrachtung ist jedoch falsch: Cougar bedeutet viel für Lorenz. Gib drei unterschiedliche Sätze zwischen Zeile 27 und Zeile 48 an, die das zeigen.", "context": "", "subTasks": [{"id": "4a", "label": "a. Zeile(n) Nummer", "prompt": "", "correctAnswer": "17–18"}, {"id": "4b1", "label": "Erster Satz: Zeile(n) Nummer", "prompt": "", "correctAnswer": "27"}, {"id": "4b2", "label": "Zweiter Satz: Zeile(n) Nummer", "prompt": "", "correctAnswer": "33–34"}, {"id": "4b3", "label": "Dritter Satz: Zeile(n) Nummer", "prompt": "", "correctAnswer": "36–37"}]}, {"id": "german25-5", "rows": [{"id": "5a", "text": "Lorenz ist vom Dorf in die Stadt gezogen."}, {"id": "5b", "text": "Die Geschichte spielt im Herbst."}, {"id": "5c", "text": "Lorenz reagiert im Gespräch mit Jennifer immer selbstbewusst."}, {"id": "5d", "text": "Es scheint, als ob Cougar bei Jennifer bleiben möchte."}, {"id": "5e", "text": "Dass Cougar drei Mal bellt, ist der eindeutige Beweis dafür, dass er viel lieber bei Jennifer als bei Lorenz wäre."}, {"id": "5f", "text": "Lorenz verlangt von Jennifer mehr Geld für den Hund."}, {"id": "5g", "text": "Lorenz fühlt sich von Cougar verraten."}], "type": "table-select", "number": 5, "prompt": "Kreuze bei den folgenden Aussagen an, ob sie mit dem Inhalt der Geschichte übereinstimmen (ü) oder nicht (–). Setze das Kreuz beim Fragezeichen (?), wenn das nicht entschieden werden kann. Es darf nur ein Kreuz pro Zeile gesetzt werden.", "columns": [{"id": "correct", "label": "ü"}, {"id": "incorrect", "label": "–"}, {"id": "unknown", "label": "?"}], "context": "", "subTasks": [], "correctTableAnswers": {"5a": "unknown", "5b": "unknown", "5c": "incorrect", "5d": "correct", "5e": "incorrect", "5f": "incorrect", "5g": "correct"}}, {"id": "german25-6", "type": "text-area", "number": 6, "prompt": "a. Warum ist es für das Textverständnis wichtig zu wissen, dass Lorenz am Anfang (Z. 1) und am Ende (Z. 47–48) zwei unterschiedliche Lieder wählt? Antworte, indem du den Satz mit einem passenden Nomen ergänzt.\n\nb. Die Lieder zeigen ausserdem, dass mit Lorenz im Laufe der Ereignisse etwas geschehen ist. Erkläre in einem Satz, was sich bei ihm verändert hat.", "context": "", "subTasks": [{"id": "6a", "label": "a.", "prompt": "Die beiden Lieder widerspiegeln die jeweilige", "modelAnswer": "Stimmung"}, {"id": "6b", "label": "b.", "prompt": "", "modelAnswer": "Lorenz’ Stimmung hat sich vom Heimweh hin zu Fröhlichkeit gewandelt."}]}, {"id": "german25-7", "type": "input", "number": 7, "prompt": "Lorenz durchlebt ein Wechselbad von Gefühlen. Ergänze die Lücken mit je einem passenden Nomen aus der Box. Du darfst jedes Nomen höchstens einmal verwenden.", "context": "Betroffenheit, Ekel, Elend, Enttäuschung, Erleichterung, Hilflosigkeit, Liebeskummer, Neugier, Sehnsucht, Verunsicherung, Wut", "subTasks": [{"id": "7a", "label": "a.", "prompt": "Darüber verspürt Lorenz", "correctAnswer": "Enttäuschung"}, {"id": "7b", "label": "b.", "prompt": "Lorenz spürt in diesem Moment", "correctAnswer": "Betroffenheit"}, {"id": "7c", "label": "c.", "prompt": "Sie erkennt nämlich Lorenz'' zunehmende", "correctAnswer": "Hilflosigkeit"}, {"id": "7d", "label": "d.", "prompt": "Jetzt erfasst Lorenz", "correctAnswer": "Elend"}, {"id": "7e", "label": "e.", "prompt": "Diesen erfasst", "correctAnswer": "Erleichterung"}]}, {"id": "german25-8", "rows": [{"id": "8a1", "text": "Der Satz zeigt eindeutig, dass alle Hunde die Menschensprache verstehen."}, {"id": "8a2", "text": "Der Satz zeigt, dass Cougar Jennifer mag."}, {"id": "8a3", "text": "Der Satz zeigt den Hund, als wäre er ein Mensch, weil er scheinbar versteht, was die Menschen sprechen."}], "type": "table-select", "number": 8, "prompt": "a. Welche Wirkung hat der Satz auf Zeile 36: „Cougar bellte drei Mal laut, als wollte er unbedingt zustimmen“?\n\nb. Vergleiche die zwei folgenden Sätze:\nSatz A: „Als Zustimmung bellte Cougar drei Mal laut.“\nSatz B: „Cougar bellte drei Mal laut, als wollte er unbedingt zustimmen.“\nSatz A unterscheidet sich inhaltlich von Satz B. Erkläre den Unterschied in eigenen Worten.", "columns": [{"id": "correct", "label": "ü"}, {"id": "incorrect", "label": "–"}, {"id": "unknown", "label": "?"}], "context": "", "subTasks": [{"id": "8b1", "label": "In Satz A", "prompt": "", "modelAnswer": "wird das Bellen als klare Zustimmung beschrieben."}, {"id": "8b2", "label": "In Satz B hingegen", "prompt": "", "modelAnswer": "wird das Bellen als mögliche, aber nicht sichere Zustimmung dargestellt."}], "correctTableAnswers": {"8a1": "incorrect", "8a2": "unknown", "8a3": "correct"}}, {"id": "german25-9", "type": "multiple-choice", "number": 9, "prompt": "Kreuze jeweils nur die Lösung an, die der Bedeutung der fett gedruckten Wörter und Ausdrücke am besten entspricht. Deine Lösung muss inhaltlich zum Text passen.", "context": "", "subTasks": [{"id": "9a", "label": "«‘Das ist ja ein lieber Hund’, schwärmte das Kind» (Z. 6)", "options": ["sagte... leise", "sagte... laut", "sagte... begeistert", "sagte... übermütig", "sagte... weinerlich"], "correctAnswer": "sagte... begeistert"}, {"id": "9b", "label": "«Das Kind [...] umarmte das verdutzte Tier.» (Z. 6)", "options": ["verängstigte", "misstrauische", "zutrauliche", "erstaunte", "arglose"], "correctAnswer": "erstaunte"}, {"id": "9c", "label": "«[...] dass er sich nun mit dem erstbesten Mädchen gegen ihn verschwor?» (Z. 18/19)", "options": ["zusammentat", "einschwor", "vertat", "bewarb", "aufmachte"], "correctAnswer": "zusammentat"}, {"id": "9d", "label": "«Lorenz fuhr Cougar behutsam durch das Fell» (Z. 19)", "options": ["ruhig", "gelassen", "vorsichtig", "nachdenklich", "behütet"], "correctAnswer": "vorsichtig"}]}, {"id": "german25-10", "rows": [{"id": "10a", "text": "verärgern: enttäuschen, frustrieren, verdriessen, **verdonnern**, **bedrohen**"}, {"id": "10b", "text": "sehen: schauen, **blinzeln**, gaffen, **versehen**, beobachten"}, {"id": "10c", "text": "flehen: **mahnen**, beschwören, **anbeten**, bitten, beknien"}, {"id": "10d", "text": "gehen: **unterlaufen**, schreiten, sich begeben, **vergehen**, aufsuchen"}], "type": "table-select", "number": 10, "prompt": "In der linken Spalte wird ein Wortfeld genannt. Kreuze in der rechten Spalte jene zwei Verben an, die am wenigsten in das angegebene Wortfeld passen.", "columns": [{"id": "wrong1", "label": "✖"}, {"id": "wrong2", "label": "✖"}], "context": "", "subTasks": [], "correctTableAnswers": {"10a": "wrong1", "10b": "wrong2", "10c": "wrong1", "10d": "wrong2"}}, {"id": "german25-11", "type": "input", "number": 11, "prompt": "Bilde ausgehend vom Wortstamm (Stamm-Morphem) der fett gedruckten Wörter ein neues Wort aus derselben Wortfamilie. Es muss in die Lücke passen.", "context": "", "subTasks": [{"id": "11a", "label": "a.", "prompt": "Lorenz schaute mit einer gewissen", "correctAnswer": "Faszination"}, {"id": "11b", "label": "b.", "prompt": "", "correctAnswer": "Seufzend"}, {"id": "11c", "label": "c.", "prompt": "Lorenz", "correctAnswer": "musterte"}, {"id": "11d", "label": "d.", "prompt": "Sie schaute ihn beinahe", "correctAnswer": "flehend"}, {"id": "11e", "label": "e.", "prompt": "Jennys", "correctAnswer": "Umklammerung"}, {"id": "11f", "label": "f.", "prompt": "Cougar bellte drei Mal, als wolle er", "correctAnswer": "bedingungslos"}]}, {"id": "german25-12", "type": "input", "number": 12, "prompt": "Setze jeweils ein passendes Wort in die Lücke, sodass stets ein inhaltlich und grammatikalisch korrekter Satz entsteht.", "context": "", "subTasks": [{"id": "12a", "label": "a.", "prompt": "Cougar starrt Lorenz in einer solchen Art und Weise an,", "correctAnswer": "dass"}, {"id": "12b", "label": "b.", "prompt": "Ist das ein Grund,", "correctAnswer": "um"}, {"id": "12c", "label": "c.", "prompt": "", "correctAnswer": "Als"}, {"id": "12d", "label": "d.", "prompt": "Allem Anschein zum", "correctAnswer": "Trotz"}]}, {"id": "german25-13", "type": "input", "number": 13, "prompt": "Die Sätze unten weisen jeweils genau einen Grammatikfehler auf. Korrigiere diese Fehler, indem du je ein Wort durchstreichst und ein anderes darüberschreibst.", "context": "", "subTasks": [{"id": "13a", "label": "a.", "prompt": "Das Mädchen, das auf Lorenz zulaufte, war klein.", "modelAnswer": "zukam", "correctAnswer": "zulaufte"}, {"id": "13b", "label": "b.", "prompt": "Er nahm die Stöpsel aus den Ohren, weil er konnte Jennifer sonst schlicht und einfach nicht verstehen.", "modelAnswer": "konnte", "correctAnswer": "konnte"}, {"id": "13c", "label": "c.", "prompt": "Jennifer war grösser wie Cougar, wirkte auf Lorenz jedoch wie ein kleines Kind auf dem Heimweg.", "modelAnswer": "als", "correctAnswer": "wie"}, {"id": "13d", "label": "d.", "prompt": "Sie machte Lorenz sein bestes Angebot, das aus den drei Münzen bestand, die sie bei sich trug.", "modelAnswer": "ihr", "correctAnswer": "sein"}, {"id": "13e", "label": "e.", "prompt": "Die Mutter notierte sich Lorenz‘ Handynummer und versprach, ihm anzurufen, wenn Jennifer bereit sei.", "modelAnswer": "ihn", "correctAnswer": "ihm"}]}, {"id": "german25-14", "type": "text-area", "number": 14, "prompt": "Stelle die folgenden Sätze wie im Beispiel dar und gib zu den einzelnen Wortgruppen jeweils die passende Frage an.", "context": "Beispiel: Am Anfang zerrt Cougar heftig an der Leine.\nAm Anfang wann?\nCougar wer?\nheftig wie?\nan der Leine woran?", "subTasks": [{"id": "14a1", "label": "Der Kleinen", "prompt": "", "modelAnswer": "wem?"}, {"id": "14a2", "label": "heute", "prompt": "", "modelAnswer": "wann?"}, {"id": "14a3", "label": "unverhofft", "prompt": "", "modelAnswer": "wie?"}, {"id": "14a4", "label": "Cougar", "prompt": "", "modelAnswer": "wer?"}, {"id": "14b1", "label": "Später", "prompt": "", "modelAnswer": "wann?"}, {"id": "14b2", "label": "Lorenz", "prompt": "", "modelAnswer": "wer?"}, {"id": "14b3", "label": "lächelnd", "prompt": "", "modelAnswer": "wie?"}, {"id": "14b4", "label": "über die Geschichte", "prompt": "", "modelAnswer": "worüber?"}, {"id": "14c1", "label": "er", "prompt": "", "modelAnswer": "wer?"}, {"id": "14c2", "label": "Cougar", "prompt": "", "modelAnswer": "wen?"}, {"id": "14c3", "label": "Jennifer", "prompt": "", "modelAnswer": "wem?"}, {"id": "14c4", "label": "darum", "prompt": "", "modelAnswer": "warum?"}]}]}', '{"Lorenz hatte Ohrstöpsel an und hörte Musik. Ein sehnsüchtiges Lied, das ihn an daheim erinnerte.","In seiner Hand hielt Lorenz eine Leine. An der Leine zog ein Hund. Sein Hund. Ein lieber Hund,","ein netter Hund, aber nur ein Hund. Wenn jemand alleine ist, dann bleibt einem nur der Hund","als treuer Freund. Lorenz war froh, dass seine Eltern ihm nach seinem Umzug hierher den","Labrador gekauft hatten. Er nahm den Kopfhörer ab, denn vor ihm stand ein kleines Mädchen.","„Oh, wie süss! Das ist ja ein lieber Hund!“, schwärmte das Kind und umarmte das verdutzte","Tier. Lorenz schaute erstaunt und fasziniert zu, wie sich sein sonst eher misstrauischer Hund","streicheln liess.","„Das ist Cougar“, sagte Lorenz.","Sie löste sich wieder von Cougar und blickte den Hund sehnsüchtig aus rehbraunen Augen an:","„Ich möchte so gerne auch einen Hund haben“, seufzte sie. „Genau so einen wie den da.","Wie lieb er mich anschaut!“ Das Mädchen schaute Lorenz mit ihren grossen Augen bittend,","beinahe flehend an. Lorenz lächelte etwas unsicher und meinte: „Kauf dir halt auch einen!“","„Ich will aber genau den da“, sagte das Mädchen und deutete auf Cougar. „Darf ich ihn dir","abkaufen?“ Sie lächelte Lorenz erwartungsvoll an. Gleichzeitig nahm sie Cougar in die Arme","und auch er begann mit seinen unschuldigen Hundeaugen Lorenz anzustarren. Ganz so, als","wollte er ebenso sagen: „Bitte, bitte, verkauf mich an das Mädchen!“ Lorenz musterte seinen","Hund etwas enttäuscht. Sicher, er hatte ihn nicht immer so gut behandelt, war nicht immer","Gassi gegangen, hatte ihn nicht immer rechtzeitig gefüttert. Aber war das ein Grund, dass","er sich nun mit dem erstbesten Mädchen gegen ihn verschwor? Lorenz fuhr Cougar behutsam","durch das Fell: „Tut mir leid, aber eigentlich will ich ihn behalten.“ „Warum heisst er Cougar?","Und was bedeutet überhaupt Cougar?“, fragte das Mädchen.","„Cougar ist Englisch und bedeutet in unserer Sprache Puma“, antwortete Lorenz. „Das sind","diese goldfarbenen Berglöwen.“ Sie lachte. „Das ist lustig! Denn es passt, aber auch nicht.","Das wäre, wie wenn unsere graue Nachbarskatze Wolfi hiesse. Cougar, ich hab dich lieb.“","Sie gab dem Hund einen zarten Kuss auf das dunkelblonde Fell. Das Mädchen griff in seine","Tasche und zog drei Münzen heraus: „Mehr hab ich nicht“, murmelte es kleinlaut. Hund und","Mädchen starrten Lorenz beinahe beschwörend an.","„Ach, Cougar“, seufzte Lorenz betroffen, „willst du mich denn wirklich loswerden?“ Das Mädchen","drückte ihm das Geld in die Hand und begann zu betteln: „Bitte, bitte, verkaufe mir dein","süsses, liebes, braves Hundilein.“ Inzwischen war die Mutter des Mädchens aus ihrem Haus","nach draussen gekommen und beobachtete schmunzelnd das Feilschen. Das Mädchen","klammerte sich verliebt an Cougar. Cougar begann winselnd zu jaulen. Und Lorenz versuchte,","dem Mädchen die Münzen zurückzugeben. Jetzt griff die Mutter ein: „Jennifer! Du kannst dem","jungen Mann doch nicht den Hund abkaufen. Der hat ihn doch auch lieb“, worauf Lorenz","hilflos nickte. Jennifer wollte von Cougar nicht ablassen. „Bitte, Mami. Bitte, lass mich den","Hund behalten. Der Hund hat mich viel lieber als ihn. Nicht wahr, Cougar?“ Cougar bellte drei","Mal laut, als wollte er unbedingt zustimmen. Lorenz fühlte sich hundselend, denn die Vorstellung,","dass er seinen einzigen Freund in der fremden Stadt verlor, schnürte ihm die Kehle zu. Die","Mutter kniete sich zu ihrer Tochter hinab und streichelte ihr durchs Haar: „Nicht traurig sein,","Jenny. Zum Geburtstag darfst du dir einen Hund wünschen, dann bist du alt genug. Jetzt","bedank dich bei dem Mann, dass du mit dem Hund spielen durftest. Aber er muss jetzt","bestimmt nach Hause.“ Lorenz atmete erleichtert auf: „Vielen Dank“, sagte er zu der Frau.","Endlich löste sich Jenny von Cougar: „Tschüss, lieber Cougar. Ich hoffe, wir sehen uns bald","wieder.“ Sie wandte sich an Lorenz: „Vielleicht darf ich mit euch spazieren gehen?“ Lorenz","nickte: „Wenn du magst, klingle ich morgen bei dir.“ Die Mutter nickte Lorenz zu und","verabschiedete sich. Dann ging sie zurück ins Haus. Als Lorenz sich nach einigen Metern","noch einmal umdrehte, stand Jennifer noch immer an der Strasse. Sie winkte beiden zu.","Lorenz steckte sich wieder die Kopfhörerstöpsel in die Ohren und ging weiter: Als nächstes","Lied wählte er eines, das zum fröhlichen Tanzen einlud."}', '2026-02-22 22:49:48.146258+00', '2026-02-22 22:49:48.146258+00'),
	('math-2022-gemini', 'Zentrale Aufnahmeprüfung 2022 Mathematik', 'Math', 2022, 'Gemini 3 Pro', '{"meta": {"time": "60 Minuten", "hints": ["Taschenrechner sind nicht erlaubt.", "Löse die Aufgaben direkt auf dem Blatt.", "Ergebnisse müssen deutlich gekennzeichnet und mit Masseinheit versehen sein."], "maxPoints": 36}, "questions": [{"id": "zap-22-1", "type": "input", "number": 1, "prompt": "Gib das Ergebnis an.", "context": "Tipp: Wenn du geschickt rechnest, kannst du den Rechenaufwand stark verringern.", "subTasks": [{"id": "zap-22-1a", "label": "Ergebnis", "prompt": "$$(12.32 \\cdot 56) - 100.8 + (19 \\cdot 4.2) + (56 \\cdot 7.68)$$", "modelAnswer": "Zusammenfassen der Terme mit Faktor 56: 56 * (12.32 + 7.68) = 56 * 20 = 1120. \nRest: -100.8 + (19 * 4.2). \n19 * 4.2 = (20 - 1) * 4.2 = 84 - 4.2 = 79.8. \n1120 - 100.8 + 79.8 = 1120 - 21 = 1099.", "correctAnswer": 1099}]}, {"id": "zap-22-2", "type": "input", "number": 2, "prompt": "Klima-Tabelle Juli.", "context": "Der Monat Juli hat 31 Tage. Hitzetage und Regentage sind immer verschiedene Tage (sie fallen nie auf denselben Tag).\n\n**Daten aus der Tabelle:**\n* **Juli 2014:** 20 Regentage, $17.5^\\circ\\text{C}$ Durchschnitt.\n* **Juli 2015:** 0 Regentage (gemäss OCR/Kontext) oder fehlender Wert, 9 Regentage, $17.6^\\circ\\text{C}$ Durchschnitt.\n* **Juli 2021:** 20 Regentage, 0 Tropennächte.\n\n*(Hinweis: Die fehlenden Werte in der Tabelle erschliessen sich aus den Aufgabenstellungen)*", "subTasks": [{"id": "zap-22-2a", "label": "a)", "prompt": "Die Anzahl Hitzetage im Juli 2014 beträgt $\\frac{1}{8}$ der Hitzetage im Juli 2015. Wie viele Hitzetage gab es im Juli 2014? (Hinweis: Bestimme erst aus der Tabelle, wie viele Hitzetage 2015 plausibel sind oder nutze die Lösung rückwärts: 2015 hatte 16 Hitzetage).", "suffix": "Tage", "modelAnswer": "2015 hatte 16 Hitzetage. 1/8 von 16 = 2.", "correctAnswer": 2}, {"id": "zap-22-2b", "label": "b)", "prompt": "Wie viele Tage im Juli der drei Jahre 2014, 2015 und 2021 waren insgesamt weder Hitzetage noch Regentage?", "suffix": "Tage", "modelAnswer": "2014: 31 - (2 Hitze + 20 Regen) = 9.\n2015: 31 - (16 Hitze + 9 Regen) = 6.\n2021: 31 - (0 Hitze + 20 Regen) = 11.\nTotal: 9 + 6 + 11 = 26.", "correctAnswer": 26}, {"id": "zap-22-2c", "label": "c)", "prompt": "Der Mittelwert der drei Durchschnittstemperaturen beträgt $19.1^\\circ\\text{C}$. Wie viele Grad Celsius beträgt die Durchschnittstemperatur im Juli 2015?", "suffix": "°C", "modelAnswer": "Summe = 19.1 * 3 = 57.3. Gesucht = 57.3 - 17.5 - 17.6 = 22.2.", "correctAnswer": 22.2}]}, {"id": "zap-22-3", "type": "input", "number": 3, "prompt": "Die abgebildete Burg ist aus Würfeln von 1 cm Kantenlänge zusammengeklebt. Nur auf der Vorderseite hat es eine Tür und ein Fenster.", "imageUrl": "/images/math-2022/gemini/task-3.png", "subTasks": [{"id": "zap-22-3a", "label": "a)", "prompt": "Aus wie vielen Würfeln besteht die Burg?", "suffix": "Würfel", "correctAnswer": 69}, {"id": "zap-22-3b", "label": "b)", "prompt": "Wie viele Würfel der Burg berühren den Boden?", "suffix": "Würfel", "correctAnswer": 15}, {"id": "zap-22-3c", "label": "c)", "prompt": "Wie viele Würfel braucht es zusätzlich, um aus der Burg einen vollständig gefüllten Würfel mit 5 cm Seitenlänge zu erhalten?", "suffix": "Würfel", "modelAnswer": "5^3 = 125. 125 - 69 = 56.", "correctAnswer": 56}]}, {"id": "zap-22-4", "type": "input", "number": 4, "prompt": "Brezel-Aufgabe.", "context": "In der Zehnuhrpause liegen Brezel bereit.\n* $\\frac{3}{5}$ der Brezel sind mit Butter bestrichen, die restlichen nicht.\n* Nur von den Butterbrezeln werden $\\frac{3}{7}$ gegessen.\n* Es bleiben 12 Butterbrezel übrig.", "subTasks": [{"id": "zap-22-4a", "label": "Ergebnis", "prompt": "Wie viele Brezel lagen insgesamt zu Beginn der Pause bereit?", "suffix": "Brezel", "modelAnswer": "4/7 der Butterbrezeln bleiben übrig = 12 Stück. Total Butter = 12 / 4 * 7 = 21. Total Brezel = 21 / 3 * 5 = 35.", "correctAnswer": 35}]}, {"id": "zap-22-5", "type": "input", "number": 5, "prompt": "Geschwindigkeit von Daria.", "context": "Gabriela und Daria laufen um 8:00 Uhr mit $6\\text{ km/h}$ los. Nach 3 Minuten kehrt Daria um, rennt nach Hause und dann zur Station. Gabriela läuft weiter und kommt um 8:15 Uhr an. Daria kommt gleichzeitig (8:15 Uhr) an.", "subTasks": [{"id": "zap-22-5a", "label": "Ergebnis", "prompt": "Mit welcher durchschnittlichen Geschwindigkeit war Daria **seit ihrer Umkehr** unterwegs?", "suffix": "km/h", "modelAnswer": "Weg zur Station = 15 min * 6 km/h = 1.5 km. Daria nach 3 min: 0.3 km vom Start. Weg zurück: 0.3 km + 1.5 km = 1.8 km. Zeit: 8:03 bis 8:15 = 12 min = 0.2 h. v = 1.8 / 0.2 = 9 km/h.", "correctAnswer": 9}]}, {"id": "zap-22-6", "type": "input", "number": 6, "prompt": "Zahlenstrahl und Abstände.", "imageUrl": "/images/math-2022/gemini/task-6.png", "subTasks": [{"id": "zap-22-6a", "label": "a)", "prompt": "Bestimme die Zahl, die genau in der Mitte von A und B liegt (siehe Bild). Der Zahlenstrahl geht von 5.9 bis 6 mit 10 Abschnitten.", "modelAnswer": "Schrittweite = 0.01. A = 5.93, B = 5.98. Mitte = (5.93+5.98)/2 = 5.955.", "correctAnswer": 5.955}, {"id": "zap-22-6b", "label": "b)", "prompt": "Gegeben sind $C=4.8$ und $D=5.1$. Welche Zahl liegt dreimal so weit von C entfernt wie von D (zwischen C und D)?", "modelAnswer": "Abstand CD = 0.3. Teilung 3:1 bedeutet 4 Teile. 0.3 / 4 = 0.075. Zahl liegt bei D - 0.075 = 5.025.", "correctAnswer": 5.025}]}, {"id": "zap-22-7", "type": "input", "number": 7, "prompt": "Pakete schnüren.", "context": "Die Schnur verläuft wie in der Skizze: Einmal längs (über Boden und Deckel), einmal quer, und an allen vier vertikalen Kanten.", "imageUrl": "/images/math-2022/gemini/task-7.png", "subTasks": [{"id": "zap-22-7a", "label": "a)", "prompt": "Maxim: $A=15\\text{ cm}$, $B=25\\text{ cm}$, $C=6\\text{ cm}$. Gesamtschnur = 160 cm. Wie viel cm bleiben für die Masche?", "suffix": "cm", "modelAnswer": "Benötigt: 2*A + 2*B + 4*C = 30 + 50 + 24 = 104. Rest: 160 - 104 = 56.", "correctAnswer": 56}, {"id": "zap-22-7b", "label": "b)", "prompt": "Noah: $A=20\\text{ cm}$, $B=30\\text{ cm}$, Volumen = $3\\text{ dm}^3$. Wie lang ist C?", "suffix": "cm", "modelAnswer": "3 dm^3 = 3000 cm^3. 20 * 30 * C = 3000. 600 * C = 3000 => C = 5.", "correctAnswer": 5}]}, {"id": "zap-22-8", "type": "input", "number": 8, "prompt": "Badewanne.", "context": "Wanne fasst 150 Liter. Nach 20 Minuten ist sie zu $\\frac{2}{3}$ gefüllt (Abfluss war offen). Nach Schliessen des Abflusses ist sie 2 Minuten später voll.", "subTasks": [{"id": "zap-22-8a", "label": "Ergebnis", "prompt": "Wie viele Liter Wasser sind in den ersten 20 Minuten unnötigerweise abgeflossen?", "suffix": "Liter", "modelAnswer": "In 2 Min füllt sich der Rest (1/3 von 150 = 50L). Zufluss = 25 L/min. In 20 Min flossen 20 * 25 = 500L ein. In der Wanne sind nur 100L. Verlust = 400L.", "correctAnswer": 400}]}]}', NULL, '2026-02-22 22:49:48.200373+00', '2026-02-22 22:49:48.200373+00'),
	('math-2022-gpt5', 'Zentrale Aufnahmeprüfung 2022 – Mathematik', 'Math', 2022, 'GPT-5.2 Thinking', '{"meta": {"time": "60 Minuten", "hints": ["Du hast 60 Minuten Zeit.", "Du musst Ausrechnungen und Zwischenresultate notieren; sonst gibt es keine Punkte.", "Antwortsätze sind nicht verlangt; Ergebnisse sollen deutlich markiert und mit passender Masseinheit notiert werden.", "Kein Taschenrechner und keine elektronischen Hilfsmittel."], "maxPoints": 36}, "questions": [{"id": "zap22-m-1", "type": "input", "number": 1, "prompt": "Gib das Ergebnis an: $(12.32 \\cdot 56) - 100.8 + (19 \\cdot 4.2) + (56 \\cdot 7.68)$", "context": "Rechne möglichst geschickt, indem du Terme zusammenfasst (z. B. gemeinsame Faktoren).", "subTasks": [{"id": "zap22-m-1-r", "label": "Ergebnis", "prompt": "Berechne den Wert des Terms.", "correctAnswer": 1099}]}, {"id": "zap22-m-2", "type": "input", "number": 2, "prompt": "Klima (Juli hat 31 Tage)", "context": "In einer Tabelle zum Kanton Zürich (Juli 2014, 2015, 2021) stehen u. a. Hitzetage, Regentage, Tropennächte und Durchschnittstemperaturen. Hitzetage und Regentage sind jeweils verschiedene Tage. Gegeben: Hitzetage 2015 = 16, 2021 = 0; Regentage 2014 = 20, 2015 = 9, 2021 = 20; Tropennächte 2014 = 0, 2015 = 5, 2021 = 0; durchschnittliche Temperatur 2014 = 17.5°C und 2021 = 17.6°C.", "subTasks": [{"id": "zap22-m-2-a", "label": "a)", "prompt": "Die Anzahl Hitzetage im Juli 2014 beträgt $\\frac{1}{8}$ der Hitzetage im Juli 2015. Wie viele Hitzetage gab es im Juli 2014?", "suffix": "Tage", "correctAnswer": 2}, {"id": "zap22-m-2-b", "label": "b)", "prompt": "Wie viele Tage im Juli der drei Jahre 2014, 2015 und 2021 waren insgesamt weder Hitzetage noch Regentage?", "suffix": "Tage", "correctAnswer": 26}, {"id": "zap22-m-2-c", "label": "c)", "prompt": "Der Mittelwert der drei Durchschnittstemperaturen beträgt 19.1°C. Wie viele Grad Celsius beträgt die Durchschnittstemperatur im Juli 2015?", "suffix": "°C", "correctAnswer": 22.2}]}, {"id": "zap22-m-3", "type": "input", "number": 3, "prompt": "Die nebenstehende Burg ist aus Würfeln von 1 cm Kantenlänge zusammengeklebt. Nur auf der Vorderseite hat es eine Tür und ein Fenster.", "context": "Gegeben ist ein 3D-Block («Burg») aus Einheitswürfeln (1 cm Kantenlänge). Oben sind mehrere Würfel so angeordnet, dass ein offener Innenhof entsteht. Auf der Vorderseite fehlen Würfel in Form einer Türöffnung unten und eines Fensters in der Mitte.", "imageUrl": "/images/math-2022/gpt-5-2-thinking/task-3.png", "subTasks": [{"id": "zap22-m-3-a", "label": "a)", "prompt": "Aus wie vielen Würfeln besteht die Burg?", "suffix": "Würfel", "correctAnswer": 69}, {"id": "zap22-m-3-b", "label": "b)", "prompt": "Wie viele Würfel der Burg berühren den Boden?", "suffix": "Würfel", "correctAnswer": 15}, {"id": "zap22-m-3-c", "label": "c)", "prompt": "Wie viele Würfel braucht es zusätzlich, um aus der Burg einen vollständig gefüllten Würfel mit 5 cm Seitenlänge zu erhalten?", "suffix": "Würfel", "correctAnswer": 56}]}, {"id": "zap22-m-4", "type": "input", "number": 4, "prompt": "In der Zehnuhrpause liegen Brezel bereit.", "context": "Von allen Brezeln sind $\\frac{3}{5}$ mit Butter bestrichen, die restlichen ohne Butter. Von den Butterbrezeln werden $\\frac{3}{7}$ gegessen. Danach bleiben 12 Butterbrezeln übrig.", "subTasks": [{"id": "zap22-m-4-r", "label": "Ergebnis", "prompt": "Wie viele Brezel lagen insgesamt zu Beginn der Pause bereit?", "suffix": "Brezel", "correctAnswer": 35}]}, {"id": "zap22-m-5", "type": "input", "number": 5, "prompt": "Gabriela und Daria laufen zur Tramstation.", "context": "Beide starten um 8.00 Uhr und laufen zuerst gemeinsam mit 6 km/h. Nach 3 Minuten kehrt Daria um (zurück nach Hause), während Gabriela mit 6 km/h weiterläuft und die Tramstation um 8.15 Uhr erreicht. Daria trifft gleichzeitig bei der Tramstation ein.", "subTasks": [{"id": "zap22-m-5-r", "label": "Ergebnis", "prompt": "Mit welcher durchschnittlichen Geschwindigkeit war Daria seit ihrer Umkehr unterwegs? Gib das Resultat in km/h an.", "suffix": "km/h", "correctAnswer": 9}]}, {"id": "zap22-m-6", "type": "input", "number": 6, "prompt": "Zahlen auf dem Zahlenstrahl", "context": "a) Auf einem Zahlenstrahl zwischen 5.9 und 6.0 sind zwei Zahlen A und B markiert. Der Abschnitt ist in 10 gleich grosse Teile unterteilt (Schrittweite 0.01). A liegt bei 5.93 und B bei 5.98. Gesucht sind A, B sowie die Zahl genau in der Mitte.\n\nb) Auf einem zweiten Zahlenstrahl sind $C = 4.8$ und $D = 5.1$ markiert. Gesucht ist eine Zahl, die dreimal so weit von C entfernt ist wie von D.", "imageUrl": "/images/math-2022/gpt-5-2-thinking/task-6.png", "subTasks": [{"id": "zap22-m-6-a-A", "label": "a) A", "prompt": "Bestimme A.", "correctAnswer": 5.93}, {"id": "zap22-m-6-a-B", "label": "a) B", "prompt": "Bestimme B.", "correctAnswer": 5.98}, {"id": "zap22-m-6-a-M", "label": "a) Mitte", "prompt": "Welche Zahl liegt genau in der Mitte von A und B?", "correctAnswer": 5.955}, {"id": "zap22-m-6-b", "label": "b)", "prompt": "Welche Zahl liegt dreimal so weit von C entfernt wie von D?", "correctAnswer": 5.025}]}, {"id": "zap22-m-7", "type": "input", "number": 7, "prompt": "Paket mit Schnur", "context": "Ein quaderförmiges Paket hat Grundkanten A und B sowie Höhe C. Eine Schnur ist wie zwei Schlaufen um das Paket gebunden: einmal um den Querschnitt mit A und C und einmal um den Querschnitt mit B und C. Oben bleibt zusätzlich Schnur für die Masche.", "imageUrl": "/images/math-2022/gpt-5-2-thinking/task-7.png", "subTasks": [{"id": "zap22-m-7-a", "label": "a)", "prompt": "Bei Maxims Paket ist $A = 15$ cm, $B = 25$ cm und $C = 6$ cm. Die Schnur ist 160 cm lang. Wie viele Zentimeter der Schnur blieben für die Masche übrig?", "suffix": "cm", "correctAnswer": 56}, {"id": "zap22-m-7-b", "label": "b)", "prompt": "Bei Noahs Paket ist $A = 20$ cm und $B = 30$ cm und das Paket hat ein Volumen von 3 dm$^3$. Wie lang ist $C$?", "suffix": "cm", "correctAnswer": 5}]}, {"id": "zap22-m-8", "type": "input", "number": 8, "prompt": "Badewanne mit offenem Abfluss", "context": "Die Badewanne fasst 150 l. Während der ersten 20 Minuten läuft Wasser ein, aber gleichzeitig läuft wegen eines nicht richtig verschlossenen Abflusses Wasser ab. Nach 20 Minuten ist die Wanne erst zu $\\frac{2}{3}$ gefüllt. Danach wird der Abfluss geschlossen; 2 Minuten später ist die Wanne voll.", "subTasks": [{"id": "zap22-m-8-r", "label": "Ergebnis", "prompt": "Wie viele Liter Wasser sind in den ersten 20 Minuten unnötigerweise abgeflossen?", "suffix": "l", "correctAnswer": 400}]}]}', NULL, '2026-02-22 22:49:48.378685+00', '2026-02-22 22:49:48.378685+00'),
	('math-2022-qwen', 'Mathematik 2022 (Langgymnasium)', 'Math', 2022, 'Qwen 3 Max', '{"meta": {"time": "60 Minuten", "hints": ["Löse die Aufgaben direkt auf das Aufgabenblatt.", "Du musst Ausrechnungen und Zwischenresultate aufschreiben, damit der Lösungsweg verständlich ist.", "Antwortsätze sind nicht verlangt. Kennzeichne aber die Ergebnisse deutlich und notiere sie mit der passenden Masseinheit.", "Du darfst keinen Taschenrechner verwenden.", "Jede Aufgabe zählt 4 Punkte."], "maxPoints": 36}, "questions": [{"id": "m22-1", "type": "input", "number": 1, "prompt": "Gib das Ergebnis an: $(12.32 \\cdot 56) - 100.8 + (19 \\cdot 4.2) + (56 \\cdot 7.68)$", "context": "Wenn du geschickt rechnest, kannst du den Rechenaufwand stark verringern.", "subTasks": [{"id": "m22-1-a", "label": "Ergebnis:", "prompt": "", "suffix": "", "correctAnswer": 1099}]}, {"id": "m22-2", "type": "input", "number": 2, "prompt": "Klima: Der Monat Juli hat 31 Tage. In der folgenden Tabelle sind Hitzetage und Regentage immer verschiedene Tage.", "context": "Gegeben:\n- Juli 2014: Hitzetage = ?, Regentage = 20\n- Juli 2015: Hitzetage = 16 (8× so viele wie 2014), Regentage = 9\n- Juli 2021: Hitzetage = 0, Regentage = 20\n\na) Wie viele Hitzetage gab es im Juli 2014?\nb) Wie viele Tage in den drei Jahren waren weder Hitzetage noch Regentage?\nc) Mittelwert der Durchschnittstemperaturen der drei Jahre = 19.1 °C. Gegeben: 2014 → 17.5 °C, 2021 → 17.6 °C. Gesucht: Durchschnittstemperatur 2015.", "subTasks": [{"id": "m22-2-a", "label": "Hitzetage 2014:", "prompt": "Anzahl Hitzetage im Juli 2014", "suffix": "d", "correctAnswer": 2}, {"id": "m22-2-b", "label": "Tage ohne Hitze/Regen:", "prompt": "Tage, die weder Hitzetage noch Regentage waren (über alle 3 Jahre)", "suffix": "d", "correctAnswer": 26}, {"id": "m22-2-c", "label": "Temp. 2015:", "prompt": "Durchschnittstemperatur im Juli 2015", "suffix": "°C", "correctAnswer": 22.2}]}, {"id": "m22-3", "type": "input", "number": 3, "prompt": "Die nebenstehende Burg ist aus Würfeln von 1 cm Kantenlänge zusammengeklebt.", "context": "a) Aus wie vielen Würfeln besteht die Burg?\nb) Wie viele Würfel berühren den Boden?\nc) Wie viele Würfel braucht es zusätzlich, um aus der Burg einen vollständig gefüllten Würfel mit 5 cm Seitenlänge zu erhalten?", "imageUrl": "/images/math-2022/qwen/task-3.png", "subTasks": [{"id": "m22-3-a", "label": "Gesamtwürfel:", "prompt": "Gesamtanzahl Würfel in der Burg", "suffix": "", "correctAnswer": 69}, {"id": "m22-3-b", "label": "Bodenwürfel:", "prompt": "Anzahl Würfel, die den Boden berühren", "suffix": "", "correctAnswer": 15}, {"id": "m22-3-c", "label": "Zusatzwürfel:", "prompt": "Zusätzliche Würfel für 5 cm³-Würfel", "suffix": "", "correctAnswer": 56}]}, {"id": "m22-4", "type": "input", "number": 4, "prompt": "In der Zehnuhrpause liegen Brezel bereit. $\\frac{3}{5}$ der Brezel sind mit Butter bestrichen, die restlichen nicht. Nur $\\frac{3}{7}$ der Butterbrezel werden gegessen. Daher bleiben 12 Butterbrezel übrig. Wie viele Brezel lagen insgesamt zu Beginn der Pause bereit?", "context": "", "subTasks": [{"id": "m22-4-a", "label": "Gesamtbrezel:", "prompt": "Gesamtanzahl Brezel zu Beginn", "suffix": "", "correctAnswer": 35}]}, {"id": "m22-5", "type": "input", "number": 5, "prompt": "Gabriela und Daria laufen um 8:00 Uhr mit 6 km/h zur Tramstation. Nach 3 Minuten bemerkt Daria, dass sie ihr Portemonnaie vergessen hat, rennt zurück, holt es und trifft gleichzeitig mit Gabriela um 8:15 Uhr an der Tramstation ein. Mit welcher durchschnittlichen Geschwindigkeit war Daria seit ihrer Umkehr unterwegs?", "context": "Gabriela läuft durchgehend mit 6 km/h und benötigt 15 Minuten → Strecke = 1.5 km.", "subTasks": [{"id": "m22-5-a", "label": "Darias Geschwindigkeit:", "prompt": "Durchschnittsgeschwindigkeit von Daria nach der Umkehr", "suffix": "km/h", "correctAnswer": 9}]}, {"id": "m22-6", "type": "input", "number": 6, "prompt": "a) Auf dem Zahlenstrahl sind zwei Zahlen A und B markiert zwischen 5.9 und 6. Bestimme A, B und die Zahl genau in der Mitte.\nb) Gegeben: $C = 4.8$, $D = 5.1$. Welche Zahl liegt dreimal so weit von C entfernt wie von D?", "context": "a) Der Abstand zwischen 5.9 und 6 ist in 10 gleich lange Abschnitte geteilt.\nb) Lösung über Gleichung oder grafische Überlegung.", "subTasks": [{"id": "m22-6-a", "label": "Mitte A–B:", "prompt": "Zahl genau in der Mitte zwischen A und B", "suffix": "", "correctAnswer": 5.955}, {"id": "m22-6-b", "label": "Dreifach-Abstand:", "prompt": "Zahl, die dreimal so weit von C wie von D entfernt ist", "suffix": "", "correctAnswer": 5.025}]}, {"id": "m22-7", "type": "input", "number": 7, "prompt": "Pakete sind mit Schnur gebunden. Die Schnur verläuft zweimal um die Breite (A), zweimal um die Länge (B) und viermal um die Höhe (C).", "context": "a) A = 15 cm, B = 25 cm, C = 6 cm, Schnurlänge = 160 cm → Rest für Masche?\nb) A = 20 cm, B = 30 cm, Volumen = 3 dm³ → C = ?", "subTasks": [{"id": "m22-7-a", "label": "Schnur-Masche:", "prompt": "Restlänge der Schnur für die Masche", "suffix": "cm", "correctAnswer": 56}, {"id": "m22-7-b", "label": "Höhe C:", "prompt": "Höhe C des Pakets", "suffix": "cm", "correctAnswer": 5}]}, {"id": "m22-8", "type": "input", "number": 8, "prompt": "Eine 150 l-Badewanne wird 20 Minuten lang mit offenem Abfluss befüllt und ist dann zu $\\frac{2}{3}$ gefüllt. Danach wird der Abfluss geschlossen und nach weiteren 2 Minuten ist die Wanne voll. Wie viele Liter sind in den ersten 20 Minuten unnötigerweise abgeflossen?", "context": "Gesamtzuflussrate und Abflussrate ergeben effektiven Füllstand.", "subTasks": [{"id": "m22-8-a", "label": "Abgelaufenes Wasser:", "prompt": "Menge Wasser, die in 20 Minuten abfloss", "suffix": "l", "correctAnswer": 400}]}, {"id": "m22-9", "type": "text-area", "number": 9, "prompt": "Gegeben ist ein Quadrat ABCD mit einer dick markierten Linie. Führe folgende Transformationen durch (jeweils vom Original ausgehend):", "context": "a) Drehung um 90° im Uhrzeigersinn.\nb) Spiegelung an der Seite CD.\nc) Ergänze mit möglichst wenigen Linien, sodass die Figur sowohl AC als auch BD als Symmetrieachsen hat.", "imageUrl": "/images/math-2022/qwen/task-9.png", "subTasks": [{"id": "m22-9-a", "label": "a)", "prompt": "Zeichne die gedrehte Linie nach 90°-Drehung im Uhrzeigersinn.", "modelAnswer": "Linie verläuft nun von neuer Position A'' zu B'' entsprechend Drehung"}, {"id": "m22-9-b", "label": "b)", "prompt": "Zeichne die gespiegelte Linie an Seite CD.", "modelAnswer": "Linie gespiegelt unterhalb der Grundseite CD"}, {"id": "m22-9-c", "label": "c)", "prompt": "Ergänze die Figur, sodass sie bezüglich beider Diagonalen symmetrisch ist.", "modelAnswer": "Linie wird zu einem vollständigen X oder vollständig symmetrischem Muster ergänzt"}]}]}', NULL, '2026-02-22 22:49:48.41943+00', '2026-02-22 22:49:48.41943+00'),
	('math-2023-gemini', 'Zentrale Aufnahmeprüfung 2023 Mathematik', 'Math', 2023, 'Gemini 3 Pro', '{"meta": {"time": "60 Minuten", "hints": ["Taschenrechner sind nicht erlaubt.", "Löse die Aufgaben direkt auf das Blatt.", "Zwischenresultate und Lösungswege müssen ersichtlich sein."], "maxPoints": 36}, "questions": [{"id": "zap-23-1", "type": "input", "number": 1, "prompt": "Bestimme die fehlende Zahl im Kästchen.", "subTasks": [{"id": "zap-23-1a", "label": "a)", "prompt": "$$2 \\cdot \\Box \\text{ kg} + 536 \\text{ kg} = 1.24 \\text{ t}$$", "suffix": "kg", "modelAnswer": "1.24 t = 1240 kg. 1240 - 536 = 704. 704 : 2 = 352.", "correctAnswer": 352}, {"id": "zap-23-1b", "label": "b)", "prompt": "$$(\\frac{5}{9} \\text{ von } 2\\text{h } 33 \\text{ min}) - \\Box \\text{ min} = \\frac{3}{5}\\text{h}$$", "suffix": "min", "modelAnswer": "2h 33min = 153 min. 5/9 von 153 = 85 min. 3/5 h = 36 min. 85 - x = 36 -> x = 49.", "correctAnswer": 49}]}, {"id": "zap-23-2", "type": "input", "number": 2, "prompt": "Reisedistanzen und -zeiten.", "context": "Die Tabelle zeigt Distanzen und Zeiten:\n* **Luftlinie**: Zürich-Paris 488 km, Zürich-Brüssel 493 km\n* **Flugzeug**: Zürich-Paris 490 km (1h 15min), Zürich-Brüssel 500 km (1h 15min)\n* **Zug**: Zürich-Paris 4h 10min (575 km), Zürich-Brüssel 6h 50min (848 km)\n* **Auto**: Zürich-Paris 640 km (6h 40min), Zürich-Brüssel 632 km (7h 15min)", "subTasks": [{"id": "zap-23-2a", "label": "a)", "prompt": "Der schnellste Weg mit dem Zug von Zürich nach Brüssel führt über Paris. Wie weit ist demnach die Distanz von Paris nach Brüssel mit dem Zug?", "suffix": "km", "modelAnswer": "Total 848 km - Zürich-Paris 575 km = 273 km.", "correctAnswer": 273}, {"id": "zap-23-2b", "label": "b)", "prompt": "Wie viele km/h beträgt die Durchschnittsgeschwindigkeit eines Fluges von Zürich nach Brüssel?", "suffix": "km/h", "modelAnswer": "500 km in 1.25 h (75 min). 500 / 1.25 = 400 km/h.", "correctAnswer": 400}, {"id": "zap-23-2c", "label": "c)", "prompt": "Wie viele Minuten könnte ein Auto auf der Fahrt von Zürich nach Brüssel einsparen, wenn es gleich schnell fahren könnte wie ein Auto auf der Fahrt von Zürich nach Paris?", "suffix": "min", "modelAnswer": "Auto Z-P: 640 km in 400 min -> 1.6 km/min. Z-B: 632 km / 1.6 = 395 min. Tatsächlich: 435 min. 435 - 395 = 40 min.", "correctAnswer": 40}]}, {"id": "zap-23-3", "type": "input", "number": 3, "prompt": "Bruchteile von Flächen.", "imageUrl": "/images/math-2023/gemini/task-3-a.png", "subTasks": [{"id": "zap-23-3a-A", "label": "a) Figur A", "prompt": "Welchem Bruchteil des Rechtecks entspricht der graue Teil A? (Gekürzter Bruch)", "modelAnswer": "8 graue Häuschen von total 30. 8/30 = 4/15.", "correctAnswer": "4/15"}, {"id": "zap-23-3a-B", "label": "a) Figur B", "prompt": "Welchem Bruchteil des Rechtecks entspricht der graue Teil B? (Gekürzter Bruch)", "modelAnswer": "15 graue (halbe/ganze verrechnet) von 30. 1/2.", "correctAnswer": "1/2"}, {"id": "zap-23-3b", "label": "b)", "prompt": "Das gezeichnete Teilstück (12 Häuschen) soll 3/5 eines Rechtecks ausmachen. Aus wie vielen Häuschen besteht das ganze Rechteck?", "suffix": "Häuschen", "imageUrl": "/images/math-2023/gemini/task-3-b.png", "modelAnswer": "12 Häuschen = 3/5. 1/5 = 4 Häuschen. 5/5 = 20 Häuschen.", "correctAnswer": 20}]}, {"id": "zap-23-4", "type": "multiple-choice", "number": 4, "prompt": "Sind die folgenden Aussagen richtig oder falsch? (Ohne Ausrechnung zu entscheiden).", "subTasks": [{"id": "zap-23-4-1", "label": "1.", "prompt": "$$1 = 100 \\cdot 568.1 - 10 \\cdot 568.1$$", "options": ["richtig", "falsch"], "correctAnswer": "falsch"}, {"id": "zap-23-4-2", "label": "2.", "prompt": "$$7895.21 - 168.7 + 31.3 = 7895.21 - 200$$", "options": ["richtig", "falsch"], "correctAnswer": "falsch"}, {"id": "zap-23-4-3", "label": "3.", "prompt": "$$89.65 \\cdot 6.3 = 6.3 \\cdot 89.65$$", "options": ["richtig", "falsch"], "correctAnswer": "richtig"}, {"id": "zap-23-4-4", "label": "4.", "prompt": "$$871.9 : 75 : 3 = 871.9 : 25$$", "options": ["richtig", "falsch"], "correctAnswer": "falsch"}]}, {"id": "zap-23-6", "type": "input", "number": 6, "prompt": "Netz eines Quaders.", "context": "Das Netz hat eine Gesamtbreite von 65 cm und eine Gesamthöhe von 56 cm. Die Höhe des linken Flügels ist 8 cm.", "imageUrl": "/images/math-2023/gemini/task-6.png", "subTasks": [{"id": "zap-23-6a", "label": "a)", "prompt": "Wie viele cm³ beträgt das Volumen des zusammengefalteten Quaders?", "suffix": "cm³", "modelAnswer": "Höhe Quader = 8 cm. Vertikales Netzmass: L + 2H = 56 -> L + 16 = 56 -> L = 40. Horizontales Netzmass: L + B = 65 -> 40 + B = 65 -> B = 25. Volumen = 40 * 25 * 8 = 8000.", "correctAnswer": 8000}]}, {"id": "zap-23-7", "type": "text-area", "number": 7, "prompt": "Rechenquadrate.", "context": "Ein Rechenquadrat besteht aus Zahlen. Die Mitte ist die Summe der vier grauen Dreiecke. Jedes graue Dreieck ist die Summe der angrenzenden weissen Dreiecke.", "imageUrl": "/images/math-2023/gemini/task-7.png", "subTasks": [{"id": "zap-23-7a", "label": "a)", "prompt": "Löse das linke Rechenquadrat. (Mitte: 46, Rechts-Weiss: 8, Unten-Weiss: 2, Unten-Grau: 12). Gib die fehlenden Zahlen an (Reihenfolge: Oben-Weiss, Links-Weiss, Oben-Grau, Rechts-Grau, Links-Grau).", "modelAnswer": "Oben-Weiss: 7, Links-Weiss: 3, Oben-Grau: 12, Rechts-Grau: 15, Links-Grau: 10. (Hinweis: Lösungen können je nach Interpretation variieren, mathematisch hergeleitet: Oben-W=3, Links-W=10...)"}, {"id": "zap-23-7b", "label": "b)", "prompt": "Löse das rechte Rechenquadrat. Bedingungen: Die oberen beiden weissen Dreiecke sind ungerade. Alle Zahlen sind verschieden. (Mitte: 30). Gib die Zahlen der vier weissen Dreiecke im Uhrzeigersinn an (startend oben).", "modelAnswer": "1, 3, 6, 5"}]}, {"id": "zap-23-8", "type": "input", "number": 8, "prompt": "Messer und Gabeln.", "context": "Gabeln: 4er Packung. Messer: 6er Packung. Ein Wirt kauft gleich viele Stück Messer wie Gabeln. Er kauft 13 Packungen Gabeln mehr als Messer.", "subTasks": [{"id": "zap-23-8a", "label": "Ergebnis", "prompt": "Wie viele Stück Gabeln hat der Wirt gekauft?", "suffix": "Stück", "modelAnswer": "6x = 4(x+13) -> 6x = 4x + 52 -> 2x = 52 -> x = 26 Packungen Messer. Gabeln = 4 * (26+13) = 156.", "correctAnswer": 156}]}, {"id": "zap-23-9", "type": "input", "number": 9, "prompt": "Quadrat und Rechteck überschneiden sich.", "context": "Ein Quadrat (6cm Seite) und ein Rechteck überschneiden sich so, dass drei Teilfiguren entstehen (siehe Bild). Alle drei Teilfiguren haben denselben Flächeninhalt.", "imageUrl": "/images/math-2023/gemini/task-9.png", "subTasks": [{"id": "zap-23-9a", "label": "a)", "prompt": "Bestimme den Flächeninhalt des grauen Rechtecks (Schnittfläche).", "suffix": "cm²", "modelAnswer": "Quadratfläche = 36. Fläche Quadrat ohne Schnitt = Fläche Schnitt. Also 2 * Schnitt = 36 -> Schnitt = 18.", "correctAnswer": 18}, {"id": "zap-23-9b", "label": "b)", "prompt": "Berechne den Umfang der Gesamtfigur (fett gedruckt).", "suffix": "cm", "modelAnswer": "Schnittfläche = 18. Breite aus Quadrat (6-2=4? Nein, 2cm ist Reststück). Höhe Schnitt = 4cm (da 6-2). Breite Schnitt = 18/4 = 4.5cm. Rechteck: Fläche 36, Höhe 5 -> Breite 7.2. Umfang addieren: 31.4 cm.", "correctAnswer": 31.4}]}]}', NULL, '2026-02-22 22:49:48.46639+00', '2026-02-22 22:49:48.46639+00'),
	('math-2023-qwen', 'Mathematik 2023 (Langgymnasium)', 'Math', 2023, 'Qwen 3 Max', '{"meta": {"time": "60 Minuten", "hints": ["Löse die Aufgaben direkt auf das Aufgabenblatt.", "Du musst Ausrechnungen und Zwischenresultate aufschreiben, damit der Lösungsweg verständlich ist.", "Antwortsätze sind nicht verlangt. Kennzeichne aber die Ergebnisse deutlich und notiere sie mit der passenden Masseinheit.", "Du darfst die Aufgaben in beliebiger Reihenfolge lösen.", "Bei Aufgabe 4 erhältst du für jedes richtig gesetzte Kreuz einen Punkt, für jedes falsch gesetzte Kreuz einen Punkt Abzug.", "Die Aufgabe 5 musst du mit Bleistift und Geometriewerkzeugen lösen. Die Konstruktionslinien müssen sichtbar sein.", "Bei Aufgabe 6 darfst du das Netz weder ausschneiden noch nachbilden.", "Du darfst weder Taschenrechner noch andere elektronische Hilfsmittel verwenden.", "Jede Aufgabe zählt 4 Punkte."], "maxPoints": 36}, "questions": [{"id": "m23-1", "type": "input", "number": 1, "prompt": "Bestimme die fehlende Zahl im Kästchen.", "context": "a) $2 \\cdot \\square + 536\\,\\text{kg} = 1.24\\,\\text{t}$\nb) $\\left(\\frac{5}{9} \\text{ von } 2\\,\\text{h}\\,33\\,\\text{min}\\right) - \\square = \\frac{3}{5}\\,\\text{h}$", "subTasks": [{"id": "m23-1-a", "label": "a):", "prompt": "Fehlende Masse in kg", "suffix": "kg", "correctAnswer": 352}, {"id": "m23-1-b", "label": "b):", "prompt": "Fehlende Zeit in Minuten", "suffix": "min", "correctAnswer": 49}]}, {"id": "m23-2", "type": "input", "number": 2, "prompt": "Die folgende Tabelle zeigt Distanzen und Zeiten für Verbindungen Zürich–Paris und Zürich–Brüssel.", "context": "a) Schnellster Zugweg Zürich–Brüssel führt über Paris (575 km Zürich–Paris, 848 km Zürich–Brüssel). Wie weit ist Paris–Brüssel?\nb) Flug Zürich–Brüssel: 500 km in 75 min. Durchschnittsgeschwindigkeit?\nc) Auto Zürich–Paris: 640 km in 400 min → 96 km/h. Auto Zürich–Brüssel: 632 km in 435 min. Wie viele Minuten könnte man bei 96 km/h sparen?", "subTasks": [{"id": "m23-2-a", "label": "a):", "prompt": "Distanz Paris–Brüssel", "suffix": "km", "correctAnswer": 273}, {"id": "m23-2-b", "label": "b):", "prompt": "Durchschnittsgeschwindigkeit Flug", "suffix": "km/h", "correctAnswer": 400}, {"id": "m23-2-c", "label": "c):", "prompt": "Zeitersparnis bei Auto Brüssel", "suffix": "min", "correctAnswer": 40}]}, {"id": "m23-3", "type": "input", "number": 3, "prompt": "a) Welchem Bruchteil des Rechtecks entspricht der graue Teil? Gib als vollständig gekürzten Bruch an.", "context": "b) Gegeben ist ein graues Teilstück, das $\\frac{3}{5}$ eines Rechtecks ausmacht. Berechne die Gesamtanzahl Häuschen und zeichne das Rechteck.", "imageUrl": "/images/math-2023/qwen/task-3.png", "subTasks": [{"id": "m23-3-a", "label": "A:", "prompt": "Bruchteil A", "suffix": "", "correctAnswer": "4/15"}, {"id": "m23-3-b", "label": "B:", "prompt": "Bruchteil B", "suffix": "", "correctAnswer": "1/2"}, {"id": "m23-3-c", "label": "Gesamtfläche:", "prompt": "Anzahl Häuschen im gesamten Rechteck", "suffix": "", "correctAnswer": 20}]}, {"id": "m23-4", "type": "multiple-choice", "number": 4, "prompt": "Sind die folgenden Aussagen richtig oder falsch? Kreuze jeweils eine Option an.", "context": "Beachte: Falsche Kreuze geben Abzug. Leer lassen = 0 Punkte.", "subTasks": [{"id": "m23-4-a", "label": "1:", "prompt": "$90 \\cdot 568.1 = 100 \\cdot 568.1 - 10 \\cdot 568.1$", "options": ["richtig", "falsch"], "correctAnswer": "richtig"}, {"id": "m23-4-b", "label": "2:", "prompt": "$7895.21 - 168.7 + 31.3 = 7895.21 - 200$", "options": ["richtig", "falsch"], "correctAnswer": "falsch"}, {"id": "m23-4-c", "label": "3:", "prompt": "$89.65 \\cdot 6.3 = 6.3 \\cdot 89.65$", "options": ["richtig", "falsch"], "correctAnswer": "richtig"}, {"id": "m23-4-d", "label": "4:", "prompt": "$871.9 : 75 : 3 = 871.9 : 25$", "options": ["richtig", "falsch"], "correctAnswer": "falsch"}]}, {"id": "m23-5", "type": "text-area", "number": 5, "prompt": "Wachhund Rex bewacht ein Haus. Punkte: F (Futternapf), K (Knochen), L (Leinenbefestigung).", "context": "a) Konstruiere Punkt P auf Wanderweg w, der gleich weit von F und K entfernt ist.\nb) Leine ist 20 m lang (Massstab gegeben). Konstruiere und markiere das erreichbare Gebiet.", "imageUrl": "/images/math-2023/qwen/task-5.png", "subTasks": [{"id": "m23-5-a", "label": "a)", "prompt": "Konstruktion des Punktes P (Mittelsenkrechte von F und K, Schnitt mit w)", "modelAnswer": "P ist Schnittpunkt der Mittelsenkrechten von F und K mit dem Wanderweg w"}, {"id": "m23-5-b", "label": "b)", "prompt": "Markierung des 20 m-Radius-Gebiets um L, beschnitten durch Sichtlinie zum Haus", "modelAnswer": "Kreis um L mit Radius 20 m, Schnitt mit Sichtfeld (Gerade durch linke obere Hausecke)"}]}, {"id": "m23-6", "type": "input", "number": 6, "prompt": "Gegeben ist das Netz eines Quaders (8 cm Höhe, 56 cm und 65 cm Gesamtlänge/Breite).", "context": "a) Volumen berechnen.\nb) Welche Kante wird mit k verklebt?\nc) Welche zwei anderen Ecken fallen mit E zusammen?", "imageUrl": "/images/math-2023/qwen/task-6.png", "subTasks": [{"id": "m23-6-a", "label": "a) Volumen:", "prompt": "Volumen des Quaders", "suffix": "cm³", "correctAnswer": 8000}, {"id": "m23-6-b", "label": "b) Gegenkante:", "prompt": "Gegenstück zu Kante k im Netz", "modelAnswer": "Die gegenüberliegende vertikale Kante am anderen Ende des Mantels"}, {"id": "m23-6-c", "label": "c) Ecken:", "prompt": "Zwei weitere Ecken, die mit E identisch werden", "modelAnswer": "Je eine Ecke an den Enden der langen Rechtecksseite, verbunden mit E über die Mantelfläche"}]}, {"id": "m23-7", "type": "input", "number": 7, "prompt": "Rechenquadrate: Mittenzahl = Summe der vier grauen Dreiecke. Graues Dreieck = Summe angrenzender weisser Dreiecke.", "context": "a) Fünf fehlende Zahlen ergänzen.\nb) Sechs Zahlen ergänzen, sodass obere weisse Zahlen ungerade und alle Zahlen verschieden sind.", "subTasks": [{"id": "m23-7-a1", "label": "a) Ecke links oben:", "prompt": "Zahl im linken oberen weissen Dreieck", "suffix": "", "correctAnswer": 7}, {"id": "m23-7-a2", "label": "a) Mitte oben:", "prompt": "Zahl im oberen grauen Dreieck", "suffix": "", "correctAnswer": 12}, {"id": "m23-7-a3", "label": "a) Mitte links:", "prompt": "Zahl im linken grauen Dreieck", "suffix": "", "correctAnswer": 10}, {"id": "m23-7-a4", "label": "a) Mitte rechts:", "prompt": "Zahl im rechten grauen Dreieck", "suffix": "", "correctAnswer": 11}, {"id": "m23-7-a5", "label": "a) Mitte unten:", "prompt": "Zahl im unteren grauen Dreieck", "suffix": "", "correctAnswer": 13}, {"id": "m23-7-b1", "label": "b) Oben links:", "prompt": "Ungerade Zahl links oben", "suffix": "", "correctAnswer": 1}, {"id": "m23-7-b2", "label": "b) Oben rechts:", "prompt": "Ungerade Zahl rechts oben", "suffix": "", "correctAnswer": 5}, {"id": "m23-7-b3", "label": "b) Unten links:", "prompt": "Zahl unten links", "suffix": "", "correctAnswer": 2}, {"id": "m23-7-b4", "label": "b) Unten mitte:", "prompt": "Zahl unten mitte", "suffix": "", "correctAnswer": 7}, {"id": "m23-7-b5", "label": "b) Unten rechts:", "prompt": "Zahl unten rechts", "suffix": "", "correctAnswer": 9}, {"id": "m23-7-b6", "label": "b) Mitte unten grau:", "prompt": "Graue Zahl unten", "suffix": "", "correctAnswer": 16}]}, {"id": "m23-8", "type": "input", "number": 8, "prompt": "Gabeln (4 pro Packung) und Messer (6 pro Packung). Der Wirt kauft gleich viele Gabeln wie Messer, aber 13 Packungen Gabeln mehr als Messer. Wie viele Gabeln hat er gekauft?", "context": "", "subTasks": [{"id": "m23-8-a", "label": "Gabeln:", "prompt": "Anzahl gekaufter Gabeln", "suffix": "", "correctAnswer": 156}]}, {"id": "m23-9", "type": "input", "number": 9, "prompt": "Ein Quadrat (6 cm × 6 cm) und ein Rechteck (5 cm × unbekannt) überlappen sich in einem grauen Rechteck, sodass drei Teilfiguren mit gleichem Flächeninhalt entstehen.", "context": "a) Flächeninhalt des grauen Rechtecks?\nb) Umfang der Gesamtfigur?", "imageUrl": "/images/math-2023/qwen/task-9.png", "subTasks": [{"id": "m23-9-a", "label": "a) Graue Fläche:", "prompt": "Flächeninhalt des grauen Bereichs", "suffix": "cm²", "correctAnswer": 18}, {"id": "m23-9-b", "label": "b) Umfang:", "prompt": "Umfang der Gesamtfigur", "suffix": "cm", "correctAnswer": 31.4}]}]}', NULL, '2026-02-22 22:49:48.507169+00', '2026-02-22 22:49:48.507169+00'),
	('math-2023', 'Mathematik 2023 (Langgymnasium)', 'Math', 2023, NULL, '{"meta": {"time": "60 Minuten", "hints": ["Löse die Aufgaben direkt auf das Aufgabenblatt. Reicht der Platz bei einer Aufgabe nicht aus, fährst du auf der letzten Seite weiter.", "Du musst Ausrechnungen und Zwischenresultate aufschreiben, damit der Lösungsweg verständlich ist; sonst erhältst du keine Punkte.", "Antwortsätze sind nicht verlangt. Kennzeichne aber die Ergebnisse deutlich und notiere sie mit der passenden Masseinheit.", "Du darfst die Aufgaben in beliebiger Reihenfolge lösen.", "Bei Aufgabe 4 erhältst du für jedes richtig gesetzte Kreuz einen Punkt, für jedes falsch gesetzte Kreuz einen Punkt Abzug.", "Bei Aufgabe 6 darfst du das Netz weder ausschneiden noch nachbilden.", "Du darfst weder Taschenrechner noch andere elektronische Hilfsmittel verwenden."], "maxPoints": 36}, "questions": [{"id": "m23-1", "type": "input", "number": 1, "prompt": "Bestimme die fehlende Zahl im Kästchen.", "subTasks": [{"id": "m23-1-a", "label": "a)", "prompt": "$2 \\cdot \\square \\text{ kg} + 536\\text{ kg} = 1.24\\text{ t}$", "correctAnswer": 352}, {"id": "m23-1-b", "label": "b)", "prompt": "$\\left(\\frac{5}{9} \\text{ von } 2\\text{ h } 33\\text{ min}\\right) - \\square \\text{ min} = \\frac{3}{5}\\text{ h}$", "correctAnswer": 49}]}, {"id": "m23-2", "type": "input", "number": 2, "prompt": "Die folgende Tabelle zeigt die Distanzen und Zeiten für die jeweils schnellsten Verbindungen.", "context": "| | Zürich–Paris | | Zürich–Brüssel | |\n|---|---|---|---|---|\n| | Distanz | Reisezeit | Distanz | Reisezeit |\n| Luftlinie | 488 km | – | 493 km | – |\n| Flugzeug | 490 km | 1 h 15 min | 500 km | 1 h 15 min |\n| Zug | 575 km | 4 h 10 min | 848 km | 6 h 50 min |\n| Auto | 640 km | 6 h 40 min | 632 km | 7 h 15 min |", "subTasks": [{"id": "m23-2-a", "label": "a)", "prompt": "Der schnellste Weg mit dem Zug von Zürich nach Brüssel führt über Paris. Wie weit ist demnach die Distanz von Paris nach Brüssel mit dem Zug?", "suffix": "km", "correctAnswer": 273}, {"id": "m23-2-b", "label": "b)", "prompt": "Wie viele km/h beträgt die Durchschnittsgeschwindigkeit eines Fluges von Zürich nach Brüssel?", "suffix": "km/h", "correctAnswer": 400}, {"id": "m23-2-c", "label": "c)", "prompt": "Wie viele Minuten könnte ein Auto auf der Fahrt von Zürich nach Brüssel einsparen, wenn es gleich schnell fahren könnte wie ein Auto auf der Fahrt von Zürich nach Paris?", "suffix": "min", "correctAnswer": 40}]}, {"id": "m23-3", "type": "input", "number": 3, "prompt": "Du siehst zwei Abbildungen mit Rechtecken, deren Seiten auf den Linien der Häuschen liegen. Darin ist je eine Figur grau eingezeichnet.", "context": "Rechteck A: 6 × 5 = 30 Häuschen, graue Figur entspricht 8 Häuschen.\nRechteck B: 10 × 6 = 60 halbe Häuschen, graue Figur entspricht 30 halbe Häuschen.", "imageUrl": "/images/math-2023/claude-opus-4-5/task-3.png", "subTasks": [{"id": "m23-3-a-A", "label": "a) Figur A:", "prompt": "Welchem Bruchteil des Rechtecks entspricht der graue Teil? (gekürzter Bruch)", "correctAnswer": "4/15"}, {"id": "m23-3-a-B", "label": "a) Figur B:", "prompt": "Welchem Bruchteil des Rechtecks entspricht der graue Teil? (gekürzter Bruch)", "correctAnswer": "1/2"}, {"id": "m23-3-b", "label": "b)", "prompt": "Das Teilstück macht $\\frac{3}{5}$ von einem Rechteck aus. Berechne die Anzahl Häuschen des Rechtecks.", "correctAnswer": 20}]}, {"id": "m23-4", "rows": [{"id": "r1", "text": "$90 \\cdot 568.1 = 100 \\cdot 568.1 - 10 \\cdot 568.1$"}, {"id": "r2", "text": "$7895.21 - 168.7 + 31.3 = 7895.21 - 200$"}, {"id": "r3", "text": "$89.65 \\cdot 6.3 = 6.3 \\cdot 89.65$"}, {"id": "r4", "text": "$871.9 : 75 : 3 = 871.9 : 25$"}], "type": "table-select", "number": 4, "prompt": "Sind die folgenden Aussagen richtig oder falsch?", "columns": [{"id": "richtig", "label": "richtig"}, {"id": "falsch", "label": "falsch"}], "context": "Die Aufgabe soll gelöst werden, ohne dass die Rechnungen ausgeführt werden. Es ist keine Begründung und kein Lösungsweg notwendig. Falsch gesetzte Kreuze geben Abzug.", "subTasks": [{"id": "m23-4-dummy", "label": "Antworten:", "prompt": "Wähle für jede Aussage richtig oder falsch."}], "correctTableAnswers": {"r1": "richtig", "r2": "falsch", "r3": "richtig", "r4": "falsch"}}, {"id": "m23-6", "type": "input", "number": 6, "prompt": "In der Abbildung siehst du das Netz eines Quaders.", "context": "Das Netz zeigt einen Quader mit den Massen: Höhe = 8 cm, Gesamtbreite = 56 cm, Gesamthöhe = 65 cm. Die Grundfläche hat die Masse 40 cm × 25 cm (berechnet aus: Länge = 56 cm - 2 × 8 cm = 40 cm, Breite = 65 cm - 40 cm = 25 cm).", "imageUrl": "/images/math-2023/claude-opus-4-5/task-6.png", "subTasks": [{"id": "m23-6-a", "label": "a)", "prompt": "Wie viele cm³ beträgt das Volumen des zusammengefalteten Quaders?", "suffix": "cm³", "correctAnswer": 8000}]}, {"id": "m23-7", "type": "input", "number": 7, "prompt": "Rechenquadrate", "context": "Ein Rechenquadrat besteht aus ganzen Zahlen grösser als 0. Die Zahl in der Mitte ist die Summe der vier Zahlen in den grauen Dreiecken. Jede Zahl in einem grauen Dreieck ist die Summe der beiden Zahlen in den angrenzenden weissen Dreiecken.", "imageUrl": "/images/math-2023/claude-opus-4-5/task-7.png", "subTasks": [{"id": "m23-7-a-oben-links", "label": "a) Oben links:", "prompt": "Ergänze die Zahl oben links im Rechenquadrat mit Mitte 46, gegeben: unten links = 3, unten rechts = 8, rechts = 5", "imageUrl": "/images/math-2023/claude-opus-4-5/task-7-a.png", "correctAnswer": 7}, {"id": "m23-7-a-oben", "label": "a) Oben (grau):", "prompt": "Welche Zahl steht im grauen Dreieck oben?", "correctAnswer": 12}, {"id": "m23-7-a-links", "label": "a) Links (grau):", "prompt": "Welche Zahl steht im grauen Dreieck links?", "correctAnswer": 10}, {"id": "m23-7-a-rechts", "label": "a) Rechts (grau):", "prompt": "Welche Zahl steht im grauen Dreieck rechts?", "correctAnswer": 13}, {"id": "m23-7-a-unten", "label": "a) Unten (grau):", "prompt": "Welche Zahl steht im grauen Dreieck unten?", "correctAnswer": 11}, {"id": "m23-7-b-oben-links", "label": "b) Oben links:", "prompt": "Ergänze das Rechenquadrat mit Mitte 30 so, dass die oberen weissen Dreiecke ungerade Zahlen enthalten und alle 9 Zahlen verschieden sind. Gegeben: unten links = 2, unten rechts = 7. Welche Zahl steht oben links?", "imageUrl": "/images/math-2023/claude-opus-4-5/task-7-b.png", "correctAnswer": 1}, {"id": "m23-7-b-oben-rechts", "label": "b) Oben rechts:", "prompt": "Welche Zahl steht oben rechts?", "correctAnswer": 5}, {"id": "m23-7-b-oben-grau", "label": "b) Oben (grau):", "prompt": "Welche Zahl steht im grauen Dreieck oben?", "correctAnswer": 6}, {"id": "m23-7-b-links-grau", "label": "b) Links (grau):", "prompt": "Welche Zahl steht im grauen Dreieck links?", "correctAnswer": 3}, {"id": "m23-7-b-rechts-grau", "label": "b) Rechts (grau):", "prompt": "Welche Zahl steht im grauen Dreieck rechts?", "correctAnswer": 12}, {"id": "m23-7-b-unten-grau", "label": "b) Unten (grau):", "prompt": "Welche Zahl steht im grauen Dreieck unten?", "correctAnswer": 9}]}, {"id": "m23-8", "type": "input", "number": 8, "prompt": "Gabeln werden in Packungen zu 4 Stück verkauft und Messer in Packungen zu 6 Stück.", "context": "Ein Wirt möchte gleich viele Stück Messer wie Gabeln kaufen. Dazu kauft er 13 Packungen Gabeln mehr als Packungen Messer.", "subTasks": [{"id": "m23-8-a", "label": "Anzahl Gabeln:", "prompt": "Wie viele Stück Gabeln hat der Wirt gekauft?", "correctAnswer": 156}]}, {"id": "m23-9", "type": "input", "number": 9, "prompt": "In der Abbildung überschneiden sich ein Quadrat und ein Rechteck in einem rechteckigen Gebiet (grau), sodass drei Teilfiguren entstehen.", "context": "Das Quadrat hat die Seitenlänge 6 cm. Das Rechteck hat die Breite 5 cm und eine bekannte Seite von 2 cm. Die drei Teilfiguren (Quadrat ohne Überlappung, graues Rechteck, Rechteck ohne Überlappung) haben alle denselben Flächeninhalt.", "imageUrl": "/images/math-2023/claude-opus-4-5/task-9.png", "subTasks": [{"id": "m23-9-a", "label": "a)", "prompt": "Bestimme den Flächeninhalt des grauen Rechtecks.", "suffix": "cm²", "correctAnswer": 18}, {"id": "m23-9-b", "label": "b)", "prompt": "Berechne den Umfang der Gesamtfigur (in der Abbildung fett ausgezogen).", "suffix": "cm", "correctAnswer": 31.4}]}]}', NULL, '2026-02-22 22:49:48.62271+00', '2026-02-22 22:49:48.62271+00'),
	('math-2024-gemini', 'Zentrale Aufnahmeprüfung 2024 Mathematik', 'Math', 2024, 'Gemini 3 Pro', '{"meta": {"time": "60 Minuten", "hints": ["Taschenrechner sind nicht erlaubt.", "Zwischenresultate notieren.", "Ergebnisse mit Masseinheit angeben."], "maxPoints": 36}, "questions": [{"id": "zap-24-1", "type": "input", "number": 1, "prompt": "Berechne das Ergebnis.", "context": "Tipp: Wenn du geschickt rechnest, kannst du den Rechenaufwand stark verringern.", "subTasks": [{"id": "zap-24-1a", "label": "Ergebnis", "prompt": "$$(6.2 \\cdot 2024) + (4.2 \\cdot 1107) - (3.1 \\cdot 4048)$$", "modelAnswer": "Der erste und dritte Term heben sich auf: 3.1 * 4048 = 3.1 * 2 * 2024 = 6.2 * 2024. Es bleibt 4.2 * 1107 = 4649.4", "correctAnswer": 4649.4}]}, {"id": "zap-24-2", "type": "input", "number": 2, "prompt": "Koordinatensystem und Parallelogramm.", "context": "Gegeben sind die Punkte $A(5/2)$, $B(7/5)$ und $C(4/4)$.", "imageUrl": "/images/math-2024/gemini/task-2.png", "subTasks": [{"id": "zap-24-2b", "label": "b)", "prompt": "Es gibt mehrere Möglichkeiten, das Dreieck ABC mit einem vierten Punkt zu einem Parallelogramm zu ergänzen. Notiere die Koordinaten aller 3 möglichen Punkte ($D_1, D_2, D_3$) in der Form ''(x/y)''.", "modelAnswer": "(2/1), (8/3), (6/7)", "correctAnswer": "(2/1), (8/3), (6/7)"}]}, {"id": "zap-24-3", "type": "input", "number": 3, "prompt": "Oliver und Claudia vergleichen Parkgebühren.", "context": "**Parkhaus Zentrum:** Erste 3 Stunden gratis, dann 2.50 Fr. pro weitere Stunde.\n**Parkhaus am Fluss:** 4 Fr. für die erste Stunde, dann 1.20 Fr. pro weitere Stunde.", "subTasks": [{"id": "zap-24-3a-1", "label": "a) Zentrum", "prompt": "Oliver parkiert 12 Stunden. Wie viel bezahlt er im **Zentrum**?", "suffix": "Fr.", "modelAnswer": "12h total. 3h gratis -> 9h zahlen. 9 * 2.50 = 22.50 Fr.", "correctAnswer": 22.5}, {"id": "zap-24-3a-2", "label": "a) Fluss", "prompt": "Wie viel bezahlt er am **Fluss**?", "suffix": "Fr.", "modelAnswer": "1. Stunde = 4 Fr. Restliche 11h * 1.20 = 13.20 Fr. Total = 17.20 Fr.", "correctAnswer": 17.2}, {"id": "zap-24-3b-1", "label": "b) Zentrum", "prompt": "Claudia hat 10 Fr. Wie viele Stunden kann sie damit maximal im **Zentrum** parkieren?", "suffix": "h", "modelAnswer": "10 Fr. : 2.50 = 4 bezahlte Stunden. Plus 3 Gratis-Stunden = 7 Stunden.", "correctAnswer": 7}, {"id": "zap-24-3b-2", "label": "b) Fluss", "prompt": "Wie viele Stunden kann sie damit maximal am **Fluss** parkieren?", "suffix": "h", "modelAnswer": "10 Fr. - 4 Fr. (1. h) = 6 Fr. Rest. 6 : 1.20 = 5 weitere Stunden. Total 1 + 5 = 6 Stunden.", "correctAnswer": 6}]}, {"id": "zap-24-4", "type": "input", "number": 4, "prompt": "Brüche und Zahlenstrahl.", "subTasks": [{"id": "zap-24-4a-1", "label": "a) weiss", "prompt": "Abgebildet ist ein Punktmuster (siehe Bild). Welchen Anteil machen die **weissen** Punkte aus? (Gekürzter Bruch)", "imageUrl": "/images/math-2024/gemini/task-4-a.png", "modelAnswer": "4 weisse von 20 total. 4/20 = 1/5.", "correctAnswer": "1/5"}, {"id": "zap-24-4a-2", "label": "a) grau", "prompt": "Anteil der **grauen** Punkte?", "modelAnswer": "10 graue von 20 total. 10/20 = 1/2.", "correctAnswer": "1/2"}, {"id": "zap-24-4a-3", "label": "a) schwarz", "prompt": "Anteil der **schwarzen** Punkte?", "modelAnswer": "6 schwarze von 20 total. 6/20 = 3/10.", "correctAnswer": "3/10"}, {"id": "zap-24-4b", "label": "b)", "prompt": "Im Zahlenstrahl sind $1/2$ und $3/4$ eingezeichnet. Wie gross ist der Abstand zwischen zwei benachbarten Strichen (als Bruch)?", "imageUrl": "/images/math-2024/gemini/task-4-b.png", "modelAnswer": "Differenz 3/4 - 1/2 = 1/4. Es sind 6 Schritte dazwischen. (1/4) : 6 = 1/24.", "correctAnswer": "1/24"}]}, {"id": "zap-24-5", "type": "input", "number": 5, "prompt": "Susanne und Markus fahren einander entgegen.", "context": "Markus (Zürich) und Susanne (Berlin) sind 870 km voneinander entfernt.\n* Markus: 22 km/h\n* Susanne: 18 km/h\n* Tag 1-3: Beide fahren je 6 Stunden.\n* Tag 4: Markus ist krank, Susanne fährt alleine weiter.", "subTasks": [{"id": "zap-24-5a", "label": "Antwort", "prompt": "Wie lange muss Susanne am 4. Tag fahren, bis sie bei Markus ankommt? (Format: ''X h Y min'')", "modelAnswer": "In 3 Tagen (18h) fahren sie zusammen 18h * (22+18)km/h = 18 * 40 = 720 km. Reststrecke: 870 - 720 = 150 km. Susanne braucht für 150 km: 150 / 18 = 8.333 h = 8 h 20 min.", "correctAnswer": "8 h 20 min"}]}, {"id": "zap-24-6", "type": "input", "number": 6, "prompt": "Gartenbeete berechnen.", "imageUrl": "/images/math-2024/gemini/task-6.png", "subTasks": [{"id": "zap-24-6a", "label": "a)", "prompt": "Berechne den **Umfang** von Laras Garten (oben). Die Flächen der Beete sind $18 m^2$, $12 m^2$, $15 m^2$ und $6 m^2$. Die Gesamthöhe links ist 12m, die Gesamtbreite unten 18m.", "suffix": "m", "modelAnswer": "Zerlegung der Rechtecke: Fläche 18 (unten links, Breite aus 18-x? Nein, Analyse der Seitenverhältnisse notwendig). Lösungsweg Schema: 37m.", "correctAnswer": 37}, {"id": "zap-24-6b", "label": "b)", "prompt": "Berechne den **Umfang** von Emils Garten (unten, kariertes Raster). Ein Kästchen entspricht einer Einheit.", "suffix": "m", "modelAnswer": "Der Umfang entspricht dem umschliessenden Rechteck, da die Einbuchtung ''ausgeglichen'' wird. 2 * (12m + 18m) = 60m.", "correctAnswer": 60}]}, {"id": "zap-24-8", "type": "input", "number": 8, "prompt": "Proportionalität prüfen.", "context": "Finde das Wertepaar, das nicht proportional zu den anderen ist, und korrigiere den rechten Wert.", "subTasks": [{"id": "zap-24-8a", "label": "a)", "prompt": "Paare: (1.6 dl | 800 g), (4.8 dl | 2 kg 400 g), (24 dl | 12 kg 500 g), (19.2 dl | 96 kg). Welches Paar ist falsch? Gib den **korrigierten rechten Wert** für dieses Paar an.", "suffix": "kg", "modelAnswer": "Das 3. Paar ist falsch. Proportionalitätsfaktor 500g/dl. 24 dl * 500 g = 12000 g = 12 kg. (Das angegebene 12.5 kg ist falsch).", "correctAnswer": 12}, {"id": "zap-24-8b", "label": "b)", "prompt": "Paare: (40 s | 120 km), (4 min | 1200 km), (15 min | 4500 km), (120 min | 36000 km). Welches Paar ist falsch? Gib den **korrigierten rechten Wert** an.", "suffix": "km", "modelAnswer": "Das 1. Paar ist falsch. Faktor: 300 km/min (= 5 km/s). 40s * 5 = 200 km. (Angegeben 120 km ist falsch).", "correctAnswer": 200}]}, {"id": "zap-24-9", "type": "input", "number": 9, "prompt": "Zahlenmauern (Addition).", "imageUrl": "/images/math-2024/gemini/task-9.png", "subTasks": [{"id": "zap-24-9a", "label": "a)", "prompt": "Ergänze die Zahlenmauer a). Gib den Wert des obersten Decksteins an.", "modelAnswer": "Rechte Seite berechnen: 343 (Mitte unten) -> 778 (Mitte rechts) -> Lücke rechts unten = 434. Oben rechnen bis zur Spitze: 1555.", "correctAnswer": 1555}, {"id": "zap-24-9b", "label": "b)", "prompt": "Ergänze Zahlenmauer b). Basissteine dürfen nur Ziffern 1 und 2 enthalten. Deckstein nur Ziffern 7 und 5. Gib den Wert des **Decksteins** an.", "modelAnswer": "Durch Probieren der Kombinationen (112, 121, etc.) ergibt sich die Lösung mit Deckstein 757.", "correctAnswer": 757}]}]}', NULL, '2026-02-22 22:49:48.661542+00', '2026-02-22 22:49:48.661542+00'),
	('math-2024-qwen', 'Mathematik 2024 (Langgymnasium)', 'Math', 2024, 'Qwen 3 Max', '{"meta": {"time": "60 Minuten", "hints": ["Löse die Aufgaben direkt auf das Aufgabenblatt.", "Du musst Ausrechnungen und Zwischenresultate aufschreiben, damit der Lösungsweg verständlich ist.", "Antwortsätze sind nicht verlangt. Kennzeichne aber die Ergebnisse deutlich und notiere sie mit der passenden Masseinheit.", "Du darfst keinen Taschenrechner verwenden.", "Jede Aufgabe zählt 4 Punkte."], "maxPoints": 36}, "questions": [{"id": "m24-1", "type": "input", "number": 1, "prompt": "Gib das Ergebnis an: $(6.2 \\cdot 2024) + (4.2 \\cdot 1107) - (3.1 \\cdot 4048)$", "context": "Wenn du geschickt rechnest, kannst du den Rechenaufwand stark verringern.", "subTasks": [{"id": "m24-1-a", "label": "Ergebnis:", "prompt": "", "suffix": "", "correctAnswer": 4649.4}]}, {"id": "m24-2", "type": "input", "number": 2, "prompt": "a) Trage die folgenden Punkte ins Koordinatensystem ein und schreibe sie an. (1P) A(5/2) B(7/5) C(4/4)", "context": "b) Es gibt mehrere Möglichkeiten, das Dreieck ABC mit einem vierten Punkt zu einem Parallelogramm zu ergänzen. Zeichne alle möglichen Punkte ein und notiere die Koordinaten dieser Punkte. (3P)", "imageUrl": "/images/math-2024/task-2.png", "subTasks": [{"id": "m24-2-a", "label": "D₁:", "prompt": "Koordinaten des ersten Punktes", "suffix": "", "correctAnswer": "(2/1)"}, {"id": "m24-2-b", "label": "D₂:", "prompt": "Koordinaten des zweiten Punktes", "suffix": "", "correctAnswer": "(8/3)"}, {"id": "m24-2-c", "label": "D₃:", "prompt": "Koordinaten des dritten Punktes", "suffix": "", "correctAnswer": "(6/7)"}]}, {"id": "m24-3", "type": "input", "number": 3, "prompt": "Oliver und Claudia müssen ihr Auto im Parkhaus lassen. Es stehen ihnen zwei Parkhäuser mit unterschiedlichen Preisen zur Auswahl.", "context": "Parkhaus Zentrum: Die ersten 3 Stunden sind gratis, danach 2.50 Fr. pro weitere Stunde.\nParkhaus am Fluss: 4 Fr. für die erste Stunde, danach 1.20 Fr. pro weitere Stunde.", "subTasks": [{"id": "m24-3-a1", "label": "Zentrum (12 h):", "prompt": "Kosten für Oliver im Parkhaus Zentrum bei 12 Stunden Parkdauer", "suffix": "Fr.", "correctAnswer": 22.5}, {"id": "m24-3-a2", "label": "Am Fluss (12 h):", "prompt": "Kosten für Oliver im Parkhaus am Fluss bei 12 Stunden Parkdauer", "suffix": "Fr.", "correctAnswer": 17.2}, {"id": "m24-3-b1", "label": "Zentrum (10 Fr.):", "prompt": "Maximale Parkdauer für Claudia im Zentrum mit 10 Fr.", "suffix": "h", "correctAnswer": 7}, {"id": "m24-3-b2", "label": "Am Fluss (10 Fr.):", "prompt": "Maximale Parkdauer für Claudia am Fluss mit 10 Fr.", "suffix": "h", "correctAnswer": 6}]}, {"id": "m24-4", "type": "input", "number": 4, "prompt": "a) Welchen Anteil aller Punkte machen – die weissen, – die grauen, – die schwarzen Punkte aus? Notiere jeweils als vollständig gekürzten Bruch. (2P)", "context": "b) Im Zahlenstrahl sind die Brüche $\\frac{1}{2}$ und $\\frac{3}{4}$ eingezeichnet. (2P)\n– Wie gross ist der Abstand zwischen zwei benachbarten Strichen?\n– Trage den Bruch $\\frac{5}{6}$ ein.", "imageUrl": "/images/math-2024/task-4.png", "subTasks": [{"id": "m24-4-a1", "label": "Weiss:", "prompt": "Anteil der weissen Punkte", "suffix": "", "correctAnswer": "1/5"}, {"id": "m24-4-a2", "label": "Grau:", "prompt": "Anteil der grauen Punkte", "suffix": "", "correctAnswer": "1/2"}, {"id": "m24-4-a3", "label": "Schwarz:", "prompt": "Anteil der schwarzen Punkte", "suffix": "", "correctAnswer": "3/10"}, {"id": "m24-4-b", "label": "Abstand:", "prompt": "Abstand zwischen zwei benachbarten Strichen", "suffix": "", "correctAnswer": "1/24"}]}, {"id": "m24-5", "type": "input", "number": 5, "prompt": "Susanne und Markus fahren einander mit dem Fahrrad entgegen. Markus startet in Zürich und Susanne im 870 km entfernten Berlin. Markus fährt mit durchschnittlich 22 km/h und Susanne mit durchschnittlich 18 km/h. Sie fahren beide gleichzeitig los. Am ersten, zweiten und dritten Tag fahren beide täglich 6 Stunden. Am vierten Tag ist Markus krank und kann nicht weiterfahren. Wie lange muss Susanne am vierten Tag fahren, bis sie beim kranken Markus ankommt?", "context": "Gib das Resultat in Stunden und Minuten an.", "subTasks": [{"id": "m24-5-a", "label": "Fahrzeit:", "prompt": "Wie lange muss Susanne am vierten Tag fahren?", "suffix": "", "correctAnswer": "8 h 20 min"}]}, {"id": "m24-6", "type": "input", "number": 6, "prompt": "Lara und Emil haben beide einen Garten. Da sie beide vier Sorten Gemüse anpflanzen wollen, unterteilen sie den Garten jeweils in vier rechteckige Beete.", "context": "a) Berechne den Umfang von Laras Garten (siehe Figur, nicht massstäblich). (3P)\nb) Berechne den Umfang von Emils Garten (siehe Figur, nicht massstäblich). (1P)", "imageUrl": "/images/math-2024/task-6.png", "subTasks": [{"id": "m24-6-a", "label": "Laras Umfang:", "prompt": "Umfang von Laras Garten", "suffix": "m", "correctAnswer": 37}, {"id": "m24-6-b", "label": "Emils Umfang:", "prompt": "Umfang von Emils Garten", "suffix": "m", "correctAnswer": 60}]}, {"id": "m24-7", "type": "text-area", "number": 7, "prompt": "Der Würfel wird gedreht und/oder gekippt. Zeichne jeweils das korrekte Symbol auf die fehlende(n) Seite(n). Mache deutlich, ob das Symbol weiss oder schwarz ist.", "context": "Auf der einen Seite sind die drei sichtbaren Symbole weiss wie abgebildet, auf der gegenüberliegenden Seite ist dasselbe Symbol schwarz. Die Symbole zeigen auf jeweils gegenüberliegenden Seiten in die gleiche Richtung.", "imageUrl": "/images/math-2024/task-7.png", "subTasks": [{"id": "m24-7-a", "label": "a)", "prompt": "Zeichne das Symbol auf der fehlenden Seite (weiss/schwarz und korrekte Richtung).", "modelAnswer": "Weisser Pfeil nach oben"}, {"id": "m24-7-b", "label": "b)", "prompt": "Zeichne das Symbol auf der fehlenden Seite.", "modelAnswer": "Schwarzer Kreis"}, {"id": "m24-7-c", "label": "c)", "prompt": "Zeichne das Symbol auf der fehlenden Seite.", "modelAnswer": "Weisser Kreis"}, {"id": "m24-7-d", "label": "d)", "prompt": "Zeichne das Symbol auf der fehlenden Seite.", "modelAnswer": "Schwarzer Pfeil nach oben"}]}, {"id": "m24-8", "type": "input", "number": 8, "prompt": "Welches Wertepaar ist zu den anderen drei Wertepaaren nicht proportional? Umkreise es. Verändere anschliessend vom umkreisten Wertepaar den Wert auf der rechten Seite so, dass auch dieses Wertepaar proportional zu den anderen drei Wertepaaren ist.", "context": "a) 1.6 dl — 800 g, 4.8 dl — 2 kg 400 g, 2.4 l — 12 kg 500 g, 19.2 l — 96 kg\nb) 40 s — 120 km, 4 min — 1200 km, 15 min — 4500 km, 120 min — 36000 km", "subTasks": [{"id": "m24-8-a", "label": "Korrektur a):", "prompt": "Korrigierter Wert für das dritte Wertepaar (in kg)", "suffix": "kg", "correctAnswer": 12}, {"id": "m24-8-b", "label": "Korrektur b):", "prompt": "Korrigierter Wert für das erste Wertepaar (in km)", "suffix": "km", "correctAnswer": 200}]}, {"id": "m24-9", "type": "input", "number": 9, "prompt": "In dieser Aufgabe geht es um Zahlenmauern, die durch Addition entstanden sind.", "context": "a) Ergänze die dreistöckige Zahlenmauer. (1P)\nb) Ergänze die dreistöckige Zahlenmauer so, dass – die drei Basissteine nur aus den Ziffern 1 und 2 bestehen und – der Deckstein nur aus den Ziffern 7 und 5 besteht. (3P)", "subTasks": [{"id": "m24-9-a1", "label": "Mittel links:", "prompt": "Wert im linken Feld der mittleren Zeile", "suffix": "", "correctAnswer": 434}, {"id": "m24-9-a2", "label": "Mittel rechts:", "prompt": "Wert im rechten Feld der mittleren Zeile", "suffix": "", "correctAnswer": 344}, {"id": "m24-9-b1", "label": "Basis links:", "prompt": "Linker Basisstein (nur Ziffern 1 und 2)", "suffix": "", "correctAnswer": "212"}, {"id": "m24-9-b2", "label": "Basis mitte:", "prompt": "Mittlerer Basisstein (nur Ziffern 1 und 2)", "suffix": "", "correctAnswer": "221"}, {"id": "m24-9-b3", "label": "Basis rechts:", "prompt": "Rechter Basisstein (nur Ziffern 1 und 2)", "suffix": "", "correctAnswer": "212"}]}]}', NULL, '2026-02-22 22:49:48.706421+00', '2026-02-22 22:49:48.706421+00'),
	('math-2025-claude', 'Mathematik 2025 (Langgymnasium)', 'Math', 2025, 'Claude Opus 4.5', '{"meta": {"time": "60 Minuten", "hints": ["Löse die Aufgaben direkt auf das Aufgabenblatt. Reicht der Platz bei einer Aufgabe nicht aus, fährst du auf der letzten Seite weiter und notierst dazu die Aufgabennummer.", "Notiere Ausrechnungen und Zwischenresultate, damit der Lösungsweg verständlich ist.", "Antwortsätze sind nicht verlangt. Kennzeichne aber die Ergebnisse deutlich und notiere sie mit der passenden Masseinheit.", "Du darfst die Aufgaben in beliebiger Reihenfolge lösen.", "Bei Aufgabe 8 darfst du die Pyramide nicht mit Papier nachbauen.", "Du darfst keinen Taschenrechner und auch keine anderen elektronischen Hilfsmittel verwenden.", "Jede Aufgabe zählt 4 Punkte. Bei Teilaufgaben sind die Teilpunkte angegeben."], "maxPoints": 36}, "questions": [{"id": "m25-1", "type": "input", "number": 1, "prompt": "Bestimme die fehlende Zahl im Kästchen.", "subTasks": [{"id": "m25-1-a", "label": "a)", "prompt": "$(\\square \\cdot 11) : 81 = 671$", "correctAnswer": 4941}, {"id": "m25-1-b", "label": "b)", "prompt": "$\\left(\\frac{\\square}{7} \\text{ von } 2\\text{ h } 55\\text{ min}\\right) - \\frac{4}{5}\\text{ h} = 27\\text{ min}$", "correctAnswer": 3}]}, {"id": "m25-2", "type": "input", "number": 2, "prompt": "Ein Museum hat unterschiedliche Eintrittspreise für Kinder, Erwachsene und Pensionierte.", "context": "Preistabelle vom 2. März 2025:\n\n| Kategorie | Eintrittspreis | Einnahmen |\n|-----------|----------------|------------|\n| Kinder | 9 Fr. | – |\n| Erwachsene | 22 Fr. | – |\n| Pensionierte | 12 Fr. | 1092 Fr. |\n| **Insgesamt** | | **4052 Fr.** |", "subTasks": [{"id": "m25-2-a", "label": "a)", "prompt": "Eine Gruppe von drei Kindern, einem Erwachsenen und zwei Pensionierten geht ins Museum. Wie viele Franken muss die Gruppe insgesamt bezahlen?", "suffix": "Fr.", "correctAnswer": 73}, {"id": "m25-2-b", "label": "b)", "prompt": "Wie viele Pensionierte besuchten das Museum am 2. März 2025?", "correctAnswer": 91}, {"id": "m25-2-c", "label": "c)", "prompt": "Am 2. März 2025 wurden genau doppelt so viele Kinder- wie Erwachseneneintritte verkauft. Wie viele Kinder besuchten das Museum?", "correctAnswer": 148}]}, {"id": "m25-3", "type": "text-area", "number": 3, "prompt": "Frau Schlegel leert ihre Kasse. Diese enthält nur Fünffranken-, Zweifranken- und Einfrankenstücke. Von jeder der drei Sorten besitzt sie mindestens ein Stück. Insgesamt zählt sie 16 Franken.", "context": "Es gibt verschiedene Möglichkeiten für den Inhalt der Kasse. Trage alle Möglichkeiten in die Tabelle ein. Falsche Möglichkeiten geben Abzug. In dieser Aufgabe braucht es keinen Lösungsweg.\n\n**Achtung:** Die Tabelle hat mehr Zeilen, als es Möglichkeiten gibt!", "subTasks": [{"id": "m25-3-a", "label": "Anzahl Möglichkeiten:", "prompt": "Wie viele gültige Kombinationen gibt es?", "correctAnswer": 7}]}, {"id": "m25-4", "type": "input", "number": 4, "prompt": "Familie Schäfer will den Boden ihres Badezimmers mit kleinen und grossen quadratischen Platten belegen. Die Tochter schlägt folgende Anordnung vor:", "context": "Das Badezimmer hat einen rechteckigen Boden, der 10 kleine Platten breit und 7 kleine Platten hoch ist (also Platz für 70 kleine Platten). Im Vorschlag der Tochter sind 46 kleine weisse Platten und 6 grosse graue Platten zu sehen. Jede grosse Platte bedeckt den Platz von 4 kleinen Platten (2×2). Die kleinen Platten (weiss) kosten 5 Fr. pro Stück, die grossen Platten (grau) 12 Fr. pro Stück.", "imageUrl": "/images/math-2025/claude-opus-4-5/task-4.png", "subTasks": [{"id": "m25-4-a", "label": "a)", "prompt": "Welchen Anteil des Bodens machen die weissen Platten aus? Gib die Antwort als gekürzten Bruch an.", "correctAnswer": "23/35"}, {"id": "m25-4-b", "label": "b)", "prompt": "Wie viele Franken kosten die Platten insgesamt, die man beim Vorschlag der Tochter benötigen würde?", "suffix": "Fr.", "correctAnswer": 302}, {"id": "m25-4-c", "label": "c)", "prompt": "Der Vater möchte den ganzen Boden mit Platten bedecken und möglichst wenig Geld ausgeben. Wie viele Franken kostet die günstigste Möglichkeit?", "suffix": "Fr.", "correctAnswer": 230}]}, {"id": "m25-5", "type": "input", "number": 5, "prompt": "Bauer Meyer erntet Erdbeeren, um sie einzukochen.", "context": "Beim Transport in die Küche gehen 2.5 kg Erdbeeren verloren. In der Küche muss jede siebte Erdbeere aussortiert werden, weil sie schimmlig ist. Nach dem Einkochen ist noch $\\frac{3}{4}$ der Erdbeermasse übrig. Diese Masse wird in 108 Gläser zu je 500 g abgefüllt.", "subTasks": [{"id": "m25-5-a", "label": "Ernte:", "prompt": "Wie viele Kilogramm Erdbeeren hat Bauer Meyer zu Beginn geerntet?", "suffix": "kg", "correctAnswer": 86.5}]}, {"id": "m25-6", "type": "input", "number": 6, "prompt": "Eine Forschungsstation ist für 40 Personen eingerichtet. Bei einem vollen Lager reichen die Lebensmittel für die 40 Personen für 24 Tage.", "subTasks": [{"id": "m25-6-a", "label": "a)", "prompt": "Wie viele Tage länger reichen die Lebensmittel des vollen Lagers, wenn nur 30 Personen anwesend sind?", "suffix": "Tage", "correctAnswer": 8}, {"id": "m25-6-b", "label": "b)", "prompt": "Zu Beginn ist das Lager voll und es sind 20 Personen auf der Station. Nach 12 Tagen kommen 10 Personen hinzu. Wie viele Tage reicht der Lebensmittelvorrat jetzt noch?", "suffix": "Tage", "correctAnswer": 24}]}, {"id": "m25-8", "type": "multiple-choice", "number": 8, "prompt": "Auf einer Pyramide sind auf den drei Seitenflächen und der Grundfläche die Augenzahlen 1, 2, 3, 4 aufgemalt.", "context": "In der abgebildeten Startpyramide befindet sich die Seitenfläche mit 3 Punkten hinten und die Pyramide steht auf der Fläche mit 4 Punkten. Die Pyramide wird durch Kippen über eine Pyramidenkante bewegt. Die Anordnung der gezeichneten Punkte auf einer Seite spielt keine Rolle.", "imageUrl": "/images/math-2025/claude-opus-4-5/task-8.png", "subTasks": [{"id": "m25-8-a-links", "label": "a) Linke Seite:", "prompt": "Welche Augenzahl liegt auf der linken sichtbaren Seite der Zielpyramide?", "options": ["1", "2", "3", "4"], "imageUrl": "/images/math-2025/claude-opus-4-5/task-8-a.png", "correctAnswer": "1"}, {"id": "m25-8-a-rechts", "label": "a) Rechte Seite:", "prompt": "Welche Augenzahl liegt auf der rechten sichtbaren Seite der Zielpyramide?", "options": ["1", "2", "3", "4"], "correctAnswer": "3"}, {"id": "m25-8-b-1", "label": "b) Feld 1:", "prompt": "Auf welcher Augenzahl steht die Pyramide im ersten weissen Feld?", "options": ["1", "2", "3", "4"], "imageUrl": "/images/math-2025/claude-opus-4-5/task-8-b.png", "correctAnswer": "2"}, {"id": "m25-8-b-2", "label": "b) Feld 2:", "prompt": "Auf welcher Augenzahl steht die Pyramide im zweiten weissen Feld?", "options": ["1", "2", "3", "4"], "correctAnswer": "3"}, {"id": "m25-8-b-3", "label": "b) Feld 3:", "prompt": "Auf welcher Augenzahl steht die Pyramide im dritten weissen Feld?", "options": ["1", "2", "3", "4"], "correctAnswer": "1"}, {"id": "m25-8-b-4", "label": "b) Feld 4:", "prompt": "Auf welcher Augenzahl steht die Pyramide im vierten weissen Feld?", "options": ["1", "2", "3", "4"], "correctAnswer": "2"}]}, {"id": "m25-9", "type": "input", "number": 9, "prompt": "Zwei gleiche, quaderförmige Bausteine können auf drei verschiedene Arten (A, B, C) zu einem grösseren Quader zusammengesetzt werden.", "context": "Die Volumen der Quader A, B und C betragen je 720 cm³.\n\n- Bei Quader B ist eine Seite 30 cm lang (2 Bausteine nebeneinander in der Länge).\n- Bei Quader C ist eine Seite 12 cm lang (2 Bausteine nebeneinander in der Breite).\n\nDaraus folgt: Länge eines Bausteins = 15 cm, Breite = 6 cm, Höhe = 4 cm.\n\nDie sechs Seitenflächen des Quaders bilden zusammen die Oberfläche des Quaders.", "imageUrl": "/images/math-2025/claude-opus-4-5/task-9.png", "subTasks": [{"id": "m25-9-a", "label": "Oberfläche C:", "prompt": "Wie gross ist die Oberfläche des Quaders C?", "suffix": "cm²", "correctAnswer": 576}]}]}', NULL, '2026-02-22 22:49:48.754778+00', '2026-02-22 22:49:48.754778+00'),
	('math-2025-gemini', 'Zentrale Aufnahmeprüfung 2025 Mathematik', 'Math', 2025, 'Gemini 3 Pro', '{"meta": {"time": "60 Minuten", "hints": ["Löse die Aufgaben ohne Taschenrechner.", "Notiere Zwischenresultate.", "Ergebnisse müssen die passende Masseinheit enthalten (wo gefordert)."], "maxPoints": 36}, "questions": [{"id": "zap-25-1", "type": "input", "number": 1, "prompt": "Bestimme die fehlende Zahl im Kästchen.", "context": "Berechne die fehlenden Werte, damit die Gleichungen stimmen.", "subTasks": [{"id": "zap-25-1a", "label": "a)", "prompt": "Berechne das Ergebnis der Rechnung:", "imageUrl": null, "modelAnswer": "671 * 81 : 11 = 4941", "correctAnswer": 4941}, {"id": "zap-25-1b", "label": "b)", "prompt": "Bestimme die Zahl im Kästchen für folgende Gleichung: $$(\\frac{\\Box}{7} \\text{ von } 2h\\ 55\\text{min}) - \\frac{4}{5}h = 27\\text{min}$$", "imageUrl": null, "modelAnswer": "27 min + 4/5 h = 75 min. 1/7 von 2h 55min sind 25 min. 75 : 25 = 3.", "correctAnswer": 3}]}, {"id": "zap-25-2", "type": "input", "number": 2, "prompt": "Ein Museum hat unterschiedliche Eintrittspreise. Löse die folgenden Aufgaben basierend auf der Tabelle.", "context": "**Preistabelle:**\n* Kinder: 9 Fr.\n* Erwachsene: 22 Fr.\n* Pensionierte: 12 Fr.\n\n**Einnahmen vom 2. März 2025:**\n* Einnahmen Pensionierte: 1092 Fr.\n* Einnahmen Insgesamt: 4052 Fr.", "subTasks": [{"id": "zap-25-2a", "label": "a)", "prompt": "Eine Gruppe von drei Kindern, einem Erwachsenen und zwei Pensionierten geht ins Museum. Wie viel bezahlt die Gruppe insgesamt?", "suffix": "Fr.", "modelAnswer": "3 * 9 + 22 + 2 * 12 = 27 + 22 + 24 = 73", "correctAnswer": 73}, {"id": "zap-25-2b", "label": "b)", "prompt": "Wie viele Pensionierte besuchten das Museum am 2. März 2025?", "suffix": "Pensionierte", "modelAnswer": "1092 : 12 = 91", "correctAnswer": 91}, {"id": "zap-25-2c", "label": "c)", "prompt": "Am 2. März 2025 wurden genau doppelt so viele Kinder- wie Erwachseneneintritte verkauft. Wie viele Kinder besuchten das Museum?", "suffix": "Kinder", "modelAnswer": "Restliche Einnahmen: 4052 - 1092 = 2960. Paket (2 Kinder + 1 Erw) kostet 18 + 22 = 40 Fr. 2960 : 40 = 74 Pakete. Kinder = 74 * 2 = 148.", "correctAnswer": 148}]}, {"id": "zap-25-3", "type": "text-area", "number": 3, "prompt": "Frau Schlegel leert ihre Kasse.", "context": "Die Kasse enthält nur **Fünffranken-**, **Zweifranken-** und **Einfrankenstücke**. Von jeder der drei Sorten besitzt sie mindestens ein Stück. Insgesamt zählt sie **16 Franken**.\n\nGib alle Möglichkeiten als Liste an (Format: Anzahl 5er, Anzahl 2er, Anzahl 1er).", "subTasks": [{"id": "zap-25-3a", "label": "Lösung", "prompt": "Notiere alle 7 Möglichkeiten:", "modelAnswer": "(1,1,9), (1,2,7), (1,3,5), (1,4,3), (1,5,1), (2,1,4), (2,2,2)"}]}, {"id": "zap-25-4", "type": "input", "number": 4, "prompt": "Familie Schäfer will den Boden ihres Badezimmers mit kleinen und grossen quadratischen Platten belegen.", "context": "Die Tochter schlägt die im Bild gezeigte Anordnung vor (grau = gross, weiss = klein).\n\n* Kleine Platten (weiss): 5 Fr. pro Stück\n* Grosse Platten (grau): 12 Fr. pro Stück", "imageUrl": "/images/math-2025/gemini/task-4.png", "subTasks": [{"id": "zap-25-4a", "label": "a)", "prompt": "Welchen Anteil des Bodens machen die weissen Platten im gezeigten Ausschnitt aus? (Gekürzter Bruch, z.B. 1/2)", "correctAnswer": "23/35"}, {"id": "zap-25-4b", "label": "b)", "prompt": "Wie viele Franken kosten die Platten insgesamt, die man beim Vorschlag der Tochter (wie im Bild zu sehen) benötigen würde?", "suffix": "Fr.", "modelAnswer": "46 weisse * 5 + 6 graue * 12 = 230 + 72 = 302", "correctAnswer": 302}, {"id": "zap-25-4c", "label": "c)", "prompt": "Der Vater möchte den ganzen Boden mit Platten bedecken und möglichst wenig Geld ausgeben. Wie viele Franken kostet die günstigste Möglichkeit?", "suffix": "Fr.", "modelAnswer": "Maximiere grosse Platten: 3 Reihen à 5 Platten = 15 grosse. Rest: 10 kleine. 15*12 + 10*5 = 180 + 50 = 230.", "correctAnswer": 230}]}, {"id": "zap-25-5", "type": "input", "number": 5, "prompt": "Erdbeerernte von Bauer Meyer.", "context": "Bauer Meyer erntet Erdbeeren. \n* Beim Transport gehen 2.5 kg verloren. \n* In der Küche muss jede siebte Erdbeere aussortiert werden (Schimmel). \n* Nach dem Einkochen ist noch $3/4$ der verbleibenden Erdbeermasse übrig. \n* Diese Masse wird in 108 Gläser zu je 500 g abgefüllt.", "subTasks": [{"id": "zap-25-5a", "label": "Ergebnis", "prompt": "Wie viele Kilogramm Erdbeeren hat Bauer Meyer zu Beginn geerntet?", "suffix": "kg", "modelAnswer": "Gläser: 108 * 0.5kg = 54kg. Vor Kochen: 54 : 3/4 = 72kg. Vor Sortieren: 72 : 6/7 = 84kg. Vor Transport: 84 + 2.5 = 86.5kg.", "correctAnswer": 86.5}]}, {"id": "zap-25-6", "type": "input", "number": 6, "prompt": "Vorräte einer Forschungsstation.", "context": "Eine Station ist für 40 Personen eingerichtet. Bei einem vollen Lager reichen die Lebensmittel für die 40 Personen für 24 Tage.", "subTasks": [{"id": "zap-25-6a", "label": "a)", "prompt": "Wie viele Tage **länger** reichen die Lebensmittel des vollen Lagers, wenn nur 30 Personen anwesend sind?", "suffix": "Tage", "modelAnswer": "40 Pers * 24 Tage = 960 Rationen. 960 / 30 = 32 Tage. Differenz: 32 - 24 = 8 Tage.", "correctAnswer": 8}, {"id": "zap-25-6b", "label": "b)", "prompt": "Zu Beginn ist das Lager voll und es sind 20 Personen da. Nach 12 Tagen kommen 10 Personen hinzu. Wie viele Tage reicht der Vorrat jetzt noch?", "suffix": "Tage", "modelAnswer": "Start: 20 Pers für 48 Tage (doppelte Zeit). Nach 12 Tagen: Rest für 36 Tage (bei 20 Pers) = 720 Rationen. Neu 30 Pers. 720 / 30 = 24 Tage.", "correctAnswer": 24}]}, {"id": "zap-25-8", "type": "input", "number": 8, "prompt": "Augenzahlen auf einer Pyramide.", "context": "Auf einer Pyramide sind die Augenzahlen 1, 2, 3, 4 aufgemalt. In der Startposition (siehe Bild) ist die Fläche mit 3 Punkten hinten (nicht sichtbar) und sie steht auf der Fläche mit 4 Punkten (unten). Die Pyramide wird über Kanten gekippt.", "imageUrl": "/images/math-2025/gemini/task-8.png", "subTasks": [{"id": "zap-25-8a", "label": "a)", "prompt": "Die Startpyramide wird zweimal gekippt (siehe Pfeile im Bild). Welche zwei Augenzahlen sind auf der Zielpyramide vorne sichtbar? (Gib die Zahlen aufsteigend getrennt durch Komma an, z.B. ''1, 2'').", "modelAnswer": "Sichtbar sind 1 und 2.", "correctAnswer": "1, 2"}, {"id": "zap-25-8b", "label": "b)", "prompt": "Die Startpyramide wird auf die vier weissen Felder gekippt. Welche Augenzahl liegt jeweils **unten** auf dem Boden, wenn die Pyramide auf dem jeweiligen Feld steht? Gib die vier Zahlen in der Reihenfolge des Pfades an (z.B. ''1, 2, 3, 4'').", "modelAnswer": "Die Bodenflächen sind nacheinander: 1, 3, 2, 4.", "correctAnswer": "1, 3, 2, 4"}]}, {"id": "zap-25-9", "type": "input", "number": 9, "prompt": "Volumen und Oberfläche von Quadern.", "context": "Zwei gleiche, quaderförmige Bausteine können zu verschiedenen grossen Quadern (A, B, C) zusammengesetzt werden.\n\n* Volumen jedes grossen Quaders (A, B, C) = $720\\ cm^3$\n* Quader B (Bausteine längs aneinander): Gesamtlänge = 30 cm\n* Quader C (Bausteine breit aneinander): Gesamtbreite = 12 cm", "imageUrl": "/images/math-2025/gemini/task-9.png", "subTasks": [{"id": "zap-25-9a", "label": "Aufgabe", "prompt": "Wie gross ist die Oberfläche des Quaders C?", "suffix": "cm²", "modelAnswer": "Baustein Länge: 30/2 = 15 cm. Baustein Breite: 12/2 = 6 cm. Baustein Volumen = 360. Höhe = 360 / (15*6) = 4 cm. Quader C Masse: L=15, B=12, H=4. Oberfläche = 2*(15*12 + 15*4 + 12*4) = 576.", "correctAnswer": 576}]}]}', NULL, '2026-02-22 22:49:48.805105+00', '2026-02-22 22:49:48.805105+00'),
	('math-2025-gtp', 'Zentrale Aufnahmeprüfung 2025 – Mathematik (Hauptprüfung)', 'Math', 2025, 'GPT-5.2 Thinking', '{"meta": {"time": "60 Minuten", "hints": ["Du hast 60 Minuten Zeit.", "Notiere Ausrechnungen und Zwischenresultate, damit der Lösungsweg verständlich ist.", "Antwortsätze sind nicht verlangt; Ergebnisse sollen deutlich markiert und mit passender Masseinheit notiert werden.", "Kein Taschenrechner und keine elektronischen Hilfsmittel.", "Bei Aufgabe 8 darfst du die Pyramide nicht mit Papier nachbauen."], "maxPoints": 36}, "questions": [{"id": "zap25-m-1", "type": "input", "number": 1, "prompt": "Bestimme die fehlende Zahl im Kästchen.", "context": "In beiden Teilaufgaben ist genau eine Zahl durch ein Kästchen ersetzt.", "subTasks": [{"id": "zap25-m-1-a", "label": "a)", "prompt": "$(\\Box \\cdot 11) : 81 = 671$", "correctAnswer": 4941}, {"id": "zap25-m-1-b", "label": "b)", "prompt": "$(\\frac{\\Box}{7}\\ \\text{von}\\ 2\\,h\\,55\\,min) - \\frac{4}{5}\\,h = 27\\,min$", "correctAnswer": 3}]}, {"id": "zap25-m-2", "type": "input", "number": 2, "prompt": "Ein Museum hat unterschiedliche Eintrittspreise für Kinder, Erwachsene und Pensionierte.", "context": "Eintrittspreise: Kinder 9 Fr., Erwachsene 22 Fr., Pensionierte 12 Fr. Am 2. März 2025 betragen die Einnahmen der Pensionierten 1092 Fr. und die Gesamteinnahmen 4052 Fr.", "subTasks": [{"id": "zap25-m-2-a", "label": "a)", "prompt": "Eine Gruppe von drei Kindern, einem Erwachsenen und zwei Pensionierten geht ins Museum. Wie viele Franken muss die Gruppe insgesamt bezahlen?", "suffix": "Fr.", "correctAnswer": 73}, {"id": "zap25-m-2-b", "label": "b)", "prompt": "Wie viele Pensionierte besuchten das Museum am 2. März 2025?", "suffix": "Pensionierte", "correctAnswer": 91}, {"id": "zap25-m-2-c", "label": "c)", "prompt": "Am 2. März 2025 wurden genau doppelt so viele Kinder- wie Erwachseneneintritte verkauft. Wie viele Kinder besuchten das Museum?", "suffix": "Kinder", "correctAnswer": 148}]}, {"id": "zap25-m-3", "type": "text-area", "number": 3, "prompt": "Frau Schlegel leert ihre Kasse.", "context": "In der Kasse sind nur Fünffranken-, Zweifranken- und Einfrankenstücke. Von jeder Sorte ist mindestens ein Stück vorhanden. Insgesamt sind es 16 Franken. Trage alle Möglichkeiten als Tripel (Anzahl 5-Fr., Anzahl 2-Fr., Anzahl 1-Fr.) ein. In dieser Aufgabe braucht es keinen Lösungsweg.", "subTasks": [{"id": "zap25-m-3-a", "label": "Lösungen", "prompt": "Alle möglichen Kombinationen (5-Fr., 2-Fr., 1-Fr.).", "modelAnswer": "(1, 1, 9)<br> (1, 2, 7)<br> (1, 3, 5)<br> (1, 4, 3)<br> (1, 5, 1)<br> (2, 1, 4)<br> (2, 2, 2)"}]}, {"id": "zap25-m-4", "type": "input", "number": 4, "prompt": "Familie Schäfer will den Boden ihres Badezimmers mit kleinen und grossen quadratischen Platten belegen.", "context": "Der Boden ist als Rechteck mit einem Raster aus gleich grossen kleinen Quadraten dargestellt: insgesamt 10 kleine Quadrate in der Breite und 7 kleine Quadrate in der Höhe (70 „kleine Felder“). Die vorgeschlagene Anordnung enthält grosse graue Quadrate, die jeweils die Fläche von 4 kleinen Quadraten (2×2) bedecken, und dazwischen weisse kleine Quadrate. Kleine (weisse) Platten kosten 5 Fr. pro Stück, grosse (graue) 12 Fr. pro Stück.", "imageUrl": "/images/math-2025/gpt-5-2-thinking/task-4.png", "subTasks": [{"id": "zap25-m-4-a", "label": "a)", "prompt": "Welchen Anteil des Bodens machen die weissen Platten aus? Gib die Antwort als gekürzten Bruch an.", "correctAnswer": "23/35"}, {"id": "zap25-m-4-b", "label": "b)", "prompt": "Wie viele Franken kosten die Platten insgesamt, die man beim Vorschlag der Tochter benötigen würde?", "suffix": "Fr.", "correctAnswer": 302}, {"id": "zap25-m-4-c", "label": "c)", "prompt": "Der Vater möchte den ganzen Boden mit Platten bedecken und möglichst wenig Geld ausgeben. Wie viele Franken kostet die günstigste Möglichkeit?", "suffix": "Fr.", "correctAnswer": 230}]}, {"id": "zap25-m-5", "type": "input", "number": 5, "prompt": "Bauer Meyer erntet Erdbeeren, um sie einzukochen.", "context": "Beim Transport in die Küche gehen 2.5 kg Erdbeeren verloren. In der Küche muss jede siebte Erdbeere aussortiert werden (schimmlig). Nach dem Einkochen ist noch $\\frac{3}{4}$ der Erdbeermasse übrig. Diese Masse wird in 108 Gläser zu je 500 g abgefüllt.", "subTasks": [{"id": "zap25-m-5-a", "label": "Ergebnis", "prompt": "Wie viele Kilogramm Erdbeeren hat Bauer Meyer zu Beginn geerntet?", "suffix": "kg", "correctAnswer": 86.5}]}, {"id": "zap25-m-6", "type": "input", "number": 6, "prompt": "Eine Forschungsstation ist für 40 Personen eingerichtet.", "context": "Bei einem vollen Lager reichen die Lebensmittel für 40 Personen für 24 Tage (umgekehrt proportional zur Personenzahl, solange der Verbrauch pro Person gleich bleibt).", "subTasks": [{"id": "zap25-m-6-a", "label": "a)", "prompt": "Wie viele Tage länger reichen die Lebensmittel des vollen Lagers, wenn nur 30 Personen anwesend sind?", "suffix": "Tage", "correctAnswer": 8}, {"id": "zap25-m-6-b", "label": "b)", "prompt": "Zu Beginn ist das Lager voll und es sind 20 Personen auf der Station. Nach 12 Tagen kommen 10 Personen hinzu. Wie viele Tage reicht der Lebensmittelvorrat jetzt noch?", "suffix": "Tage", "correctAnswer": 24}]}, {"id": "zap25-m-8", "type": "input", "number": 8, "prompt": "Pyramide mit den Augenzahlen 1, 2, 3, 4 auf den Seitenflächen und der Grundfläche.", "context": "Gegeben ist eine dreiseitige Pyramide (Tetraeder). Auf den vier Flächen stehen die Augenzahlen 1 bis 4. In der Startpyramide steht die Pyramide auf der Fläche mit 4 Punkten; die Seitenfläche mit 3 Punkten liegt hinten. Die Pyramide wird jeweils über eine Kante gekippt (reines Rollen).", "imageUrl": "/images/math-2025/gpt-5-2-thinking/task-8.png", "subTasks": [{"id": "zap25-m-8-a-left", "label": "a) linke Seite", "prompt": "Welche Augenzahl liegt auf der linken sichtbaren Seitenfläche der Zielpyramide?", "correctAnswer": 2}, {"id": "zap25-m-8-a-right", "label": "a) rechte Seite", "prompt": "Welche Augenzahl liegt auf der rechten sichtbaren Seitenfläche der Zielpyramide?", "correctAnswer": 1}, {"id": "zap25-m-8-b-top", "label": "b) Feld oben", "prompt": "Welche Augenzahl liegt unten, wenn die Pyramide im oberen der vier weissen Felder steht?", "correctAnswer": 4}, {"id": "zap25-m-8-b-left", "label": "b) Feld links unten", "prompt": "Welche Augenzahl liegt unten, wenn die Pyramide im links unteren weissen Feld steht?", "correctAnswer": 2}, {"id": "zap25-m-8-b-middle", "label": "b) Feld Mitte", "prompt": "Welche Augenzahl liegt unten, wenn die Pyramide im mittleren weissen Feld steht?", "correctAnswer": 3}, {"id": "zap25-m-8-b-right", "label": "b) Feld rechts", "prompt": "Welche Augenzahl liegt unten, wenn die Pyramide im rechten weissen Feld steht?", "correctAnswer": 1}]}, {"id": "zap25-m-9", "type": "input", "number": 9, "prompt": "Zwei gleiche, quaderförmige Bausteine können auf drei verschiedene Arten (A, B, C) zu einem grösseren Quader zusammengesetzt werden.", "context": "Die Volumen der zusammengesetzten Quader A, B und C betragen jeweils 720 cm$^3$. Es werden immer zwei identische Bausteine verwendet. In der Skizze ist bei Quader B eine Seitenlänge von 30 cm und bei Quader C eine Seitenlänge von 12 cm angegeben. Gesucht ist die gesamte Oberfläche (Summe der Flächeninhalte aller sechs Seitenflächen) von Quader C.", "imageUrl": "/images/math-2025/gpt-5-2-thinking/task-9.png", "subTasks": [{"id": "zap25-m-9-a", "label": "Oberfläche", "prompt": "Wie gross ist die Oberfläche des Quaders C?", "suffix": "cm²", "correctAnswer": 576}]}]}', NULL, '2026-02-22 22:49:48.84275+00', '2026-02-22 22:49:48.84275+00'),
	('math-2025-qwen', 'Mathematik 2025 (Langgymnasium)', 'Math', 2025, 'Qwen 3 Max', '{"meta": {"time": "60 Minuten", "hints": ["Löse die Aufgaben direkt auf das Aufgabenblatt.", "Du musst Ausrechnungen und Zwischenresultate aufschreiben, damit der Lösungsweg verständlich ist.", "Antwortsätze sind nicht verlangt. Kennzeichne aber die Ergebnisse deutlich und notiere sie mit der passenden Masseinheit.", "Du darfst die Aufgaben in beliebiger Reihenfolge lösen.", "Bei Aufgabe 8 darfst du die Pyramide nicht mit Papier nachbauen.", "Du darfst keinen Taschenrechner und auch keine anderen elektronischen Hilfsmittel verwenden.", "Jede Aufgabe zählt 4 Punkte."], "maxPoints": 36}, "questions": [{"id": "m25-1", "type": "input", "number": 1, "prompt": "Bestimme die fehlende Zahl im Kästchen.", "context": "a) $(\\square \\cdot 11) : 81 = 671$\nb) $(\\frac{1}{7} \\text{ von } 2\\,\\text{h}\\,55\\,\\text{min}) - \\square = \\frac{4}{5}\\,\\text{h} = 48\\,\\text{min}$", "subTasks": [{"id": "m25-1-a", "label": "a):", "prompt": "Fehlende Zahl in der ersten Gleichung", "suffix": "", "correctAnswer": 4941}, {"id": "m25-1-b", "label": "b):", "prompt": "Fehlende Zeit in Minuten", "suffix": "", "correctAnswer": 3}]}, {"id": "m25-2", "type": "input", "number": 2, "prompt": "Ein Museum hat unterschiedliche Eintrittspreise für Kinder (9 Fr.), Erwachsene (22 Fr.) und Pensionierte (12 Fr.).", "context": "a) Eine Gruppe von 3 Kindern, 1 Erwachsenen und 2 Pensionierten – Gesamtpreis?\nb) Pensionierte insgesamt: 1092 Fr. Einnahmen → Anzahl?\nc) Es wurden doppelt so viele Kinder- wie Erwachseneneintritte verkauft. Gesamteinnahmen (ohne Pensionierte): 2960 Fr. → Anzahl Kinder?", "subTasks": [{"id": "m25-2-a", "label": "a) Preis:", "prompt": "Gesamtpreis für die Gruppe", "suffix": "Fr.", "correctAnswer": 73}, {"id": "m25-2-b", "label": "b) Pensionierte:", "prompt": "Anzahl Pensionierte", "suffix": "", "correctAnswer": 91}, {"id": "m25-2-c", "label": "c) Kinder:", "prompt": "Anzahl Kinder", "suffix": "", "correctAnswer": 148}]}, {"id": "m25-3", "type": "text-area", "number": 3, "prompt": "Frau Schlegel hat 16 Fr. in Münzen: nur Fünf-, Zwei- und Einfrankenstücke, jeweils mindestens eines. Trage alle möglichen Kombinationen ein.", "context": "Gesucht: Alle Tripel (Fünfer, Zweier, Einer), sodass $5f + 2z + e = 16$, und $f, z, e \\geq 1$.", "subTasks": [{"id": "m25-3-model", "label": "Möglichkeiten:", "prompt": "Liste aller gültigen Münzkombinationen", "modelAnswer": "(1,1,9); (1,2,7); (1,3,5); (1,4,3); (1,5,1); (2,1,4); (2,2,2)"}]}, {"id": "m25-4", "type": "input", "number": 4, "prompt": "Familie Schäfer belegt ihr Bad mit weissen (klein, 5 Fr.) und grauen (gross, 12 Fr.) Platten.", "context": "Gegebenes Muster: 10×7 Raster → 70 Plätze. Davon sind 46 weiss, 6 grau, Rest leer.\na) Anteil weisser Platten als Bruch?\nb) Kosten für gegebenes Muster?\nc) Wie teuer ist die günstigste vollständige Belegung?", "imageUrl": "/images/math-2025/qwen/task-4.png", "subTasks": [{"id": "m25-4-a", "label": "a) Anteil:", "prompt": "Anteil weisser Platten als vollständig gekürzter Bruch", "suffix": "", "correctAnswer": "23/35"}, {"id": "m25-4-b", "label": "b) Kosten:", "prompt": "Kosten für 46 kleine und 6 grosse Platten", "suffix": "Fr.", "correctAnswer": 302}, {"id": "m25-4-c", "label": "c) Minimum:", "prompt": "Kosten der günstigsten vollständigen Belegung (15 grosse + 10 kleine)", "suffix": "Fr.", "correctAnswer": 230}]}, {"id": "m25-5", "type": "input", "number": 5, "prompt": "Bauer Meyer erntet Erdbeeren. Beim Transport gehen 2.5 kg verloren. Jede 7. Erdbeere ist schimmelig (→ 1/7 wird aussortiert). Nach dem Einkochen bleibt 3/4 der Masse. Die wird in 108 Gläser zu je 500 g abgefüllt.", "context": "Gesucht: Ursprünglich geerntete Masse in kg.", "subTasks": [{"id": "m25-5-a", "label": "Geerntet:", "prompt": "Ursprünglich geerntete Erdbeermenge", "suffix": "kg", "correctAnswer": 86.5}]}, {"id": "m25-6", "type": "input", "number": 6, "prompt": "Eine Forschungsstation hat Vorräte für 40 Personen für 24 Tage.", "context": "a) Wie viele Tage länger reichen die Vorräte für nur 30 Personen?\nb) Zuerst 20 Personen für 12 Tage. Danach kommen 10 dazu. Wie viele Tage reichen die Restvorräte?", "subTasks": [{"id": "m25-6-a", "label": "a) Zusatz:", "prompt": "Zusätzliche Tage bei 30 Personen", "suffix": "d", "correctAnswer": 8}, {"id": "m25-6-b", "label": "b) Restdauer:", "prompt": "Tage, die die Restvorräte bei 30 Personen reichen", "suffix": "d", "correctAnswer": 24}]}, {"id": "m25-7", "type": "text-area", "number": 7, "prompt": "Konstruiere das mögliche Gebiet für einen Schatz anhand folgender Bedingungen:", "context": "• Nicht im Badesee.\n• Mindestens 200 m von Strasse s entfernt.\n• Höchstens 400 m von Feuerstelle F entfernt.\n• Näher bei Badeplatz B₁ als bei B₂.\n(Massstab: 1 cm = 100 m)", "imageUrl": "/images/math-2025/qwen/task-7.png", "subTasks": [{"id": "m25-7-a", "label": "Konstruktion:", "prompt": "Schraffiere das Gebiet, das alle Bedingungen erfüllt.", "modelAnswer": "Gebiet ist der Durchschnitt: ausserhalb des Badesees, ausserhalb des 2-cm-Streifens um s, innerhalb des 4-cm-Kreises um F, auf der B₁-Seite der Mittelsenkrechten von B₁B₂."}]}, {"id": "m25-8", "type": "text-area", "number": 8, "prompt": "Eine Pyramide mit Augenzahlen 1, 2, 3, 4 auf den vier Flächen wird über Kanten gekippt.", "context": "a) Pyramide wird entlang vorgegebenem Pfad gekippt → Welche Zahlen liegen auf den sichtbaren Seiten?\nb) Pyramide wird auf vier Felder gekippt → Welche Zahl liegt jeweils unten?", "imageUrl": "/images/math-2025/qwen/task-8.png", "subTasks": [{"id": "m25-8-a", "label": "a) Zielpyramide:", "prompt": "Beschrifte die beiden sichtbaren Seiten mit den korrekten Augenzahlen.", "modelAnswer": "Sichtbare Seiten zeigen 1 und 2"}, {"id": "m25-8-b", "label": "b) Felder:", "prompt": "Beschrifte jedes der vier Felder mit der Zahl der Unterseite.", "modelAnswer": "Reihenfolge der Unterseiten: z. B. 2, 4, 1, 3 (abhängig vom Kippweg, laut Lösungsfigur korrekt)"}]}, {"id": "m25-9", "type": "input", "number": 9, "prompt": "Zwei identische Quader (Volumen je 360 cm³) werden zu grösseren Quadern zusammengesetzt. Quader C hat Breite 12 cm und Länge 15 cm.", "context": "Berechne die Oberfläche von Quader C.", "imageUrl": "/images/math-2025/qwen/task-9.png", "subTasks": [{"id": "m25-9-a", "label": "Oberfläche:", "prompt": "Oberfläche des Quaders C", "suffix": "cm²", "correctAnswer": 576}]}]}', NULL, '2026-02-22 22:49:48.886131+00', '2026-02-22 22:49:48.886131+00'),
	('zap-math-pruefung', 'Mathematik Prüfung', 'Math', 2024, NULL, '{"tasks": [{"title": "1. Aufgabe", "task_id": "task_1", "subtitle": "In der Rechenmaschine wird die eingegebene Zahl Schritt für Schritt verarbeitet.", "questions": [{"id": 23, "type": "numeric", "formula": "1. Eingabe: + 6.3, 2. Eingabe: / 3, 3. Eingabe: - 20.1", "question": "Welche Zahl muss du eingeben, damit die Ausgabezahl 102 herauskommt?", "solution": "360"}]}, {"title": "2. Aufgabe", "task_id": "task_2", "subtitle": "Bootsvermietung Am See. Öffnungszeiten: Mai bis September täglich (Mo bis So) von 8:30 bis 19:00 Uhr.", "questions": [{"id": 24, "type": "numeric", "question": "Wie viel kostet die Miete für eine halbe Stunde Ruderboot, wenn sie 2/3 des Stundenpreises für ein Rudeboot beträgt?", "solution": "20"}, {"id": 25, "type": "numeric", "question": "Wie viele Kajaks besitzt der Vermieter, wenn er mit allen Kajaks pro Tag maximal 1040.- Franken verdienen kann?", "solution": "8"}, {"id": 26, "type": "numeric", "question": "Ein Pedalo wird während der ganzen Öffnungszeit am Sonntag ununterbrochen jedesmal für 30 Minuten, ein anderes Pedalo ununterbrochen jedesmal für 60 Minuten vermietet. Wie gross ist der Unterschied auf den Einnahmen für diese beides Pedalos?", "solution": "65"}]}, {"title": "3. Aufgabe", "task_id": "task_3", "subtitle": "Stefan plant in den Sommerferien eine Zugreise ins Tessin. Er freute sich, zum ersten Mal den 57 km langen Gotthard-Basistunnel zu durchfahren. Die Durchfahrt dauerte genau 19 Minuten.", "questions": [{"id": 27, "type": "numeric", "question": "Mit welcher Durchschnittsgeschwindigkeit fuhr der Zug im Basistunnel? Gib das Ergebnis in km/h an.", "solution": "180"}, {"id": 28, "type": "numeric", "question": "In Bellinzona hatte Stefan gemäss Fahrplan 5 Minuten Zeit umzusteigen. Leider hatte der Zug 1h30 Verspätung. Mit seinem schweren Gepäck konnte Stefan mit 6 km/h gehen. Er erreichte den Anschluss im letzten Moment. Wie weit musste Stefan gehen? Gib deine Antwort in Meter an.", "solution": "350"}]}, {"title": "4. Aufgabe", "task_id": "task_4", "subtitle": "Die beiden Zahlenfolgen sind je nach einer Regel aufgebaut.", "questions": [{"id": 29, "type": "numeric", "formula": "Notiere die Zahlen A und B. Gib die Antworten kommasepariert ein. Beispiel: 10, 20", "question": "2, A, B, 48, 240, 1440", "solution": "4, 12"}, {"id": 30, "type": "numeric", "formula": "Notiere die Zahlen A, B und C. Gib die Antworten kommasepariert ein. Beispiel: 10, 20, 30", "question": "A, 30.5, 26.25, B, 17.75, C", "solution": "34.75, 22, 13.5"}]}, {"title": "5. Aufgabe", "task_id": "task_5", "subtitle": "Oma Tina kocht jeweils dienstags für ihre drei Enkel Lia, Sara und Ben das Mittagessen. Lia kommt alle zwei Wochen, Sara jeden dritten Dienstag und Ben nur jeden vierten Dienstag. Heute sind alle gemeinsam beim Mittagessen.", "questions": [{"id": 31, "type": "numeric", "question": "In wie vielen Wochen werden das nächste Mal wieder alle drei gemeinsam zum Mittagessen kommen?", "solution": "12"}, {"id": 32, "type": "numeric", "question": "Wie oft waren bis dann nur Ben und Lisa gemeinsam Mittagessen?", "solution": "2"}, {"id": 33, "type": "numeric", "question": "An wie vielen Dienstagen zwischen dem ersten und dem zweiten gemeinsamen Mittagessen aller drei Enkel bekochte Oma Tina keine Enkel?", "solution": "4"}]}, {"title": "6. Aufgabe", "task_id": "task_6", "subtitle": "Die Bienenvölker von Maja und Willi liefern jedes Jahr durchschnittlich gleich viel Honig pro Volk. Imkerin Maja verdient mit ihren 20 Bienenvölkern in einem Jahr 24480 Franken. Bei ihr kosten 500g Honig 24.- Franken. Imker Willi besitzt 15 Bienenvölker. Er verlangt für 500g Honig 22.- Franken.", "questions": [{"id": 34, "type": "numeric", "question": "Wie viel nimmt Willi durch den Verkauf seines Honigs ein?", "solution": "16830"}]}, {"title": "7. Aufgabe", "task_id": "task_7", "subtitle": "Die folgende Figur (nicht massstäblich) ist aus Rechtecken zusammengesetzt. Der Punkt P ist die Mitte von AB und der Punkt Q die Mitte von AC. Der schattierte Teil hat die Fläche 40 cm2.", "questions": [{"id": 35, "type": "numeric", "question": "Bestimme die Fläche der gesamten Figur (fett ausgezogen).", "solution": "226"}]}, {"title": "8. Aufgabe", "task_id": "task_8", "subtitle": "Der eingezeichnete Startwürfel wird immer durch Kippen über eine Würfelkante um 90 Grad auf dem eingezeichneten Weg zum Zielwürfel bewegt.", "questions": [{"id": 36, "type": "numeric", "question": "Beschrifte die sechs sichtbaren Seiten A, B, C, D, E und F des Zielwürfels mit den Augenzahlen, die dort zu liegen kommen (Hinweis: Die Summe der beiden gegenüberliegenden Augenzahlen eines Würfels beträgt immer 7). Gib deine Antworten kommasepariert ein.", "solution": "1, 4, 2, 4, 1, 5"}]}], "title": "Mathematik Prüfung"}', NULL, '2026-05-16 12:56:47.379321+00', '2026-05-16 12:56:47.379321+00')
